     '[{"lat": 45.72556, "lng": 5.08111, "label": "letiště Lyon-Saint-Exupéry"}, {"lat": 45.75371, "lng": 4.82724, "label": "Bazilika Saint-Martin d''Ainay"}, {"lat": 45.76083, "lng": 4.82722, "label": "katedrála v Lyonu"}, {"lat": 45.76229, "lng": 4.82256, "label": "Bazilika Notre-Dame de Fourvière"}, {"lat": 45.81944, "lng": 4.6225, "label": "Sainte Marie de La Tourette"}, {"lat": 45.52417, "lng": 4.87306, "label": "Vienne Cathedral"}, {"lat": 45.523, "lng": 4.87072, "label": "Saint Peter''s church"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.72556,5.08111&destination=45.523,4.87072&travelmode=driving&waypoints=45.75371,4.82724%7C45.76083,4.82722%7C45.76229,4.82256%7C45.81944,4.6225%7C45.52417,4.87306', 'http://commons.wikimedia.org/wiki/Special:FilePath/Vue%20a%C3%A9rienne%20d%27une%20partie%20de%20l%27a%C3%A9roport%20de%20Lyon%20Saint-Exup%C3%A9ry%20et%20de%20la%20gare%20TGV%20%28septembre%202022%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vue%20a%C3%A9rienne%20d%27une%20partie%20de%20l%27a%C3%A9roport%20de%20Lyon%20Saint-Exup%C3%A9ry%20et%20de%20la%20gare%20TGV%20%28septembre%202022%29.jpg","http://commons.wikimedia.org/wiki/Special:FilePath/Lyon%202e%20-%20Basilique%20Saint-Martin%20d%27Ainay%20depuis%20la%20rue%20Bourgelat%20%28mars%202019%29.jpg","http://commons.wikimedia.org/wiki/Special:FilePath/007.%20Photo%20prise%20depuis%20les%20toits%20de%20la%20Basilique%20Notre-Dame%20de%20Fourvi%C3%A8re.JPG","http://commons.wikimedia.org/wiki/Special:FilePath/France-003038%20-%20Basilica%20of%20Notre-Dame%20de%20Fourvi%C3%A8re%20%2815939822990%29.jpg","http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20Saint-Maurice%20%28Vienne%2C%202022%29.jpg","http://commons.wikimedia.org/wiki/Special:FilePath/%C3%89glise%20Saint-Pierre%20de%20Vienne.jpg"}'::text[], '{"letiště Lyon-Saint-Exupéry","Bazilika Saint-Martin d''Ainay","katedrála v Lyonu","Bazilika Notre-Dame de Fourvière","Sainte Marie de La Tourette","Vienne Cathedral","Saint Peter''s church"}'::text[], '{"FR"}'::text[], false, 7099, 'approved', '{"en": {"name": "Wings & wheels: letiště Lyon-Saint-Exupéry and around", "description": "A points-of-interest ride in France: Lyon–Saint-Exupéry Airport, Basilica of Saint-Martin d''Ainay, Lyon Cathedral, Basilica of Notre-Dame de Fourvière…. 7 stops over roughly 100 km — reorder them in the app and navigate right away."}, "de": {"name": "Zu den Flugzeugen: letiště Lyon-Saint-Exupéry und Umgebung", "description": "Eine Tour zu Sehenswürdigkeiten in Frankreich: Flughafen Lyon Saint-Exupéry, Basilika Saint-Martin d’Ainay, Kathedrale von Lyon, Notre-Dame de Fourvière…. 7 Stopps auf rund 100 km — Reihenfolge in der App anpassbar, Navigation direkt aus der App."}, "pl": {"name": "Szlakiem samolotów: letiště Lyon-Saint-Exupéry i okolice", "description": "Wycieczka po ciekawych miejscach we Francji: Port lotniczy Lyon-Saint-Exupéry, Bazilika Saint-Martin d''Ainay, Katedra św. Jana Chrzciciela w Lyonie, Bazylika Notre-Dame de Fourvière…. Łącznie 7 przystanków na około 100 km — kolejność zmienisz w aplikacji i od razu nawigujesz."}, "nl": {"name": "Langs vliegtuigen: letiště Lyon-Saint-Exupéry en omgeving", "description": "Een rit langs bezienswaardigheden in Frankrijk: Luchthaven Lyon-Saint-Exupéry, Basilica of Saint-Martin d''Ainay, Kathedraal van Lyon, Notre-Dame de Fourvière…. 7 stops over zo''n 100 km — pas de volgorde aan in de app en navigeer direct."}, "es": {"name": "Tras los aviones: letiště Lyon-Saint-Exupéry y alrededores", "description": "Una ruta por puntos de interés en Francia: Aeropuerto de Lyon-Saint Exupéry, basílica de San Martín de Ainay, Catedral de Lyon, basílica Notre-Dame de Fourvière…. 7 paradas en unos 100 km; reordénalas en la app y navega al instante."}, "fr": {"name": "Sur la piste des avions : letiště Lyon-Saint-Exupéry et environs", "description": "Une virée entre points d''intérêt en France : aéroport Lyon-Saint-Exupéry, basilique Saint-Martin d''Ainay, primatiale Saint-Jean de Lyon, basilique Notre-Dame de Fourvière…. 7 arrêts sur environ 100 km — réorganisez-les dans l''app et lancez la navigation."}, "uk": {"name": "До літаків: letiště Lyon-Saint-Exupéry та околиці", "description": "Поїздка цікавими місцями у Франції: Ліон, Базиліка Сен-Мартен, Кафедральний собор Івана Хрестителя в Ліоні, Базиліка Нотр-Дам-де-Фурв''єр…. Загалом 7 зупинок на приблизно 100 км — порядок можна змінити в застосунку й одразу навігувати."}}'::jsonb);
end $$;
