  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Amsterdam-Schiphol', 'Letiště v Nizozemsku. Letecký cíl v Nizozemsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 52.3081, 4.76417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ams-above-2007.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ams-above-2007.jpg"}'::text[], 0, '{"en": {"name": "Amsterdam Schiphol Airport", "description": "Airport in Haarlemmermeer, Netherlands. An aviation sight in the Netherlands — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Schiphol", "description": "Internationaler Verkehrsflughafen der niederländischen Hauptstadt Amsterdam. Ein Luftfahrt-Ziel in den Niederlanden — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Amsterdam-Schiphol", "description": "Międzynarodowy port lotniczy Amsterdamu, największy w Holandii. Cel lotniczy w Holandii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Schiphol", "description": "Internationale luchthaven in Noord-Holland, Nederland. Een luchtvaartdoel in Nederland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Ámsterdam-Schiphol", "description": "Aeropuerto de los Países Bajos. Un destino aeronáutico en los Países Bajos: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport d''Amsterdam-Schiphol", "description": "Aéroport international desservant Amsterdam aux Pays-Bas. Un site aéronautique aux Pays-Bas — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Схіпгол", "description": "Аеропорт в Амстердамі. Авіаційна пам''ятка в Нідерландах — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Obranná linie Amsterdamu', 'Prstenec opevnění. Hrad či zámek v Nizozemsku — historická zastávka, která stojí za odbočku.', 52.37444, 4.89306, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fort%20bij%20Spijkerboor%20bovenzijde%20geschutskoepel.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fort%20bij%20Spijkerboor%20bovenzijde%20geschutskoepel.JPG"}'::text[], 1, '{"en": {"name": "Defence Line of Amsterdam", "description": "Fortification line in the Netherlands. A castle in the Netherlands — a historic stop worth the detour."}, "de": {"name": "Stellung von Amsterdam", "description": "Neuzeitlicher Verteidigungsring aus dem 19. Jahrhundert. Eine Burg bzw. ein Schloss in den Niederlanden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Holenderskie linie obrony wodnej", "description": "Zamek w Holandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Stelling van Amsterdam", "description": "Historische militaire verdedigingsgordel in Nederland. Een kasteel in Nederland — een historische stop die de omweg waard is."}, "es": {"name": "Línea de defensa de Ámsterdam", "description": "Un castillo en los Países Bajos: una parada histórica que merece el desvío."}, "fr": {"name": "ligne de défense d''Amsterdam", "description": "Dispositif militaire de protection. Un château aux Pays-Bas — une halte historique qui vaut le détour."}, "uk": {"name": "Захисні укріплення Амстердама", "description": "Замок в Нідерландах — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Weesp', 'Hrad či zámek v Nizozemsku — historická zastávka, která stojí za odbočku.', 52.3069, 5.0417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Weesp%20met%20Fort%20Ossenmarkt.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Weesp%20met%20Fort%20Ossenmarkt.jpg"}'::text[], 2, '{"en": {"name": "Weesp", "description": "Town and former municipality in the Netherlands. A castle in the Netherlands — a historic stop worth the detour."}, "de": {"name": "Weesp", "description": "Stadt und ehemalige Gemeinde in der niederländischen Provinz Nordholland. Eine Burg bzw. ein Schloss in den Niederlanden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Weesp", "description": "Miasto w Holandii. Zamek w Holandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Weesp", "description": "Plaats en voormalige gemeente in Noord-Holland, Nederland. Een kasteel in Nederland — een historische stop die de omweg waard is."}, "es": {"name": "Weesp", "description": "Municipio de los Países Bajos. Un castillo en los Países Bajos: una parada histórica que merece el desvío."}, "fr": {"name": "Weesp", "description": "Commune néerlandaise située en province de Hollande-Septentrionale. Un château aux Pays-Bas — une halte historique qui vaut le détour."}, "uk": {"name": "Весп", "description": "Муніципалітет у Нідерландах. Замок в Нідерландах — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Muiden', 'Obec v provincii Severní Holandsko. Hrad či zámek v Nizozemsku — historická zastávka, která stojí za odbočku.', 52.3292, 5.0714, 'http://commons.wikimedia.org/wiki/Special:FilePath/Muiden%20het%20slot%20en%20de%20Flevopolder.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Muiden%20het%20slot%20en%20de%20Flevopolder.jpg"}'::text[], 3, '{"en": {"name": "Muiden", "description": "Town in Gooise Meren, Netherlands. A castle in the Netherlands — a historic stop worth the detour."}, "de": {"name": "Muiden", "description": "Niederländische Stadt. Eine Burg bzw. ein Schloss in den Niederlanden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Muiden", "description": "Zamek w Holandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Muiden", "description": "Plaats in de Noord-Hollandse gemeente Gooise Meren, Nederland. Een kasteel in Nederland — een historische stop die de omweg waard is."}, "es": {"name": "Muiden", "description": "Municipio de los Países Bajos. Un castillo en los Países Bajos: una parada histórica que merece el desvío."}, "fr": {"name": "Muiden", "description": "Ville et ancienne commune néerlandaise. Un château aux Pays-Bas — une halte historique qui vaut le détour."}, "uk": {"name": "Мейден", "description": "Місто в Нідерландах. Замок в Нідерландах — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Naarden', 'Sídlo v provincii Severní Holandsko v Nizozemsku. Hrad či zámek v Nizozemsku — historická zastávka, která stojí za odbočku.', 52.29528, 5.16222, 'http://commons.wikimedia.org/wiki/Special:FilePath/30282-Vestingwerken%20en%20grachten%20van%20Naarden.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/30282-Vestingwerken%20en%20grachten%20van%20Naarden.jpg"}'::text[], 4, '{"en": {"name": "Naarden", "description": "Town in Gooise Meren, Netherlands. A castle in the Netherlands — a historic stop worth the detour."}, "de": {"name": "Naarden", "description": "Festung und Ort in der niederländischen Provinz Nordholland. Eine Burg bzw. ein Schloss in den Niederlanden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Naarden", "description": "Miasto w Holandii. Zamek w Holandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Naarden", "description": "Stad in de Noord-Hollandse gemeente Gooise Meren, Nederland. Een kasteel in Nederland — een historische stop die de omweg waard is."}, "es": {"name": "Naarden", "description": "Municipio de los Países Bajos. Un castillo en los Países Bajos: una parada histórica que merece el desvío."}, "fr": {"name": "Naarden", "description": "Ville néerlandaise située en Hollande-Septentrionale. Un château aux Pays-Bas — une halte historique qui vaut le détour."}, "uk": {"name": "Нарден", "description": "Фортеця і район муніципалітету Гооізе-Міре в нідерландській провінції Північна Голландія. Замок в Нідерландах — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Eemmeer', 'Vodní plocha v Nizozemsku — příjemný cíl vyjížďky s výhledy na hladinu.', 52.28056, 5.33083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eemmeer.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eemmeer.JPG"}'::text[], 5, '{"en": {"name": "Eemmeer", "description": "Lake in Netherlands, Eemmeer, Netherlands. A body of water in the Netherlands — a pleasant ride destination with waterside views."}, "de": {"name": "Eemmeer", "description": "See in den Niederlanden. Ein Gewässer in den Niederlanden — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Eemmeer", "description": "Akwen w Holandii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Eemmeer", "description": "Meer in Nederland. Een waterpartij in Nederland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Eemmeer", "description": "Lago en Países Bajos. Una masa de agua en los Países Bajos: un destino agradable con vistas al agua."}, "fr": {"name": "Eemmeer", "description": "Lac néerlandais. Un plan d''eau aux Pays-Bas — une belle destination avec vue sur l''eau."}, "uk": {"name": "Ееммеер", "description": "Водойма в Нідерландах — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Katedrála svatého Martina z Tours', 'Památka v Nizozemsku — kus historie přímo u trasy.', 52.09092, 5.12223, 'http://commons.wikimedia.org/wiki/Special:FilePath/DomTorenUtrechtNederland.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/DomTorenUtrechtNederland.jpg"}'::text[], 6, '{"en": {"name": "St. Martin''s Cathedral, Utrecht", "description": "Cathedral in Utrecht. A heritage sight in the Netherlands — a piece of history right on your route."}, "de": {"name": "Utrechter Dom", "description": "Kirchengebäude in Utrecht. Ein Denkmal in den Niederlanden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętego Marcina w Utrechcie", "description": "Zabytek w Holandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Domkerk", "description": "Kerkgebouw in Utrecht, Nederland. Een monument in Nederland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Martín", "description": "Utrecht. Un monumento en los Países Bajos: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Martin d''Utrecht", "description": "Édifice religieux aux Pays-Bas. Un monument aux Pays-Bas — un morceau d''histoire au bord de la route."}, "uk": {"name": "Утрехтський собор", "description": "Пам''ятка в Нідерландах — шматочок історії просто на маршруті."}}'::jsonb);
