    (v_route, 'Letiště Charlese de Gaulla', 'Letiště v Paříži. Letecký cíl ve Francii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 49.00972, 2.54778, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aeroport%20de%20Roissy.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aeroport%20de%20Roissy.JPG"}'::text[], 0, '{"en": {"name": "Paris-Charles de Gaulle Airport", "description": "International airport serving Paris, France. An aviation sight in France — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Paris-Charles-de-Gaulle", "description": "Flughafen in Frankreich, Paris. Ein Luftfahrt-Ziel in Frankreich — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Paryż-Roissy-Charles de Gaulle", "description": "Cel lotniczy we Francji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Parijs-Charles de Gaulle", "description": "Internationale luchthaven in Île-de-France, Frankrijk. Een luchtvaartdoel in Frankrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "París-Charles de Gaulle", "description": "Infraestructura de transporte de París, Francia. Un destino aeronáutico en Francia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport Paris-Charles-de-Gaulle", "description": "Aéroport desservant Paris (Île-de-France, France). Un site aéronautique en France — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт імені Шарля де Голля", "description": "Аеропорт, спроєктований Полем Андрьо і відкритий 8 березня 1974 року. Авіаційна пам''ятка у Франції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'bazilika svatého Denise', 'Památka ve Francii — kus historie přímo u trasy.', 48.93556, 2.35972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilique%20St%20Denis%20fa%C3%A7ade%20ouest%20St%20Denis%20Seine%20St%20Denis%2020.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilique%20St%20Denis%20fa%C3%A7ade%20ouest%20St%20Denis%20Seine%20St%20Denis%2020.jpg"}'::text[], 1, '{"en": {"name": "Basilica of Saint-Denis", "description": "Basilica located in Seine-Saint-Denis, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Kathedrale von Saint-Denis", "description": "Kirchengebäude in Saint-Denis, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Saint-Denis", "description": "Świątynia katolicka. Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Saint-Denis", "description": "Kathedraal in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Saint-Denis", "description": "Basílica situada en Sena-Saint Denis, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Denis", "description": "Basilique située en Seine-Saint-Denis, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Абатство Сен-Дені", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika Sacré-Cœur', 'Bazilika v Paříži. Památka ve Francii — kus historie přímo u trasy.', 48.88665, 2.34295, 'http://commons.wikimedia.org/wiki/Special:FilePath/Le%20sacre%20coeur.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Le%20sacre%20coeur.jpg"}'::text[], 2, '{"en": {"name": "Sacré-Cœur", "description": "Roman Catholic church in Paris, France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Sacré-Cœur de Montmartre", "description": "Neobyzantinisches Kirchengebäude in Paris. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Sacré-Cœur", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Basilique du Sacré-Cœur", "description": "Kerkgebouw in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica del Sacré Cœur de Montmartre", "description": "Basílica y monumento de París. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique du Sacré-Cœur de Montmartre", "description": "Basilique située à Paris, France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Сакре-Кер", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála Notre-Dame', 'Katedrála v Paříži. Památka ve Francii — kus historie přímo u trasy.', 48.853, 2.3498, 'http://commons.wikimedia.org/wiki/Special:FilePath/Notre-Dame%20de%20Paris%202013-07-24.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Notre-Dame%20de%20Paris%202013-07-24.jpg"}'::text[], 3, '{"en": {"name": "Notre-Dame de Paris", "description": "Cathedral in Paris. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Notre-Dame de Paris", "description": "Kathedrale und Sitz des Erzbistums Paris. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Notre-Dame w Paryżu", "description": "Świątynia katolicka we Francji, w Paryżu; archikatedra w stylu gotyckim. Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Notre-Dame van Parijs", "description": "Kathedraal in Parijs, Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Notre-Dame de París", "description": "Catedral católica en París, Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Paris", "description": "Cathédrale située à Paris, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Паризької Богоматері", "description": "Собор у Парижі. Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bastila', 'Pevnost a věznice v Paříži. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.85333, 2.36917, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bastille%20Exterior%201790%20or%201791.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bastille%20Exterior%201790%20or%201791.jpg"}'::text[], 4, '{"en": {"name": "Bastille", "description": "Former fortress in Paris, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Bastille", "description": "Ehemalige Stadttorburg im Osten von Paris. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Bastylia", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Bastille Saint-Antoine", "description": "Bouwwerk in Parijs. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Bastilla", "description": "Prisión de París hasta la Revolución Francesa. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "Bastille", "description": "Ancienne forteresse parisienne. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Бастилія", "description": "Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Eiffelova věž', 'Rozhledna v Paříži. Rozhledna ve Francii — výhled do kraje jako odměna za zastávku.', 48.8583, 2.29448, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tour%20Eiffel%20Wikimedia%20Commons.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tour%20Eiffel%20Wikimedia%20Commons.jpg"}'::text[], 5, '{"en": {"name": "Eiffel Tower", "description": "Tower located on the Champ de Mars in Paris, France. A lookout tower in France — sweeping views as a reward for stopping."}, "de": {"name": "Eiffelturm", "description": "Eisenfachwerkturm auf dem Champs de Mars in Paris. Ein Aussichtsturm in Frankreich — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Wieża Eiffla", "description": "Konstrukcja kratowa z kutego żelaza (Paryż, Francja; 1889–). Wieża widokowa we Francji — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Eiffeltoren", "description": "Bouwwerk in Parijs. Een uitkijktoren in Frankrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "torre Eiffel", "description": "Monumento en París, Francia. Un mirador en Francia: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour Eiffel", "description": "Tour de fer puddlé de 330 mètres à Paris, France. Une tour panoramique en France — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Ейфелева вежа", "description": "Архітектурна пам''ятка Парижа, розміщена на Марсовому полі, символ сучасної Франції. Оглядова вежа у Франції — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Versailles', 'Zámek ve městě Versailles. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.80472, 2.12028, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vue%20a%C3%A9rienne%20du%20domaine%20de%20Versailles%20par%20ToucanWings%20-%20Creative%20Commons%20By%20Sa%203.0%20-%20083.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vue%20a%C3%A9rienne%20du%20domaine%20de%20Versailles%20par%20ToucanWings%20-%20Creative%20Commons%20By%20Sa%203.0%20-%20083.jpg"}'::text[], 6, '{"en": {"name": "Palace of Versailles", "description": "Palace in Versailles, France and location of the Museum of the History of France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Schloss Versailles", "description": "Französisches Schloss, Residenz der Könige von Frankreich. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac wersalski", "description": "Pałac królewski w Wersalu we Francji. Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Versailles", "description": "Kasteel in Versailles, Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Versalles", "description": "Recinto palaciego en Francia que desempeñó las funciones de una residencia real en siglos pasados. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Versailles", "description": "Château à Versailles, en France. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Версальський палац", "description": "Палац у Версалі, колишня резиденція французьких королів. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb);
