    (v_route, 'Letiště Frankfurt nad Mohanem', 'Letiště v Německu. Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 50.03331, 8.57046, 'http://commons.wikimedia.org/wiki/Special:FilePath/FRA%20June2013.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/FRA%20June2013.JPG"}'::text[], 0, '{"en": {"name": "Frankfurt Airport", "description": "Biggest airport of Germany, located in Frankfurt, Hesse. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Frankfurt Main", "description": "Größter deutscher Flughafen in Hessen. Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Frankfurt", "description": "Port lotniczy w Niemczech. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Frankfurt am Main", "description": "Internationale luchthaven in Frankfurt am Main, Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "aeropuerto de Frankfurt", "description": "Aeropuerto alemán. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Francfort-sur-le-Main", "description": "Aéroport international desservant Francfort-sur-le-Main. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Рейн-Майнський аеропорт", "description": "Найбільший аеропорт Німеччини. Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Zámek Friedrichshof', 'Hesensko, Německo. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.18889, 8.51, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schlosshotel-kronberg002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schlosshotel-kronberg002.jpg"}'::text[], 1, '{"en": {"name": "Schlosshotel Kronberg", "description": "Château in Kronberg im Taunus, Hesse, near Frankfurt am Main. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Friedrichshof", "description": "Schlosshotel in Kronberg im Taunus in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zámek Friedrichshof", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Schlosshotel Kronberg", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Schlosshotel Kronberg", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château-hôtel de Kronberg", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Schlosshotel Kronberg", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Saalburg Roman Fort', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.2715, 8.56666, 'http://commons.wikimedia.org/wiki/Special:FilePath/Saalburg%20Main%20Gate%20%28Porta%20Praetoria%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Saalburg%20Main%20Gate%20%28Porta%20Praetoria%29.jpg"}'::text[], 2, '{"en": {"name": "Saalburg Roman Fort", "description": "Cohort castrum, part of the Limes Germanicus, and is the most completely reconstructed Roman fort in Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Römerkastell Saalburg", "description": "Kohortenfestung, Teil des Limes Germanicus, am vollständigsten rekonstruiertes römisches Kastell in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Saalburg Roman Fort", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Romeins fort van Saalburg", "description": "Is het cohortfort, onderdeel van de Limes Germanicus, en is het meest volledig gereconstrueerde Romeinse fort in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Fuerte Romano de Saalburg", "description": "Es el fuerte de cohorte, que forma parte del Limes Germanicus, y es el fuerte romano más reconstruido en Alemania. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Fort romain Saalburg", "description": "Est le fort de la cohorte, une partie du Limes Germanicus, et est le fort romain le plus reconstruit en Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Saalburg Roman Fort", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Adlerhorst', 'Velitelské stanoviště Adolfa Hitlera. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 50.37917, 8.61111, 'http://commons.wikimedia.org/wiki/Special:FilePath/Adlerhorst-Ziegenberg-Bunker-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Adlerhorst-Ziegenberg-Bunker-1.jpg"}'::text[], 3, '{"en": {"name": "Adlerhorst", "description": "World War II bunker complex in the Taunus mountains in the state of Hesse, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Führerhauptquartier Adlerhorst", "description": "Bunkerkomplex. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Führerhauptquartier Adlerhorst", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Adlerhorst", "description": "Bouwwerk in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Adlerhorst", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Adlerhorst", "description": "Ensemble de bunkers de militaires allemands de la Seconde Guerre mondiale. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Адлерхорст", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála svatých Martina a Štěpána v Mohuči', 'Katedrála v Německu. Památka v Německu — kus historie přímo u trasy.', 49.99889, 8.27389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20%28Mainz%29%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cathedral%20%28Mainz%29%202.jpg"}'::text[], 4, '{"en": {"name": "Mainz Cathedral", "description": "Cathedral in Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Mainzer Dom", "description": "Romanischer Kaiserdom mit gotischen Elementen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Moguncji", "description": "Romańska katedra cesarska z elementami gotyckimi. Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Mainz", "description": "Kathedraal in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Maguncia", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Martin de Mayence", "description": "Église allemande. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Майнцький собор", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter Eberbach', 'Německý cisterciácký klášter. Památka v Německu — kus historie přímo u trasy.', 50.0425, 8.04667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Eberbach%20fg01.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Eberbach%20fg01.JPG"}'::text[], 5, '{"en": {"name": "Eberbach Abbey", "description": "Former monastery in the Rheingau. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Kloster Eberbach", "description": "Kulturdenkmal in Eltville, Hessen. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Eberbach", "description": "Były cysterski klasztor w Rheingau. Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster Eberbach", "description": "Voormalig cisterciënzer klooster in Eltville. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio Eberbach", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye d''Eberbach", "description": "Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Klášter Eberbach", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Frankenstein', 'Zřícenina hradu v Německu. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 49.79333, 8.66833, 'http://commons.wikimedia.org/wiki/Special:FilePath/InnerCastle.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/InnerCastle.jpg"}'::text[], 6, '{"en": {"name": "Frankenstein Castle", "description": "Castle in Hesse, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Burg Frankenstein", "description": "Burgruine in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Frankenstein w Odenwaldzie", "description": "Ruina zamku w Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burcht Frankenstein", "description": "Kasteel in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Frankenstein", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château Frankenstein", "description": "Château fort allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Frankenstein", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb);
