    (v_route, 'letiště Adolfa Suáreze', 'Mezinárodní letiště ve Španělsku. Letecký cíl ve Španělsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 40.47222, -3.56083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Barajas%20overview1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Barajas%20overview1.jpg"}'::text[], 0, '{"en": {"name": "Madrid-Barajas Airport", "description": "International airport serving Madrid, Spain. An aviation sight in Spain — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Madrid-Barajas", "description": "Flughafen in Spanien. Ein Luftfahrt-Ziel in Spanien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Madryt-Barajas", "description": "Cel lotniczy w Hiszpanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Adolfo Suárez Madrid-Barajas", "description": "Internationale luchthaven in Madrid, Spanje. Een luchtvaartdoel in Spanje — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "aeropuerto Adolfo Suárez Madrid-Barajas", "description": "Aeropuerto principal de Madrid, España. Un destino aeronáutico en España: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Madrid-Barajas", "description": "Aéroport desservant Madrid, en Espagne. Un site aéronautique en Espagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Барахас", "description": "Авіаційна пам''ятка в Іспанії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Alcalá Gate', 'Hrad či zámek ve Španělsku — historická zastávka, která stojí za odbočku.', 40.42002, -3.68873, 'http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20de%20Alcal%C3%A1%202025.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Puerta%20de%20Alcal%C3%A1%202025.jpg"}'::text[], 1, '{"en": {"name": "Alcalá Gate", "description": "Cultural property in Madrid Distritos: Retiro y Salamanca, Spain. A castle in Spain — a historic stop worth the detour."}, "de": {"name": "Puerta de Alcalá", "description": "Denkmal in Spanien. Eine Burg bzw. ein Schloss in Spanien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Puerta de Alcalá", "description": "Klasycystyczny pomnik. Zamek w Hiszpanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Puerta de Alcalá", "description": "Triomfboog in Madrid, Spanje. Een kasteel in Spanje — een historische stop die de omweg waard is."}, "es": {"name": "Puerta de Alcalá", "description": "Antigua puerta de entrada/salida de Madrid. Un castillo en España: una parada histórica que merece el desvío."}, "fr": {"name": "porte de Alcalá", "description": "Monument à Madrid. Un château en Espagne — une halte historique qui vaut le détour."}, "uk": {"name": "Alcalá Gate", "description": "Пам''ятка культурної спадщини в Іспанії. Замок в Іспанії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter koletinských klarisek v Madridu', 'Klášter v Madridu. Památka ve Španělsku — kus historie přímo u trasy.', 40.41827, -3.70619, 'http://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20las%20Descalzas%20Reales%20%28Madrid%29%2007.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20las%20Descalzas%20Reales%20%28Madrid%29%2007.jpg"}'::text[], 2, '{"en": {"name": "Convent of Las Descalzas Reales", "description": "Monastery in Madrid, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Monasterio de las Descalzas Reales", "description": "Denkmal in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Descalzas Reales", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Monasterio de las Descalzas Reales", "description": "Klooster en museum in Madrid. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de las Descalzas Reales", "description": "Monasterio de la ciudad de Madrid, (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère des Déchaussées royales", "description": "Monument historique d''Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Дескальсас-Реалес", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie Almudenské v Madridu', 'Katedrála ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 40.41556, -3.71444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Almudena%202022%20-%20overview.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Almudena%202022%20-%20overview.jpg"}'::text[], 3, '{"en": {"name": "Almudena Cathedral", "description": "Roman Catholic cathedral in Madrid, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Almudena-Kathedrale", "description": "Gebäude in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Catedral de la Almudena", "description": "Świątynia katolicka. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Madrid", "description": "Bouwwerk in Madrid. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "catedral de la Almudena", "description": "Catedral de Madrid (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Almudena", "description": "Cathédrale catholique romaine à Madrid, Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор де ла Альмудена", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Royal Basilica of Saint Francis the Great', 'Památka ve Španělsku — kus historie přímo u trasy.', 40.41048, -3.71439, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica%20de%20San%20Francisco%20el%20Grande-2009.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica%20de%20San%20Francisco%20el%20Grande-2009.jpg"}'::text[], 4, '{"en": {"name": "Royal Basilica of Saint Francis the Great", "description": "Cultural property in Madrid, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Royal Basilica of Saint Francis the Great", "description": "Denkmal in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika San Francisco el Grande", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Real Basilica de San Francisco el Grande", "description": "Bouwwerk in Madrid. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Francisco el Grande", "description": "Edificio en Madrid. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-François-le-Grand", "description": "Basilique catholique de Madrid. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Королівський собор святого Франциска Великого", "description": "Пам''ятка культурної спадщини в Іспанії. Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
