    (v_route, 'Letiště London Gatwick', 'Letiště ve Velké Británii. Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 51.14722, -0.19028, 'http://commons.wikimedia.org/wiki/Special:FilePath/Gatwick%20Airport%20%2850850159593%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Gatwick%20Airport%20%2850850159593%29.jpg"}'::text[], 0, '{"en": {"name": "London Gatwick Airport", "description": "International airport in West Sussex, England. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen London Gatwick", "description": "Flughafen in London, Vereinigtes Königreich. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "port lotniczy Londyn-Gatwick", "description": "Międzynarodowy port lotniczy w West Sussex, w Anglii; 40 km na południe od centrum Londynu. Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Londen Gatwick", "description": "Internationale luchthaven in Crawley, Verenigd Koninkrijk. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Londres-Gatwick", "description": "Aeropuerto de Londres, Reino Unido. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Londres Gatwick", "description": "Aéroport dans le West Sussex, Royaume-Uni. Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Гатвік", "description": "Англійський аеропорт за 40 км від Лондона. Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Hever Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.18694, 0.11389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hever%20Castle.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hever%20Castle.jpg"}'::text[], 1, '{"en": {"name": "Hever Castle", "description": "Grade I listed country house in Hever, Kent, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Hever Castle", "description": "Schloss im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Hever Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Hever Castle", "description": "Museum in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Hever", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Hever", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Hever Castle", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'St George''s Cathedral, Southwark', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.49788, -0.1079, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20George%27s%20Cathedral%20%282022%29%20-%20London%2C%20UK.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20George%27s%20Cathedral%20%282022%29%20-%20London%2C%20UK.jpg"}'::text[], 2, '{"en": {"name": "St George''s Cathedral, Southwark", "description": "Roman Catholic cathedral in London, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "St.-Georgs-Kathedrale", "description": "Kirchengebäude in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jerzego w Londynie", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "St George''s Cathedral, Southwark", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Jorge, Southwark", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-George de Southwark", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "St George''s Cathedral, Southwark", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Churchillovo muzeum a Cabinet War Rooms', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.50222, -0.1293, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cabinet%20war%20rooms.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cabinet%20war%20rooms.jpg"}'::text[], 3, '{"en": {"name": "Churchill War Rooms", "description": "Museum in London. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Cabinet War Rooms", "description": "Ehemals geheime Kommandozentrale der britischen Kriegsführung im Zweiten Weltkrieg in London. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Churchillovo muzeum a Cabinet War Rooms", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Churchill Museum and Cabinet War Rooms", "description": "Bouwwerk in Londen. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Churchill War Rooms", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "Churchill War Rooms", "description": "Musée londonien. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Churchillovo muzeum a Cabinet War Rooms", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Serpentine', 'Vodní plocha ve Velké Británii — příjemný cíl vyjížďky s výhledy na hladinu.', 51.50528, -0.16944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Serpentine%20Lake.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Serpentine%20Lake.jpg"}'::text[], 4, '{"en": {"name": "Serpentine", "description": "Lake in Hyde Park, London, United Kingdom. A body of water in the United Kingdom — a pleasant ride destination with waterside views."}, "de": {"name": "The Serpentine", "description": "See in Hyde Park, London. Ein Gewässer in Großbritannien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Serpentine", "description": "Jezioro w Hyde Parku w Londynie. Akwen w Wielkiej Brytanii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Serpentine", "description": "Meer in Hyde Park, Londen. Een waterpartij in het Verenigd Koninkrijk — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Serpentine", "description": "Lago en Hyde Park, Londres. Una masa de agua en el Reino Unido: un destino agradable con vistas al agua."}, "fr": {"name": "Serpentine", "description": "Lac dans Hyde Park à Londres. Un plan d''eau au Royaume-Uni — une belle destination avec vue sur l''eau."}, "uk": {"name": "Серпентин", "description": "Водойма у Великій Британії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Richmond Park', 'Park v Londýně. Přírodní zajímavost ve Velké Británii — místo na protažení nohou uprostřed přírody.', 51.44333, -0.275, 'http://commons.wikimedia.org/wiki/Special:FilePath/Isabella%20Plantation%2C%20Richmond%20Park%2C%20London%20-%20April%202011.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Isabella%20Plantation%2C%20Richmond%20Park%2C%20London%20-%20April%202011.jpg"}'::text[], 5, '{"en": {"name": "Richmond Park", "description": "Royal Park in London, England, UK. A natural sight in the United Kingdom — a spot to stretch your legs amid nature."}, "de": {"name": "Richmond Park", "description": "Park im Vereinigten Königreich. Eine Natursehenswürdigkeit in Großbritannien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Richmond Park", "description": "Atrakcja przyrodnicza w Wielkiej Brytanii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Richmond Park", "description": "Park in het Verenigd Koninkrijk. Een natuurbezienswaardigheid in het Verenigd Koninkrijk — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque Richmond", "description": "Parque situado en Londres, Reino Unido. Un paraje natural en el Reino Unido: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Richmond Park", "description": "Le plus grand parc de Londres, district de Richmond upon Thames. Un site naturel au Royaume-Uni — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Річмонд-парк", "description": "Природна пам''ятка у Великій Британії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Guildford Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.2411, -0.59, 'http://commons.wikimedia.org/wiki/Special:FilePath/Guildford%20Cathedral%2C%20Stag%20Hill%2C%20Guildford%20%28Seen%20from%20Onslow%20Village%29%20%28May%202014%29%20%281%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Guildford%20Cathedral%2C%20Stag%20Hill%2C%20Guildford%20%28Seen%20from%20Onslow%20Village%29%20%28May%202014%29%20%281%29.JPG"}'::text[], 6, '{"en": {"name": "Guildford Cathedral", "description": "Anglican cathedral at Guildford, Surrey, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Guildford", "description": "Kathedrale im Vereinigten Königreich. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Guildford", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Guildford", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Guildford Cathedral", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Guildford", "description": "Cathédrale anglicane en Angleterre. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Guildford Cathedral", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb);
