    (v_route, 'Letiště Mnichov', 'Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 48.35378, 11.78609, 'http://commons.wikimedia.org/wiki/Special:FilePath/Munich%20Airport%20Aerial%20View%20T1%20T2%20MAC.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Munich%20Airport%20Aerial%20View%20T1%20T2%20MAC.jpg"}'::text[], 0, '{"en": {"name": "Munich Airport", "description": "International airport serving Munich, capital of Bavaria. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen München", "description": "Internationaler Verkehrsflughafen der bayerischen Landeshauptstadt München. Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Monachium", "description": "Port lotniczy w Niemczech. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven München", "description": "Internationale luchthaven in Hallbergmoos, Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional de Múnich-Franz Josef Strauss", "description": "Aeropuerto alemán. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international Franz-Josef-Strauss de Munich", "description": "Aéroport desservant Munich en Allemagne. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Мюнхен", "description": "Аеропорт в Німеччині. Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Schleißheim palace complex', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.24861, 11.56833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Schleissheim%20Palace.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20Schleissheim%20Palace.jpg"}'::text[], 1, '{"en": {"name": "Schleißheim palace complex", "description": "Comprises three palaces in a grand baroque park in the village of Oberschleißheim near Munich, Bavaria, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schlossanlage Schleißheim", "description": "Schlosskomplex mit drei Schlössern in Deutschland. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Schleißheim", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Paleis van Schleißheim", "description": "Duits kastelencomplex. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Schleißheim", "description": "Complejo palaciego alemán. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Schleissheim", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Шляйсгайм", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Nymphenburg', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.15806, 11.50361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Nymphenburg%2C%20Weitwinkelansicht.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Nymphenburg%2C%20Weitwinkelansicht.jpg"}'::text[], 2, '{"en": {"name": "Nymphenburg Palace", "description": "Baroque palace in Munich, Bavaria, southern Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Nymphenburg", "description": "Schloss in München, Sommerresidenz. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Nymphenburg", "description": "Pałac w Monachium, Niemczech. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "slot Nymphenburg", "description": "Bouwwerk in München. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Nymphenburg", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château Nymphenburg", "description": "Palais baroque à Munich, Bavière, sud de l''Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Німфенбург", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie v Mnichově', 'Katedrála v německém Mnichově. Památka v Německu — kus historie přímo u trasy.', 48.13858, 11.57362, 'http://commons.wikimedia.org/wiki/Special:FilePath/Frauenkirche%20Munich%20-%20View%20from%20Peterskirche%20Tower.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Frauenkirche%20Munich%20-%20View%20from%20Peterskirche%20Tower.jpg"}'::text[], 3, '{"en": {"name": "Frauenkirche", "description": "Church in Munich, Bavaria, Germany; cathedral of the archdiocese of Munich and Freising. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Frauenkirche, München", "description": "Kathedralkirche des katholischen Erzbistums München und Freising, Deutschland. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Marii Panny w Monachium", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Frauenkirche", "description": "München. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora de Múnich", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Munich", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Фрауенкірхе", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'kostel svatého Petra v Mnichově', 'Kostelní stavba v Mnichově. Památka v Německu — kus historie přímo u trasy.', 48.13647, 11.57601, 'http://commons.wikimedia.org/wiki/Special:FilePath/Alter-peter%20vom-rathaus.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Alter-peter%20vom-rathaus.jpg"}'::text[], 4, '{"en": {"name": "St. Peter''s Church, Munich", "description": "A church in Munich. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "St. Peter (München)", "description": "Kirchengebäude in München. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Piotra w Monachium", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Petruskerk", "description": "München. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "kostel svatého Petra v Mnichově", "description": "Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Saint-Pierre de Munich", "description": "Édifice religieux allemand. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "kostel svatého Petra v Mnichově", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Isartor', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.1351, 11.5817, 'http://commons.wikimedia.org/wiki/Special:FilePath/Isartor%20M%C3%BCnchen%2C%20ohne%20Autos.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Isartor%20M%C3%BCnchen%2C%20ohne%20Autos.jpg"}'::text[], 5, '{"en": {"name": "Isartor", "description": "Tower. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Isartor", "description": "Stadttor der historischen Altstadt von München. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Isartor", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Isartor", "description": "Toren in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Isartor", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Isartor", "description": "Bâtiment de Haute-Bavière, en Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Isartor", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Královská rezidence Mnichov', 'Městský zámek a rezidence bavorských vévodů, kurfiřtů a králů. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 48.14105, 11.57871, 'http://commons.wikimedia.org/wiki/Special:FilePath/BAVIERA.%20M%C3%9ANICH.%20Residenz%20%28fachada%20occidental%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BAVIERA.%20M%C3%9ANICH.%20Residenz%20%28fachada%20occidental%29.jpg"}'::text[], 6, '{"en": {"name": "Munich Residence", "description": "Building in Munich, Upper Bavaria, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Residenz München", "description": "Größtes Innenstadtschloss Deutschlands. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Rezydencja w Monachium", "description": "Rezydencja królów Bawarii. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Munich Residenz", "description": "Stadsresidentie in classicistische stijl in de Duitse stad München. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Residencia de Múnich", "description": "Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "résidence de Munich", "description": "Bâtiment de Munich, Haute-Bavière, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Мюнхенська Резиденція", "description": "Будівля у Верхній Баварії, Німеччина. Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb);
