    (v_route, 'Letiště Řím-Fiumicino', 'Letiště v Itálii. Letecký cíl v Itálii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 41.7956, 12.2499, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rom%20Fiumicino%202011-by-RaBoe-02.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rom%20Fiumicino%202011-by-RaBoe-02.jpg"}'::text[], 0, '{"en": {"name": "Roma Fiumicino Airport", "description": "International airport of Rome, in Fiumicino, Italy. An aviation sight in Italy — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Rom-Fiumicino", "description": "Größter Flughafen der italienischen Hauptstadt Rom und Hauptdrehkreuz der Fluggesellschaft ITA. Ein Luftfahrt-Ziel in Italien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Rzym-Fiumicino", "description": "Port lotniczy we Włoszech. Cel lotniczy we Włoszech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Rome Fiumicino", "description": "Internationale luchthaven in Fiumicino, Italië. Een luchtvaartdoel in Italië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Roma-Fiumicino", "description": "Aeropuerto más importante de Italia. Un destino aeronáutico en Italia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport Léonard-de-Vinci de Rome-Fiumicino", "description": "Aéroport desservant Rome, en Italie. Un site aéronautique en Italie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт імені Леонардо да Вінчі", "description": "Авіаційна пам''ятка в Італії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Bazilika svatého Pavla za hradbami', 'Římská bazilika. Památka v Itálii — kus historie přímo u trasy.', 41.85861, 12.47722, 'http://commons.wikimedia.org/wiki/Special:FilePath/StPaul.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/StPaul.jpg"}'::text[], 1, '{"en": {"name": "Basilica of Saint Paul outside the Walls", "description": "Church in Rome, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Sankt Paul vor den Mauern", "description": "Kirchengebäude in Rom. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Pawła za Murami", "description": "Prawdopodobne miejsce pochówku św. Pawła. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Paulus buiten de Muren", "description": "Kerkgebouw in Rome, Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Pablo Extramuros", "description": "Basílica mayor en Roma. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Paul-hors-les-Murs", "description": "Édifice religieux italien. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Павла за мурами", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Aurelianova hradba', 'Hrad či zámek v Itálii — historická zastávka, která stojí za odbočku.', 41.87329, 12.49896, 'http://commons.wikimedia.org/wiki/Special:FilePath/Celio%20-%20le%20mura%20tra%20porta%20san%20Sebastiano%20e%20porta%20Ardeatina%201974.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Celio%20-%20le%20mura%20tra%20porta%20san%20Sebastiano%20e%20porta%20Ardeatina%201974.JPG"}'::text[], 2, '{"en": {"name": "Aurelian Walls", "description": "Historic line of walls built around the city of Rome, Italy. A castle in Italy — a historic stop worth the detour."}, "de": {"name": "Aurelianische Mauer", "description": "Antike Stadtmauer von Rom, archäologische Stätte in Italien. Eine Burg bzw. ein Schloss in Italien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Mur Aureliana", "description": "Mury miejskie Rzymu. Zamek we Włoszech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Aureliaanse Muur", "description": "Weermuur in Rome, Italië. Een kasteel in Italië — een historische stop die de omweg waard is."}, "es": {"name": "Murallas aurelianas", "description": "Línea histórica de murallas construida alrededor de la ciudad de Roma, Italia. Un castillo en Italia: una parada histórica que merece el desvío."}, "fr": {"name": "mur d''Aurélien", "description": "Enceinte fortifiée antique protégeant la ville de Rome. Un château en Italie — une halte historique qui vaut le détour."}, "uk": {"name": "Стіна Авреліана", "description": "Замок в Італії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Lateránská bazilika', 'Katedrála sv. Jana v Římě. Památka v Itálii — kus historie přímo u trasy.', 41.88591, 12.50616, 'http://commons.wikimedia.org/wiki/Special:FilePath/San%20Giovanni%20in%20Laterano%202021.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/San%20Giovanni%20in%20Laterano%202021.jpg"}'::text[], 3, '{"en": {"name": "Archbasilica of St. John Lateran", "description": "Cathedral in Rome, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Lateranbasilika", "description": "Kathedrale des Bistums Rom. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "bazylika św. Jana na Lateranie", "description": "Świątynia katolicka w Rzymie. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Jan van Lateranen", "description": "Kerkgebouw in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Archibasílica de San Juan de Letrán", "description": "Catedral de Roma, Italia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Jean-de-Latran", "description": "Église à Rome, Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Латеранська базиліка", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika Panny Marie Sněžné', 'Bazilika maior v Římě. Památka v Itálii — kus historie přímo u trasy.', 41.8975, 12.49861, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Santa%20Maria%20Maggiore%20-%20Roma.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20Santa%20Maria%20Maggiore%20-%20Roma.jpg"}'::text[], 4, '{"en": {"name": "Basilica di Santa Maria Maggiore", "description": "Largest Catholic Marian church in Rome. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Santa Maria Maggiore", "description": "Eine der vier Papstbasiliken Roms und eine der sieben Pilgerkirchen. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Matki Bożej Większej", "description": "Starożytna bazylika papieska w Rzymie. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basiliek van Santa Maria Maggiore", "description": "Kerkgebouw in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa María la Mayor", "description": "Basílica mayor en Roma, Italia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Sainte-Marie-Majeure de Rome", "description": "Église romaine du Vatican. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Санта Марія Маджоре", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Pantheon', 'Starověký kruhový chrám v Římě. Památka v Itálii — kus historie přímo u trasy.', 41.89861, 12.47694, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pantheon%20%28Rome%29%20-%20Right%20side%20and%20front.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pantheon%20%28Rome%29%20-%20Right%20side%20and%20front.jpg"}'::text[], 5, '{"en": {"name": "Pantheon", "description": "Ancient Roman temple in Rome, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Pantheon", "description": "Antikes Bauwerk in Rom. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Panteon w Rzymie", "description": "Świątynia na Polu Marsowym. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Pantheon", "description": "Antieke tempel in Rome, Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Panteón de Agripa", "description": "Templo de planta circular erigido en Roma. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Panthéon", "description": "Édifice religieux antique à Rome, Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Римський Пантеон", "description": "Храм усіх богів у Римі. Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Andělský hrad', 'Monumentální kruhová stavba v Římě. Hrad či zámek v Itálii — historická zastávka, která stojí za odbočku.', 41.90304, 12.46631, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castel%20Sant%27Angelo%20at%20Night.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castel%20Sant%27Angelo%20at%20Night.jpg"}'::text[], 6, '{"en": {"name": "Castel Sant''Angelo", "description": "Castle and museum in Rome, formerly the imperial mausoleum of the emperor Hadrian and subsequent Roman emperors. A castle in Italy — a historic stop worth the detour."}, "de": {"name": "Engelsburg", "description": "Burg und Museum in Rom. Eine Burg bzw. ein Schloss in Italien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Świętego Anioła", "description": "Budowla w Rzymie. Zamek we Włoszech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Engelenburcht", "description": "Kasteel en museum in Rome. Een kasteel in Italië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Sant''Angelo", "description": "Monumento romano. Un castillo en Italia: una parada histórica que merece el desvío."}, "fr": {"name": "château Saint-Ange", "description": "Château et musée à Rome. Un château en Italie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Сант-Анджело", "description": "Колишній мавзолей римського імператора Адріана, перетворений в середньовіччі на укріплений замок. Замок в Італії — історична зупинка, варта об''їзду."}}'::jsonb);
