    (v_route, 'Letiště Brusel', 'Letiště v Belgii. Letecký cíl v Belgii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 50.90139, 4.48444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Brussels%20Airport%20Runway%2025%20R.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Brussels%20Airport%20Runway%2025%20R.jpg"}'::text[], 0, '{"en": {"name": "Brussels Airport", "description": "International airport northeast of Brussels, Belgium. An aviation sight in Belgium — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Brüssel-Zaventem", "description": "Flughafen von Brüssel, Belgien, ca. 12 km nordöstlich der Stadt. Ein Luftfahrt-Ziel in Belgien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Bruksela", "description": "Port lotniczy w Belgii. Cel lotniczy w Belgii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Brussels Airport", "description": "Nationale luchthaven van België. Een luchtvaartdoel in België — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Bruselas-National", "description": "Aeropuerto comercial de Bruselas y el principal aeropuerto de Bélgica por tráfico y operaciones. Un destino aeronáutico en Bélgica: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Bruxelles", "description": "Aéroport desservant Bruxelles (Région de Bruxelles-Capitale, Belgique). Un site aéronautique en Belgique — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Брюссельський аеропорт", "description": "Аеропорт у Бельгії. Авіаційна пам''ятка у Бельгії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Zámek Laeken', 'Zámek v Belgii. Hrad či zámek v Belgii — historická zastávka, která stojí za odbočku.', 50.88639, 4.35972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20Laeken.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castle%20of%20Laeken.JPG"}'::text[], 1, '{"en": {"name": "Royal Castle of Laeken", "description": "Château and official residence of the monarch of the Belgians. A castle in Belgium — a historic stop worth the detour."}, "de": {"name": "Schloss Laken", "description": "Schloss und Residenz des belgischen Königs. Eine Burg bzw. ein Schloss in Belgien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zámek Laeken", "description": "Zamek w Belgii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Laken", "description": "Kasteel en officiële residentie van de Koning der Belgen. Een kasteel in België — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Real de Laeken", "description": "Castillo y residencia oficial del rey de los belgas. Un castillo en Bélgica: una parada histórica que merece el desvío."}, "fr": {"name": "château de Laeken", "description": "Château et résidence officielle du roi des Belges. Un château en Belgique — une halte historique qui vaut le détour."}, "uk": {"name": "Лакенський палац", "description": "Замок у Бельгії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bazilika Sacré-Cœur', 'Bazilika v Bruselu. Památka v Belgii — kus historie přímo u trasy.', 50.86667, 4.31722, 'http://commons.wikimedia.org/wiki/Special:FilePath/1001%20Basilica%20of%20the%20Sacred%20Heart%20in%20Brussels%20Photo%20by%20Giles%20Laurent.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/1001%20Basilica%20of%20the%20Sacred%20Heart%20in%20Brussels%20Photo%20by%20Giles%20Laurent.jpg"}'::text[], 2, '{"en": {"name": "National Basilica of the Sacred Heart", "description": "Basilica in Brussels, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Nationalbasilika des Heiligen Herzens", "description": "Kirchengebäude in Brüssel, Belgien. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Narodowa Bazylika Najświętszego Serca w Brukseli", "description": "Kościół rzymskokatolicki (Bruksela, Belgia). Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Nationale Basiliek van het Heilig-Hart", "description": "Basiliek in Brussel, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica del Sagrado Corazón", "description": "Lugar de culto en Koekelberg, Bruselas. Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique nationale du Sacré-Cœur", "description": "Basilique à Bruxelles, Belgique. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Серця", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Michaela archanděla a svaté Guduly', 'Katedrála v Bruselu. Památka v Belgii — kus historie přímo u trasy.', 50.84778, 4.36028, 'http://commons.wikimedia.org/wiki/Special:FilePath/%28Belgium%29%20St.%20Michael%20%26%20St.%20Gudula%20Cathedral%20Tower%2C%20Brussels.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%28Belgium%29%20St.%20Michael%20%26%20St.%20Gudula%20Cathedral%20Tower%2C%20Brussels.jpg"}'::text[], 3, '{"en": {"name": "Cathedral of St. Michael and St. Gudula", "description": "Cathedral in Brussels, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Kathedrale St. Michael und St. Gudula", "description": "Hauptkirche der Stadt Brüssel und Sitz des Erzbischofs. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "katedra Świętego Michała i Świętej Guduli", "description": "Świątynia katolicka. Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Sint-Michiel en Sint-Goedele", "description": "Kathedraal in Brussel, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Miguel y Santa Gúdula de Bruselas", "description": "Catedral en Bruselas, Bélgica. Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saints-Michel-et-Gudule", "description": "Cathédrale à Bruxelles, Belgique. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Брюссельський собор", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'St. Rumbold''s Cathedral', 'Památka v Belgii — kus historie přímo u trasy.', 51.02889, 4.47833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mechelen%20Margareta%20voor%20Sint-Rombouts%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mechelen%20Margareta%20voor%20Sint-Rombouts%2002.jpg"}'::text[], 4, '{"en": {"name": "St. Rumbold''s Cathedral", "description": "Cathedral in Mechelen, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Kathedrale von Mechelen", "description": "Kathedrale in Belgien. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Rumolda w Mechelen", "description": "Świątynia katolicka. Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Romboutskathedraal", "description": "Mechelen. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Rumoldo de Malinas", "description": "Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Rombaut de Malines", "description": "Édifice religieux belge. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Румбольда", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála Panny Marie v Antverpách', 'Katedrála v Belgii. Památka v Belgii — kus historie přímo u trasy.', 51.22027, 4.40025, 'http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Antwerp%20Cathedral%20from%20the%20Groenplaats.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Antwerp%20Cathedral%20from%20the%20Groenplaats.jpg"}'::text[], 5, '{"en": {"name": "Onze-Lieve-Vrouwekathedraal", "description": "Roman-Catholic cathedral in Antwerp, Belgium. A heritage sight in Belgium — a piece of history right on your route."}, "de": {"name": "Liebfrauenkathedrale", "description": "Domkirche des Bistums Antwerpen. Ein Denkmal in Belgien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Najświętszej Marii Panny w Antwerpii", "description": "Świątynia katolicka. Zabytek w Belgii — kawałek historii tuż przy trasie."}, "nl": {"name": "Onze-Lieve-Vrouwekathedraal", "description": "Kerkgebouw en museum in Antwerpen, België. Een monument in België — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Amberes", "description": "Templo de Bélgica. Un monumento en Bélgica: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame d''Anvers", "description": "Cathédrale catholique située à Anvers. Un monument en Belgique — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Антверпенської Богоматері", "description": "Пам''ятка у Бельгії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Antwerp City Hall', 'Renesanční radnice v Antverpách byla postavena v letech 1561 až 1565 podle návrhu Cornelise Florise de Vriendta. Rozhledna v Belgii — výhled do kraje jako odměna za zastávku.', 51.22139, 4.39944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Antwerpen%20Stadhuis%20crop1%202006-05-28.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Antwerpen%20Stadhuis%20crop1%202006-05-28.jpg"}'::text[], 6, '{"en": {"name": "Antwerp City Hall", "description": "City hall of Antwerp, Belgium. A lookout tower in Belgium — sweeping views as a reward for stopping."}, "de": {"name": "Rathaus Antwerpen", "description": "Rathaus in Belgien. Ein Aussichtsturm in Belgien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Ratusz w Antwerpii", "description": "Wieża widokowa w Belgii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Stadhuis van Antwerpen", "description": "Bouwwerk in Antwerpen (stad). Een uitkijktoren in België — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Ayuntamiento de Amberes", "description": "Un mirador en Bélgica: amplias vistas como recompensa por la parada."}, "fr": {"name": "hôtel de ville d''Anvers", "description": "Édifice civil en Belgique. Une tour panoramique en Belgique — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Антверпенська ратуша", "description": "Оглядова вежа у Бельгії — широкі краєвиди як нагорода за зупинку."}}'::jsonb);
