  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Paříž-Orly', 'Letiště v Paříži. Letecký cíl ve Francii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 48.72333, 2.37944, 'http://commons.wikimedia.org/wiki/Special:FilePath/OrlyVal%20Orly.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/OrlyVal%20Orly.JPG"}'::text[], 0, '{"en": {"name": "Orly Airport", "description": "International airport serving Paris, France. An aviation sight in France — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Paris-Orly", "description": "Flughafen in Frankreich. Ein Luftfahrt-Ziel in Frankreich — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Paryż-Orly", "description": "Międzynarodowy port lotniczy. Cel lotniczy we Francji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Orly", "description": "Vliegveld in Île-de-France, Frankrijk. Een luchtvaartdoel in Frankrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Paris Orly", "description": "Aeropuerto francés. Un destino aeronáutico en Francia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Paris-Orly", "description": "Aéroport desservant Paris (Île-de-France, France). Un site aéronautique en France — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Орлі", "description": "Авіаційна пам''ятка у Франції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Zámek Vincennes', 'Zámek ve Francii. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.84278, 2.43583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Vincennes%20Paris%20FRA%20002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Vincennes%20Paris%20FRA%20002.jpg"}'::text[], 1, '{"en": {"name": "Château de Vincennes", "description": "Castle. A castle in France — a historic stop worth the detour."}, "de": {"name": "Schloss Vincennes", "description": "Schloss in Frankreich. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Vincennes", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Vincennes", "description": "Kasteel in Vincennes, Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Vincennes", "description": "Castillo de Francia. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Vincennes", "description": "Château fort français situé à Vincennes. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Венсенський замок", "description": "Замок (споруда). Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Klášter Saint-Germain-des-Prés', 'Klášter v Paříži. Památka ve Francii — kus historie přímo u trasy.', 48.85389, 2.33444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Paris%20St-Germain-des-Pr%C3%A9s.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Paris%20St-Germain-des-Pr%C3%A9s.jpg"}'::text[], 2, '{"en": {"name": "Royal abbey of Saint-Germain-des-Prés", "description": "Abbey located in Paris, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Abtei Saint-Germain-des-Prés", "description": "Kirchengebäude in Paris. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Saint-Germain-des-Prés (opactwo)", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Koninklijke abdij van Saint-Germain-des-Prés", "description": "Klooster in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Saint-Germain-des-Prés", "description": "Abadía situada en París, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye Royale de Saint-Germain-des-Prés", "description": "Abbaye située à Paris, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Сен-Жермен-де-Пре (абатство)", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Palais du Louvre', 'Bývalý královský palác v Paříži. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.86103, 2.33589, 'http://commons.wikimedia.org/wiki/Special:FilePath/Pavillon%20de%20Flore%2C%20Louvre%20Museum%2C%20Paris%205%20November%202019.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Pavillon%20de%20Flore%2C%20Louvre%20Museum%2C%20Paris%205%20November%202019.jpg"}'::text[], 3, '{"en": {"name": "Louvre Palace", "description": "Former royal palace, now hosting the Louvre Museum in Paris, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Palais du Louvre", "description": "Früherer französischer Königspalast. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Luwr", "description": "Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Louvrekasteel", "description": "Voormalig paleis, nu huisvesting Louvremuseum. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio del Louvre", "description": "Antiguo palacio real en París. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "palais du Louvre", "description": "Ancien palais royal, hébergeant aujourd''hui le musée du Louvre. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Луврський палац", "description": "Стародавній королівський замок у Парижі (Франція), перебудований у палац. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Zámek Malmaison', 'Zámek ve městě Malmaison u Paříže. Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.8708, 2.16685, 'http://commons.wikimedia.org/wiki/Special:FilePath/2011%20Chateau%20de%20Malmaison%20recto-verso.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2011%20Chateau%20de%20Malmaison%20recto-verso.jpg"}'::text[], 4, '{"en": {"name": "Château de Malmaison", "description": "Historic estate and mansion near Paris, France. A castle in France — a historic stop worth the detour."}, "de": {"name": "Schloss Malmaison", "description": "Schloss nahe Paris in Frankreich. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Malmaison", "description": "Pałac we Francji. Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Malmaison", "description": "Museum in Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Malmaison", "description": "Castillo en Rueil-Malmaison, sede del Museo Nacional Malmaison. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Malmaison", "description": "Château situé à Rueil-Malmaison, près de Paris et abritant le musée national de la Malmaison. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Мальмезон", "description": "Палац у Франції. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Château de Saint-Germain-en-Laye', 'Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.89806, 2.09639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Saint-Germain-en-Laye01.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Saint-Germain-en-Laye01.jpg"}'::text[], 5, '{"en": {"name": "Château de Saint-Germain-en-Laye", "description": "Castle housing the national archeology museum near Paris. A castle in France — a historic stop worth the detour."}, "de": {"name": "Schloss Saint-Germain-en-Laye", "description": "Schloss in Frankreich. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Château de Saint-Germain-en-Laye", "description": "Zamek we Francji. Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Château de Saint-Germain-en-Laye", "description": "Kasteel in Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Saint-Germain-en-Laye", "description": "Castillo francés en la región de París. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Saint-Germain-en-Laye", "description": "Château français abritant le musée d''archéologie nationale, en région parisienne. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Сен-Жерменський палац", "description": "Шато у Франції. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Zámek Vaux-le-Vicomte', 'Hrad či zámek ve Francii — historická zastávka, která stojí za odbočku.', 48.56583, 2.71415, 'http://commons.wikimedia.org/wiki/Special:FilePath/0%20Maincy%20-%20Ch%C3%A2teau%20de%20Vaux-le-Vicomte%20%282%29.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/0%20Maincy%20-%20Ch%C3%A2teau%20de%20Vaux-le-Vicomte%20%282%29.JPG"}'::text[], 6, '{"en": {"name": "Vaux-le-Vicomte", "description": "Nicolas Fouquet''s castle in Maincy. A castle in France — a historic stop worth the detour."}, "de": {"name": "Schloss Vaux-le-Vicomte", "description": "Schloss in Frankreich. Eine Burg bzw. ein Schloss in Frankreich — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Vaux-le-Vicomte", "description": "Zespół pałacowo-ogrodowy w Maincy, we Francji. Zamek we Francji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel van Vaux-le-Vicomte", "description": "Kasteel in Frankrijk. Een kasteel in Frankrijk — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Vaux-le-Vicomte", "description": "Castillo en Ile-de-France. Un castillo en Francia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Vaux-le-Vicomte", "description": "Château de Nicolas Fouquet en Île-de-France. Un château en France — une halte historique qui vaut le détour."}, "uk": {"name": "Во-ле-Віконт", "description": "Шато у Франції. Замок у Франції — історична зупинка, варта об''їзду."}}'::jsonb);
