    (v_route, 'Letiště Curych', 'Mezinárodní letiště ve Švýcarsku. Letecký cíl ve Švýcarsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 47.45806, 8.54806, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zurich%20airport%20img%203324.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zurich%20airport%20img%203324.jpg"}'::text[], 0, '{"en": {"name": "Zurich Airport", "description": "International airport serving Zurich, Switzerland. An aviation sight in Switzerland — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Zürich", "description": "Internationaler Flughafen in der Schweiz. Ein Luftfahrt-Ziel in der Schweiz — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Zurych-Kloten", "description": "Port lotniczy w Szwajcarii. Cel lotniczy w Szwajcarii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Zürich", "description": "Internationale luchthaven in Zürich, Zwitserland. Een luchtvaartdoel in Zwitserland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional de Zúrich", "description": "Mayor aeropuerto de Suiza. Un destino aeronáutico en Suiza: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Zurich", "description": "Aéroport situé à Zurich en Suisse. Un site aéronautique en Suisse — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Цюрих", "description": "Авіаційна пам''ятка у Швейцарії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Rýnské vodopády', 'Vodopády ve Švýcarsku. Přírodní zajímavost ve Švýcarsku — místo na protažení nohou uprostřed přírody.', 47.67722, 8.61583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Chutes%20du%20Rhin%20-%20Octobre%202021.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Chutes%20du%20Rhin%20-%20Octobre%202021.jpg"}'::text[], 1, '{"en": {"name": "Rhine Falls", "description": "Waterfall on the Rhein River in Switzerland. A natural sight in Switzerland — a spot to stretch your legs amid nature."}, "de": {"name": "Rheinfall", "description": "Wasserfall in der Schweiz. Eine Natursehenswürdigkeit in der Schweiz — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Rheinfall", "description": "Wodospad. Atrakcja przyrodnicza w Szwajcarii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Rheinfall", "description": "Grootste waterval van Europa. Een natuurbezienswaardigheid in Zwitserland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cataratas del Rin", "description": "Un paraje natural en Suiza: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "chutes du Rhin", "description": "Chutes en Suisse. Un site naturel en Suisse — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Рейнський водоспад", "description": "Природна пам''ятка у Швейцарії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Habsburg', 'Hrad ve Švýcarsku. Hrad či zámek ve Švýcarsku — historická zastávka, která stojí za odbočku.', 47.46254, 8.18073, 'http://commons.wikimedia.org/wiki/Special:FilePath/Habsburg-Schloss.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Habsburg-Schloss.jpg"}'::text[], 2, '{"en": {"name": "Habsburg Castle", "description": "Castle on the Wülpelsberg in Habsburg in the canton of Aargau, Switzerland. A castle in Switzerland — a historic stop worth the detour."}, "de": {"name": "Schloss Habsburg", "description": "Burg auf dem Wülpelsberg in Habsburg im Kanton Aargau, Schweiz. Eine Burg bzw. ein Schloss in der Schweiz — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Habsburg", "description": "Zamek w Szwajcarii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Habichtsburg", "description": "Bouwwerk in Aargau. Een kasteel in Zwitserland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Habsburgo", "description": "Un castillo en Suiza: una parada histórica que merece el desvío."}, "fr": {"name": "château de Habsbourg", "description": "Un château en Suisse — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Габсбург", "description": "Замок у Швейцарії. Замок у Швейцарії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Hallwilersee', 'Jezero ve Švýcarsku. Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.28417, 8.21611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Hallwil%20%28view%20from%20the%20south%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Lake%20Hallwil%20%28view%20from%20the%20south%29.jpg"}'::text[], 3, '{"en": {"name": "Lake Hallwil", "description": "Lake in Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Hallwilersee", "description": "See in der Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Hallwilersee", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Hallwilermeer", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Hallwil", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Hallwil", "description": "Lac en Suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Галльвільське озеро", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Zugské jezero', 'Jezero ve Švýcarsku. Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.11667, 8.48333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Zoug.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Zoug.jpg"}'::text[], 4, '{"en": {"name": "Lake Zug", "description": "Lake in Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Zugersee", "description": "See in der Zentralschweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Zug", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Zug", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Zug", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Zoug", "description": "Lac suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Цугське озеро", "description": "Озеро в Швейцарії. Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Klášter Einsiedeln', 'Památka ve Švýcarsku — kus historie přímo u trasy.', 47.12667, 8.75139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Einsiedeln%20001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kloster%20Einsiedeln%20001.jpg"}'::text[], 5, '{"en": {"name": "Einsiedeln Abbey", "description": "Benedictine monastery in Einsiedeln in the canton of Schwyz in Switzerland. A heritage sight in Switzerland — a piece of history right on your route."}, "de": {"name": "Benediktinerabtei Einsiedeln", "description": "Territorialabtei der Benediktiner in Einsiedeln im Kanton Schwyz, Schweiz. Ein Denkmal in der Schweiz — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo terytorialne Einsiedeln", "description": "Zabytek w Szwajcarii — kawałek historii tuż przy trasie."}, "nl": {"name": "Abdij van Einsiedeln", "description": "Een monument in Zwitserland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Einsiedeln", "description": "Un monumento en Suiza: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye d''Einsiedeln", "description": "Un monument en Suisse — un morceau d''histoire au bord de la route."}, "uk": {"name": "Айнзідельнське абатство", "description": "Пам''ятка у Швейцарії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Curyšské jezero', 'Jezero ve Švýcarsku. Vodní plocha ve Švýcarsku — příjemný cíl vyjížďky s výhledy na hladinu.', 47.2475, 8.6775, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zuerichsee.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zuerichsee.jpg"}'::text[], 6, '{"en": {"name": "Lake Zurich", "description": "Major lake in Switzerland. A body of water in Switzerland — a pleasant ride destination with waterside views."}, "de": {"name": "Zürichsee", "description": "See in der Schweiz. Ein Gewässer in der Schweiz — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Zuryskie", "description": "Akwen w Szwajcarii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Zürich", "description": "Meer in Zwitserland. Een waterpartij in Zwitserland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Zúrich", "description": "Lago de Suiza. Una masa de agua en Suiza: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Zurich", "description": "Lac suisse. Un plan d''eau en Suisse — une belle destination avec vue sur l''eau."}, "uk": {"name": "Цюрихське озеро", "description": "Водойма у Швейцарії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
