  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Kodaň', 'Letiště v Dánsku. Letecký cíl v Dánsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 55.61806, 12.65611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20airport%20from%20air.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20airport%20from%20air.jpg"}'::text[], 0, '{"en": {"name": "Copenhagen Airport", "description": "International airport serving Copenhagen, Denmark. An aviation sight in Denmark — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Kopenhagen-Kastrup", "description": "Flughafen in Dänemark. Ein Luftfahrt-Ziel in Dänemark — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Kopenhaga-Kastrup", "description": "Międzynarodowy port lotniczy w Danii. Cel lotniczy w Danii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Internationale luchthaven Kopenhagen Kastrup", "description": "Vliegveld in Tårnby, Denemarken. Een luchtvaartdoel in Denemarken — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Copenhague-Kastrup", "description": "Principal aeropuerto de Dinamarca. Un destino aeronáutico en Dinamarca: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Copenhague", "description": "Aéroport desservant Copenhague (Danemark). Un site aéronautique au Danemark — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Каструп", "description": "Найбільший аеропорт Данії. Авіаційна пам''ятка в Данії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Kodaňský zámek', 'Budova v Kodani v Dánsku. Hrad či zámek v Dánsku — historická zastávka, která stojí za odbočku.', 55.67722, 12.58, 'http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20Castle%201698.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20Castle%201698.jpg"}'::text[], 1, '{"en": {"name": "Copenhagen Castle", "description": "Building in Copenhagen, Denmark. A castle in Denmark — a historic stop worth the detour."}, "de": {"name": "Kodaňský zámek", "description": "Burg in Dänemark. Eine Burg bzw. ein Schloss in Dänemark — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Kodaňský zámek", "description": "Zamek w Danii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Copenhagen Castle", "description": "Fortificatie in Denemarken. Een kasteel in Denemarken — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Copenhague", "description": "Edificio real en Dinamarca. Un castillo en Dinamarca: una parada histórica que merece el desvío."}, "fr": {"name": "château de Copenhague", "description": "Bâtiment de la commune de Copenhague, au Danemark. Un château au Danemark — une halte historique qui vaut le détour."}, "uk": {"name": "Kodaňský zámek", "description": "Замок в Данії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Kostel Panny Marie', 'Kodaňská katedrála a Národní katedrála Dánska. Památka v Dánsku — kus historie přímo u trasy.', 55.67933, 12.5725, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rundet%C3%A5rn%20view%202%20new%20version.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rundet%C3%A5rn%20view%202%20new%20version.jpg"}'::text[], 2, '{"en": {"name": "Church of Our Lady", "description": "Cathedral of Copenhagen and the National Cathedral of Denmark. A heritage sight in Denmark — a piece of history right on your route."}, "de": {"name": "Frauenkirche", "description": "Kirchengebäude in Kopenhagen. Ein Denkmal in Dänemark — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Marii Panny w Kopenhadze", "description": "Zabytek w Danii — kawałek historii tuż przy trasie."}, "nl": {"name": "Onze-Lieve-Vrouwekerk", "description": "Kerkgebouw in Kopenhagen, Denemarken. Een monument in Denemarken — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora de Copenhague", "description": "Un monumento en Dinamarca: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame de Copenhague", "description": "Église de la commune de Copenhague, Danemark. Un monument au Danemark — un morceau d''histoire au bord de la route."}, "uk": {"name": "Kostel Panny Marie", "description": "Пам''ятка в Данії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Rundetaarn', 'Věž ze 17. století v centu Kodaně. Rozhledna v Dánsku — výhled do kraje jako odměna za zastávku.', 55.68137, 12.57579, 'http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20-%20Rundet%C3%A5rn%20-%202013.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Copenhagen%20-%20Rundet%C3%A5rn%20-%202013.jpg"}'::text[], 3, '{"en": {"name": "Rundetaarn", "description": "17th-century tower located in central Copenhagen, Denmark. A lookout tower in Denmark — sweeping views as a reward for stopping."}, "de": {"name": "Rundetaarn", "description": "Museum in Dänemark. Ein Aussichtsturm in Dänemark — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Rundetaarn", "description": "Wieża widokowa w Danii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Rundetaarn", "description": "Bouwwerk in Kopenhagen. Een uitkijktoren in Denemarken — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Rundetårn", "description": "Torre del siglo XVII en Dinamarca. Un mirador en Dinamarca: amplias vistas como recompensa por la parada."}, "fr": {"name": "Rundetårn", "description": "Tour du XVIIe siècle située dans le centre de Copenhague, au Danemark. Une tour panoramique au Danemark — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Кругла вежа", "description": "Оглядова вежа в Данії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Kastellet', 'Hrad či zámek v Dánsku — historická zastávka, která stojí za odbočku.', 55.69161, 12.59357, 'http://commons.wikimedia.org/wiki/Special:FilePath/Kastellet%20aerial.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Kastellet%20aerial.jpg"}'::text[], 4, '{"en": {"name": "Kastellet", "description": "Star fort in Copenhagen. A castle in Denmark — a historic stop worth the detour."}, "de": {"name": "Kastell von Kopenhagen", "description": "Zitadelle in Dänemark. Eine Burg bzw. ein Schloss in Dänemark — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Kastellet", "description": "Fort gwiaździsty w Kopenhadze. Zamek w Danii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kastellet", "description": "Vestingwerk in Kopenhagen. Een kasteel in Denemarken — een historische stop die de omweg waard is."}, "es": {"name": "Kastellet", "description": "Fuerte  en Copenhague. Un castillo en Dinamarca: una parada histórica que merece el desvío."}, "fr": {"name": "Kastellet", "description": "Bâtiment de la commune de Copenhague, au Danemark. Un château au Danemark — une halte historique qui vaut le détour."}, "uk": {"name": "Kastellet", "description": "Замок в Данії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Furesø', 'Vodní plocha v Dánsku — příjemný cíl vyjížďky s výhledy na hladinu.', 55.79639, 12.41417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fures%C3%B8%20N%C3%A6sseslottet%202005-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fures%C3%B8%20N%C3%A6sseslottet%202005-1.jpg"}'::text[], 5, '{"en": {"name": "Furesø", "description": "Lake in Denmark. A body of water in Denmark — a pleasant ride destination with waterside views."}, "de": {"name": "Furesø", "description": "See in der dänischen Region Hovedstaden. Ein Gewässer in Dänemark — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Furesø", "description": "Jezioro w Danii. Akwen w Danii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Furesø", "description": "Meer. Een waterpartij in Denemarken — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Furesø", "description": "Una masa de agua en Dinamarca: un destino agradable con vistas al agua."}, "fr": {"name": "lac Furesø", "description": "Lac danois. Un plan d''eau au Danemark — une belle destination avec vue sur l''eau."}, "uk": {"name": "Furesø", "description": "Водойма в Данії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Katedrála v Roskilde', 'Památka v Dánsku — kus historie přímo u trasy.', 55.64267, 12.08031, 'http://commons.wikimedia.org/wiki/Special:FilePath/Roskilde%20Cathedral%20aerial%20crop.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Roskilde%20Cathedral%20aerial%20crop.jpg"}'::text[], 6, '{"en": {"name": "Roskilde Cathedral", "description": "Cathedral in Denmark (Church of Denmark). A heritage sight in Denmark — a piece of history right on your route."}, "de": {"name": "Dom zu Roskilde", "description": "Kirchengebäude in Dänemark. Ein Denkmal in Dänemark — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "katedra w Roskilde", "description": "Katedra w Danii. Zabytek w Danii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Roskilde", "description": "Kathedraal in Denemarken. Een monument in Denemarken — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Roskilde", "description": "Un monumento en Dinamarca: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Roskilde", "description": "Bâtiment de Danemark. Un monument au Danemark — un morceau d''histoire au bord de la route."}, "uk": {"name": "Роскілльський собор", "description": "Кафедральний собор в Роскіллє, Данія. Пам''ятка в Данії — шматочок історії просто на маршруті."}}'::jsonb);
