    (v_route, 'Letiště London Stansted', 'Letiště ve Velké Británii. Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 51.885, 0.235, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stansted%20Airport%20-%20geograph.org.uk%20-%201710808.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stansted%20Airport%20-%20geograph.org.uk%20-%201710808.jpg"}'::text[], 0, '{"en": {"name": "London Stansted Airport", "description": "Passenger airport at Stansted Mountfitchet, Essex, England. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen London-Stansted", "description": "Flughafen im Großraum der britischen Hauptstadt London. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Londyn-Stansted", "description": "Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Londen Stansted", "description": "Internationale luchthaven in Essex, Verenigd Koninkrijk. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Londres-Stansted", "description": "Aeropuerto de Gran Bretaña. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Londres Stansted", "description": "Aéroport desservant Londres au Royaume-Uni. Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Лондон-Станстед", "description": "Пасажирський аеропорт. Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Saffron Walden Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 52.0255, 0.242, 'http://commons.wikimedia.org/wiki/Special:FilePath/Walden%20Castle%2C%20Saffron%20walden%20-%20geograph.org.uk%20-%20154528.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Walden%20Castle%2C%20Saffron%20walden%20-%20geograph.org.uk%20-%20154528.jpg"}'::text[], 1, '{"en": {"name": "Saffron Walden Castle", "description": "Former medieval castle in Essex, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Walden Castle", "description": "Archäologische Stätte im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Saffron Walden Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Saffron Walden Castle", "description": "Kasteel in Uttlesford, het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Saffron Walden Castle", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Walden", "description": "Château dans l''Essex en Angleterre. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Saffron Walden Castle", "description": "Археологічна пам''ятка у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
