  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Atény', 'Letiště v Řecku. Letecký cíl v Řecku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 37.93639, 23.94444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Athens%20International%20Airport%20Eleftherios%20Venizelos%20%CE%94%CE%B9%CE%B5%CE%B8%CE%BD%CE%AE%CF%82%20%CE%91%CE%B5%CF%81%CE%BF%CE%BB%CE%B9%CE%BC%CE%AD%CE%BD%CE%B1%CF%82%20%CE%91%CE%B8%CE%B7%CE%BD%CF%8E%CE%BD%20%CE%95%CE%BB%CE%B5%CF%85%CE%B8%CE%AD%CF%81%CE%B9%CE%BF%CF%82%20%CE%92%CE%B5%CE%BD%CE%B9%CE%B6%CE%AD%CE%BB%CE%BF%CF%82%202019-12-01%20h.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Athens%20International%20Airport%20Eleftherios%20Venizelos%20%CE%94%CE%B9%CE%B5%CE%B8%CE%BD%CE%AE%CF%82%20%CE%91%CE%B5%CF%81%CE%BF%CE%BB%CE%B9%CE%BC%CE%AD%CE%BD%CE%B1%CF%82%20%CE%91%CE%B8%CE%B7%CE%BD%CF%8E%CE%BD%20%CE%95%CE%BB%CE%B5%CF%85%CE%B8%CE%AD%CF%81%CE%B9%CE%BF%CF%82%20%CE%92%CE%B5%CE%BD%CE%B9%CE%B6%CE%AD%CE%BB%CE%BF%CF%82%202019-12-01%20h.jpg"}'::text[], 0, '{"en": {"name": "Athens International Airport \"Eleftherios Venizelos\"", "description": "International airport serving Athens, Greece. An aviation sight in Greece — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Athen-Eleftherios Venizelos", "description": "Flughafen in Griechenland. Ein Luftfahrt-Ziel in Griechenland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Ateny", "description": "Port lotniczy w Grecji. Cel lotniczy w Grecji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Athene", "description": "Bouwwerk in Athene. Een luchtvaartdoel in Griekenland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional Eleftherios Venizelos", "description": "Un destino aeronáutico en Grecia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international d''Athènes Elefthérios-Venizélos", "description": "Aéroport d''Athènes situé à Spáta en Grèce. Un site aéronautique en Grèce — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт «Елефтеріос Венізелос»", "description": "Авіаційна пам''ятка у Греції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Katedrála svatého Dinonýsia v Aténách', 'Katedrála v Řecku. Památka v Řecku — kus historie přímo u trasy.', 37.9791, 23.73461, 'http://commons.wikimedia.org/wiki/Special:FilePath/%CE%86%CE%B3%CE%B9%CE%BF%CF%82%20%CE%94%CE%B9%CE%BF%CE%BD%CF%8D%CF%83%CE%B9%CE%BF%CF%82%20%CE%91%CE%B5%CF%81%CE%BF%CF%80%CE%B1%CE%B3%CE%AF%CF%84%CE%B7%CF%82%206648.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%CE%86%CE%B3%CE%B9%CE%BF%CF%82%20%CE%94%CE%B9%CE%BF%CE%BD%CF%8D%CF%83%CE%B9%CE%BF%CF%82%20%CE%91%CE%B5%CF%81%CE%BF%CF%80%CE%B1%CE%B3%CE%AF%CF%84%CE%B7%CF%82%206648.jpg"}'::text[], 1, '{"en": {"name": "Cathedral Basilica of St. Dionysius the Areopagite", "description": "Cathedral in Athens, Greece. A heritage sight in Greece — a piece of history right on your route."}, "de": {"name": "Kathedrale St. Dionysius Areopagita", "description": "Kirchengebäude in Athen. Ein Denkmal in Griechenland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Dionizego Areopagity w Atenach", "description": "Świątynia katolicka. Zabytek w Grecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Sint Dionysius de Areopagiet", "description": "Kathedraal in Griekenland. Een monument in Griekenland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral-basílica de San Dionisio Areopagita", "description": "Un monumento en Grecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Denys-l''Aréopagite d''Athènes", "description": "Église d''Athènes, Attique, en Grèce. Un monument en Grèce — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Dinonýsia v Aténách", "description": "Пам''ятка у Греції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Metropolitan Cathedral of Athens', 'Památka v Řecku — kus historie přímo u trasy.', 37.97528, 23.73, 'http://commons.wikimedia.org/wiki/Special:FilePath/%CE%9C%CE%B7%CF%84%CF%81%CF%8C%CF%80%CE%BF%CE%BB%CE%B7%20%CE%91%CE%B8%CE%B7%CE%BD%CF%8E%CE%BD%203321.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%CE%9C%CE%B7%CF%84%CF%81%CF%8C%CF%80%CE%BF%CE%BB%CE%B7%20%CE%91%CE%B8%CE%B7%CE%BD%CF%8E%CE%BD%203321.jpg"}'::text[], 2, '{"en": {"name": "Metropolitan Cathedral of Athens", "description": "Church building in Athens, Attica Region, Greece. A heritage sight in Greece — a piece of history right on your route."}, "de": {"name": "Kathedrale Mariä Verkündigung", "description": "Kirchengebäude in Athen. Ein Denkmal in Griechenland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Zwiastowania Matki Bożej w Atenach", "description": "Świątynia prawosławna. Zabytek w Grecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Grote Metropolitaan", "description": "Bouwwerk in Athene. Een monument in Griekenland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Anunciación de Santa María", "description": "Catedral ortodoxa griega en Atenas. Un monumento en Grecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l’Annonciation", "description": "Église d''Athènes, Attique, en Grèce. Un monument en Grèce — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор в Афінах", "description": "Пам''ятка у Греції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Akropolis', 'Náboženské centrum a dominanta Athén. Hrad či zámek v Řecku — historická zastávka, která stojí za odbočku.', 37.97167, 23.72611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Attica%2006-13%20Athens%2050%20View%20from%20Philopappos%20-%20Acropolis%20Hill.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Attica%2006-13%20Athens%2050%20View%20from%20Philopappos%20-%20Acropolis%20Hill.jpg"}'::text[], 3, '{"en": {"name": "Acropolis of Athens", "description": "Ancient citadel above the city of Athens. A castle in Greece — a historic stop worth the detour."}, "de": {"name": "Akropolis", "description": "Antike Stadtfestung in Athen. Eine Burg bzw. ein Schloss in Griechenland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Akropol ateński", "description": "Zamek w Grecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Akropolis van Athene", "description": "Bouwwerk in Athene. Een kasteel in Griekenland — een historische stop die de omweg waard is."}, "es": {"name": "Acrópolis de Atenas", "description": "Antigua ciudadela de Atenas. Un castillo en Grecia: una parada histórica que merece el desvío."}, "fr": {"name": "Acropole d''Athènes", "description": "Ancienne forteresse et sanctuaire à Athènes, en Grèce. Un château en Grèce — une halte historique qui vaut le détour."}, "uk": {"name": "Афінський акрополь", "description": "Антична цитадель. Замок у Греції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Dafnion', 'Památka v Řecku — kus historie přímo u trasy.', 38.01306, 23.63583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dafni%20monastery.jpeg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dafni%20monastery.jpeg"}'::text[], 4, '{"en": {"name": "Daphni Monastery", "description": "11th-century Byzantine monastery in Greece. A heritage sight in Greece — a piece of history right on your route."}, "de": {"name": "Kloster Daphni", "description": "Kloster in Griechenland. Ein Denkmal in Griechenland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Klasztor Dafni", "description": "Kompleks zabudowań XI-wiecznego klasztoru bizantyjskiego na przedmieściu Aten. Zabytek w Grecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster van Dafni", "description": "Klooster in Griekenland. Een monument in Griekenland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Dafni", "description": "Un monumento en Grecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "monastère de Daphni", "description": "Bâtiment d''Attique, en Grèce. Un monument en Grèce — un morceau d''histoire au bord de la route."}, "uk": {"name": "Монастир Дафні", "description": "Пам''ятка у Греції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Lake Vouliagmeni', 'Vodní plocha v Řecku — příjemný cíl vyjížďky s výhledy na hladinu.', 37.8075, 23.78556, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vouliagmenis%20lake%202.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vouliagmenis%20lake%202.JPG"}'::text[], 5, '{"en": {"name": "Lake Vouliagmeni", "description": "Lake in Athens, Greece. A body of water in Greece — a pleasant ride destination with waterside views."}, "de": {"name": "Limni tis Vouliagmenis", "description": "See in Attika, Griechenland. Ein Gewässer in Griechenland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lake Vouliagmeni", "description": "Jezioro w Grecji. Akwen w Grecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lake Vouliagmeni", "description": "Meer in Griekenland. Een waterpartij in Griekenland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lake Vouliagmeni", "description": "Una masa de agua en Grecia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Vouliagméni", "description": "Lac grec. Un plan d''eau en Grèce — une belle destination avec vue sur l''eau."}, "uk": {"name": "Вуліагмені", "description": "Водойма у Греції — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Lake Marathon', 'Vodní plocha v Řecku — příjemný cíl vyjížďky s výhledy na hladinu.', 38.16861, 23.9, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Marathon%2C%20Greece.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Marathon%2C%20Greece.jpg"}'::text[], 6, '{"en": {"name": "Lake Marathon", "description": "Reservoir in Attica, Greece. A body of water in Greece — a pleasant ride destination with waterside views."}, "de": {"name": "Marathon-See", "description": "Stausee in Griechenland. Ein Gewässer in Griechenland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lake Marathon", "description": "Zbiornik retencyjny (Oropou, Grecja). Akwen w Grecji — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Marathonmeer", "description": "Stuwmeer in Griekenland. Een waterpartij in Griekenland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lake Marathon", "description": "Una masa de agua en Grecia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Marathon", "description": "Lac grec. Un plan d''eau en Grèce — une belle destination avec vue sur l''eau."}, "uk": {"name": "Марафон", "description": "Водойма у Греції — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
