    (v_route, 'Letiště Frédérica Chopina', 'Letiště ve Varšavě v Polsku. Letecký cíl v Polsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 52.16583, 20.96722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lotnisko%20Chopina%20w%20Warszawie%202018b.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lotnisko%20Chopina%20w%20Warszawie%202018b.jpg"}'::text[], 0, '{"en": {"name": "Warsaw Chopin Airport", "description": "Airport in Warsaw, Poland. An aviation sight in Poland — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Chopin-Flughafen Warschau", "description": "Flughafen in Polen. Ein Luftfahrt-Ziel in Polen — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Lotnisko Chopina w Warszawie", "description": "Międzynarodowy port lotniczy w Warszawie. Cel lotniczy w Polsce — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Warschau Frédéric Chopin", "description": "Vliegveld in Polen. Een luchtvaartdoel in Polen — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Varsovia-Frédéric Chopin", "description": "Principal terminal aérea de Polonia. Un destino aeronáutico en Polonia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Varsovie-Chopin", "description": "Aéroport desservant Varsovie en Pologne. Un site aéronautique en Pologne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт імені Фридерика Шопена", "description": "Авіаційна пам''ятка у Польщі — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Ujazdów Castle', 'Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.21944, 21.03056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Ujazdowski%20w%20Warszawie%202021.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Ujazdowski%20w%20Warszawie%202021.jpg"}'::text[], 1, '{"en": {"name": "Ujazdów Castle", "description": "Polish palace. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Schloss Ujazdowski", "description": "Burg in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Ujazdowski", "description": "Zamek w Warszawie, znajdujący się w dzielnicy Śródmieście, na Ujazdowie. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Ujazdówkasteel", "description": "Kasteel in Polen. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Ujazdowski en Varsovia", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Ujazdów", "description": "Château polonais. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Уяздовський замок", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Královský hrad', 'Zámek ve Varšavě. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.24778, 21.01417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Warszawa-Zamek%20Kr%C3%B3lewski.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Warszawa-Zamek%20Kr%C3%B3lewski.jpg"}'::text[], 2, '{"en": {"name": "Royal Castle in Warsaw", "description": "Castle residency in Warsaw, Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Königliches Schloss Warschau", "description": "Schloss in Polen. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Królewski w Warszawie", "description": "Zamek w Warszawie. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Koninklijk Paleis", "description": "Warschau. Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Real de Varsovia", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "palais royal de Varsovie", "description": "Palais en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Королівський замок у Варшаві", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bazilika svatého Jana Křtitele', 'Kostel ve Varšavě. Památka v Polsku — kus historie přímo u trasy.', 52.24889, 21.01361, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20archikatedralna%20%C5%9Bw.%20Jana%20Chrzciciela%20w%20Warszawie%202020.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bazylika%20archikatedralna%20%C5%9Bw.%20Jana%20Chrzciciela%20w%20Warszawie%202020.jpg"}'::text[], 3, '{"en": {"name": "St. John''s Archcathedral", "description": "Cathedral. A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Johanneskathedrale", "description": "Kirchengebäude in Warschau. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Archikatedralna św. Jana Chrzciciela w Warszawie", "description": "Świątynia katolicka na Starym Mieście. Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Johanneskathedraal", "description": "Warschau. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan de Varsovia", "description": "Edificio religioso en la ciudad vieja de Varsovia. Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean de Varsovie", "description": "Église cathédrale de Varsovie (Pologne). Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "катедра Івана Хрестителя (Варшава)", "description": "Латинський собор у Варшаві. Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Velká synagoga', 'Bývalá synagoga ve Varšavě. Památka v Polsku — kus historie přímo u trasy.', 52.24459, 21.0024, 'http://commons.wikimedia.org/wiki/Special:FilePath/Wielka%20Synagoga%20w%20Warszawie.PNG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Wielka%20Synagoga%20w%20Warszawie.PNG"}'::text[], 4, '{"en": {"name": "Great Synagogue, Warsaw", "description": "Synagogue (Warsaw, Poland; 1878–1943). A heritage sight in Poland — a piece of history right on your route."}, "de": {"name": "Große Synagoge Warschau", "description": "Ehemalig Warschaus größte und 1943 zerstörte Synagoge. Ein Denkmal in Polen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Wielka Synagoga w Warszawie", "description": "Synagoga (Warszawa, Polska; 1878–1943). Zabytek w Polsce — kawałek historii tuż przy trasie."}, "nl": {"name": "Great Synagogue, Warsaw", "description": "Synagoge in Polen. Een monument in Polen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Gran Sinagoga de Varsovia", "description": "Un monumento en Polonia: un pedazo de historia junto a la ruta."}, "fr": {"name": "grande synagogue de Varsovie", "description": "Un monument en Pologne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Велика синагога (Варшава)", "description": "Пам''ятка в Польщі — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Pevnost Modlin', 'Pevnost v Polsku. Hrad či zámek v Polsku — historická zastávka, která stojí za odbočku.', 52.43833, 20.68194, 'http://commons.wikimedia.org/wiki/Special:FilePath/White%20Tower%20in%20Modlin%20Fortress.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/White%20Tower%20in%20Modlin%20Fortress.jpg"}'::text[], 5, '{"en": {"name": "Modlin Fortress", "description": "Fortress in Poland. A castle in Poland — a historic stop worth the detour."}, "de": {"name": "Festung Modlin", "description": "Polnische Festung. Eine Burg bzw. ein Schloss in Polen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Modlin", "description": "Twierdza na Mazowszu, w Polsce. Zamek w Polsce — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Modlin Fortress", "description": "Een kasteel in Polen — een historische stop die de omweg waard is."}, "es": {"name": "Fortaleza Modlin", "description": "Un castillo en Polonia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Modlin", "description": "Forteresse en Pologne. Un château en Pologne — une halte historique qui vaut le détour."}, "uk": {"name": "Модлинська фортеця", "description": "Замок у Польщі — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Kampinoský národní park', 'Národní park v Mazovském vojvodství na území Kampinoského pralesa. Přírodní zajímavost v Polsku — místo na protažení nohou uprostřed přírody.', 52.31667, 20.56667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20Kampinos%20Alces%20alces%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Poland%20Kampinos%20Alces%20alces%201.jpg"}'::text[], 6, '{"en": {"name": "Kampinos National Park", "description": "National park of Poland. A natural sight in Poland — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Kampinos", "description": "Nationalpark in Polen. Eine Natursehenswürdigkeit in Polen — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Kampinoski Park Narodowy", "description": "Polski park narodowy utworzony w 1959 roku. Atrakcja przyrodnicza w Polsce — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Kampinos National Park", "description": "Nationaal park in Polen. Een natuurbezienswaardigheid in Polen — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Kampinos", "description": "Un paraje natural en Polonia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Kampinos", "description": "Parc national de Pologne. Un site naturel en Pologne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Кампіноський національний парк", "description": "Природна пам''ятка в Польщі — місце розім''яти ноги серед природи."}}'::jsonb);
