    (v_route, 'Letiště Helsinky-Vantaa', 'Letiště ve Finsku. Letecký cíl ve Finsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 60.31722, 24.96333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Helsinki%20Airport%20%2817087444118%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Helsinki%20Airport%20%2817087444118%29.jpg"}'::text[], 0, '{"en": {"name": "Helsinki Airport", "description": "International airport serving Helsinki, Finland. An aviation sight in Finland — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Helsinki-Vantaa", "description": "Flughafen in der finnischen Stadt Vantaa. Ein Luftfahrt-Ziel in Finnland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Helsinki-Vantaa", "description": "Port lotniczy w Finlandii. Cel lotniczy w Finlandii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Helsinki-Vantaa", "description": "Vliegveld in Vantaa, Finland. Een luchtvaartdoel in Finland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Helsinki-Vantaa", "description": "Un destino aeronáutico en Finlandia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport d''Helsinki-Vantaa", "description": "Principal aéroport finlandais situé à Helsinki. Un site aéronautique en Finlande — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Гельсінкі-Вантаа", "description": "Авіаційна пам''ятка у Фінляндії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Evangelická katedrála', 'Katedrála, okres Vironniemi, Helsinky, Finsko. Památka ve Finsku — kus historie přímo u trasy.', 60.17039, 24.95212, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lutheran%20Cathedral%20Helsinki.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lutheran%20Cathedral%20Helsinki.jpg"}'::text[], 1, '{"en": {"name": "Helsinki Cathedral", "description": "Cathedral in Helsinki, Church of Finland. A heritage sight in Finland — a piece of history right on your route."}, "de": {"name": "Dom von Helsinki", "description": "Kirchengebäude in Helsinki. Ein Denkmal in Finnland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Helsinkach", "description": "Zabytek w Finlandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Domkerk van Helsinki", "description": "Bouwwerk in Helsinki. Een monument in Finland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Helsinki", "description": "Templo luterano de Finlandia. Un monumento en Finlandia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale luthérienne d''Helsinki", "description": "Cathédrale finlandaise. Un monument en Finlande — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Гельсінок", "description": "Пам''ятка у Фінляндії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Chrám věčného spánku Panny Marie', 'Kostel, Katajanokka, okres Vironniemi, Jižní hlavní obvod, Helsinky, finsko. Památka ve Finsku — kus historie přímo u trasy.', 60.16853, 24.95987, 'http://commons.wikimedia.org/wiki/Special:FilePath/11-07-31-helsinki-by-RalfR-135.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/11-07-31-helsinki-by-RalfR-135.jpg"}'::text[], 2, '{"en": {"name": "Uspenski Cathedral", "description": "Orthodox cathedral church of Helsinki, Finland. A heritage sight in Finland — a piece of history right on your route."}, "de": {"name": "Uspenski-Kathedrale", "description": "Kirchengebäude in Helsinki. Ein Denkmal in Finnland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sobór Zaśnięcia Matki Bożej w Helsinkach", "description": "Świątynia prawosławna. Zabytek w Finlandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Oespenski-kathedraal", "description": "Helsinki. Een monument in Finland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral Ortodoxa Uspenski", "description": "Catedral ortodoxa en Helsinki. Un monumento en Finlandia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Ouspenski", "description": "Cathédrale orthodoxe finlandaise située à Helsinki. Un monument en Finlande — un morceau d''histoire au bord de la route."}, "uk": {"name": "Успенський собор", "description": "Пам''ятка у Фінляндії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Jindřicha v Helsinkách', 'Kostel ve Finsku. Památka ve Finsku — kus historie přímo u trasy.', 60.15919, 24.95432, 'http://commons.wikimedia.org/wiki/Special:FilePath/Saint%20Henry%27s%20Cathedral%20Helsinki%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Saint%20Henry%27s%20Cathedral%20Helsinki%202.jpg"}'::text[], 3, '{"en": {"name": "Pyhän Henrikin katedraali", "description": "Catholic cathedral in Helsinki, Finland. A heritage sight in Finland — a piece of history right on your route."}, "de": {"name": "Henrik-Kathedrale", "description": "Kirchengebäude in Helsinki. Ein Denkmal in Finnland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Henryka w Helsinkach", "description": "Zabytek w Finlandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Hendrikkathedraal", "description": "Kathedraal in Finland ontworpen door Ernst Lohrmann. Een monument in Finland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Enrique de Helsinki", "description": "Principal iglesia católica de la capital finlandesa. Un monumento en Finlandia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Henri d’Helsinki", "description": "Église finlandaise. Un monument en Finlande — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Jindřicha v Helsinkách", "description": "Пам''ятка у Фінляндії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Suomenlinna', 'Ostrovy, námořní obranná pevnost ve Finsku, Jižní hlavní obvod, Helsinky. Hrad či zámek ve Finsku — historická zastávka, která stojí za odbočku.', 60.14361, 24.98444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Suomenlinna.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Suomenlinna.jpg"}'::text[], 4, '{"en": {"name": "Suomenlinna", "description": "Sea fortress by Helsinki, Finland. A castle in Finland — a historic stop worth the detour."}, "de": {"name": "Suomenlinna", "description": "Inselburg von Helsinki. Eine Burg bzw. ein Schloss in Finnland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Suomenlinna", "description": "Zamek w Finlandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Suomenlinna", "description": "Buurt of wijk in Helsinki, Finland. Een kasteel in Finland — een historische stop die de omweg waard is."}, "es": {"name": "Suomenlinna", "description": "Un castillo en Finlandia: una parada histórica que merece el desvío."}, "fr": {"name": "Suomenlinna", "description": "Forteresse maritime à Helsinki en Finlande. Un château en Finlande — une halte historique qui vaut le détour."}, "uk": {"name": "Свеаборг", "description": "Бастіонна фортеця в Гельсінкі, об''єкт спадщини ЮНЕСКО. Замок у Фінляндії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bodom', 'Jezero na jihu Finska. Vodní plocha ve Finsku — příjemný cíl vyjížďky s výhledy na hladinu.', 60.25639, 24.66667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bodomjarvi%20talvella.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bodomjarvi%20talvella.jpg"}'::text[], 5, '{"en": {"name": "Lake Bodom", "description": "Lake in Espoo, Finland. A body of water in Finland — a pleasant ride destination with waterside views."}, "de": {"name": "Bodominjärvi", "description": "See in Finnland. Ein Gewässer in Finnland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Bodom", "description": "Fińskie jezioro. Akwen w Finlandii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Bodommeer", "description": "Meer in Finland. Een waterpartij in Finland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Bodom", "description": "Lago Finlandés. Una masa de agua en Finlandia: un destino agradable con vistas al agua."}, "fr": {"name": "lac Bodom", "description": "Lac finlandais. Un plan d''eau en Finlande — une belle destination avec vue sur l''eau."}, "uk": {"name": "Бодом", "description": "Озеро у Фінляндії. Водойма у Фінляндії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Národní park Nuuksio', 'Finský národní park, Espoo. Přírodní zajímavost ve Finsku — místo na protažení nohou uprostřed přírody.', 60.31667, 24.46667, 'http://commons.wikimedia.org/wiki/Special:FilePath/Nuuksio%20National%20Park.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Nuuksio%20National%20Park.JPG"}'::text[], 6, '{"en": {"name": "Nuuksio National Park", "description": "National park in Uusimaa, Finland. A natural sight in Finland — a spot to stretch your legs amid nature."}, "de": {"name": "Nuuksio-Nationalpark", "description": "Nationalpark in Finnland. Eine Natursehenswürdigkeit in Finnland — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Nuuksio", "description": "Atrakcja przyrodnicza w Finlandii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Nuuksio National Park", "description": "Een natuurbezienswaardigheid in Finland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional de Nuuksio", "description": "Área protegida de Finlandia. Un paraje natural en Finlandia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Nuuksio", "description": "Parc national de Finlande. Un site naturel en Finlande — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Нууксіо", "description": "Природна пам''ятка у Фінляндії — місце розім''яти ноги серед природи."}}'::jsonb);
