    (v_route, 'Letiště Malpensa', 'Letiště v Itálii. Letecký cíl v Itálii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 45.63, 8.72306, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20photograph%20of%20Milan%20Malpensa%20airport.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20photograph%20of%20Milan%20Malpensa%20airport.jpg"}'::text[], 0, '{"en": {"name": "Milan–Malpensa \"Silvio Berlusconi\" Airport", "description": "International airport serving Milan, Italy. An aviation sight in Italy — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Mailand-Malpensa", "description": "Flughafen für Mailand, Italien. Ein Luftfahrt-Ziel in Italien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Mediolan-Malpensa", "description": "Port lotniczy we Włoszech. Cel lotniczy we Włoszech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Milaan-Malpensa", "description": "Internationale luchthaven in Somma Lombardo, Italië. Een luchtvaartdoel in Italië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Milán-Malpensa", "description": "Aeropuerto internacional situado en la provincia de Varese, Italia. Un destino aeronáutico en Italia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Milan Malpensa", "description": "Aéroport desservant Milan, Italie. Un site aéronautique en Italie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Мілан Мальпенса", "description": "Авіаційна пам''ятка в Італії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Varese', 'Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 45.81667, 8.73333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Posizionevareselago.png', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Posizionevareselago.png"}'::text[], 1, '{"en": {"name": "Lake Varese", "description": "Lake near Varese, Italy. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Lago di Varese", "description": "See in der Lombardei, Italien. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Varese", "description": "Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Meer van Varese", "description": "Meer in Italië. Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Varese", "description": "Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lac de Varèse", "description": "Lac italien. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Varese", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Orta', 'Jezero v Itálii. Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 45.8098, 8.3963, 'http://commons.wikimedia.org/wiki/Special:FilePath/LagoOrtaOmegnaJune052026%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/LagoOrtaOmegnaJune052026%2001.jpg"}'::text[], 2, '{"en": {"name": "Lake Orta", "description": "Lake in Italy. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Ortasee", "description": "See im Piemont, Italien. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Orta", "description": "Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Ortameer", "description": "Meer in Italië. Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "lago de Orta", "description": "Lago italiano. Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lac d''Orta", "description": "Lac italien. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Орта", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Katedrála Nanebevzetí Panny Marie', 'Katedrála v italském Como. Památka v Itálii — kus historie přímo u trasy.', 45.8118, 9.08366, 'http://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Como%20-%20panoramio%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Duomo%20di%20Como%20-%20panoramio%20%282%29.jpg"}'::text[], 3, '{"en": {"name": "Como Cathedral", "description": "Master cathedral in Como. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Dom zu Como", "description": "Dom zu Como. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Como", "description": "Świątynia katolicka. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Como Cathedral", "description": "Kathedraal in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Como", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame-de-l''Assomption de Côme", "description": "Édifice religieux italien. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála Nanebevzetí Panny Marie", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Sforzesco', 'Hrad v Itálii. Hrad či zámek v Itálii — historická zastávka, která stojí za odbočku.', 45.471, 9.17969, 'http://commons.wikimedia.org/wiki/Special:FilePath/20110725%20Castello%20Sforzesco%20Milan%205557.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20110725%20Castello%20Sforzesco%20Milan%205557.jpg"}'::text[], 4, '{"en": {"name": "Sforza Castle", "description": "Castle in Milan, Italy. A castle in Italy — a historic stop worth the detour."}, "de": {"name": "Castello Sforzesco", "description": "Schloss in Mailand. Eine Burg bzw. ein Schloss in Italien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Castello Sforzesco", "description": "Zamek w Mediolanie, Włochy. Zamek we Włoszech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castello Sforzesco", "description": "Museum in Milaan. Een kasteel in Italië — een historische stop die de omweg waard is."}, "es": {"name": "Castillo Sforzesco", "description": "Castillo que se encuentra en el casco antiguo de Milán, Italia. Un castillo en Italia: una parada histórica que merece el desvío."}, "fr": {"name": "château des Sforza", "description": "Château milanais. Un château en Italie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Сфорца", "description": "Замок в Італії. Замок в Італії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'kostel sv. Marie Milostiplné', 'Církevní budova v Miláně, Itálie. Památka v Itálii — kus historie přímo u trasy.', 45.46601, 9.17041, 'http://commons.wikimedia.org/wiki/Special:FilePath/Side%20and%20dome%20-%20Santa%20Maria%20delle%20Grazie%20-%20Milan%202014.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Side%20and%20dome%20-%20Santa%20Maria%20delle%20Grazie%20-%20Milan%202014.jpg"}'::text[], 5, '{"en": {"name": "Santa Maria delle Grazie", "description": "Church in Milan. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Santa Maria delle Grazie", "description": "Kirche in Mailand. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Santa Maria delle Grazie", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Santa Maria delle Grazie", "description": "Kerk met bijbehorend klooster in Milaan, Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Santa Maria delle Grazie", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Santa Maria delle Grazie de Milan", "description": "Église italienne. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Санта Марія делле Ґраціє", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika svatého Ambrože', 'Chrám v Miláně. Památka v Itálii — kus historie přímo u trasy.', 45.4625, 9.17583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Milan%20Sant%27Ambrogio%20016%204923.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Milan%20Sant%27Ambrogio%20016%204923.jpg"}'::text[], 6, '{"en": {"name": "Basilica of Sant''Ambrogio", "description": "Romanesque church in Milan. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Sant’Ambrogio", "description": "Romanische Abtei- und Wallfahrtskirche in Mailand. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Ambrożego w Mediolanie", "description": "Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basiliek van Sint Ambrosius", "description": "Basiliek in Milan. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de san Ambrosio", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Ambroise", "description": "Cathédrale à Milan. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Амвросія", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb);
