    (v_route, 'letiště Barcelona-El Prat', 'Mezinárodní letiště ve Španělsku. Letecký cíl ve Španělsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 41.29694, 2.07833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20El%20Prat%2005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20El%20Prat%2005.jpg"}'::text[], 0, '{"en": {"name": "Josep Tarradellas Airport Barcelona-El Prat", "description": "International airport in Barcelona, Spain. An aviation sight in Spain — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Barcelona-El Prat", "description": "Flughafen in Spanien. Ein Luftfahrt-Ziel in Spanien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Barcelona", "description": "Cel lotniczy w Hiszpanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Josep Tarradellas Barcelona-El Prat", "description": "Internationale Luchthaven van Barcelona. Een luchtvaartdoel in Spanje — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Josep Tarradellas Barcelona-El Prat", "description": "Aeropuerto internacional que da servicio a Barcelona y su área metropolitana. Un destino aeronáutico en España: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Barcelone-El Prat", "description": "Aéroport situé à Barcelone en Espagne. Un site aéronautique en Espagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Барселона — Ель-Прат", "description": "Авіаційна пам''ятка в Іспанії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Katedrála v Barceloně', 'Katedrála ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 41.38389, 2.17639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20Cathedral%20Saint%20Eulalia.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20Cathedral%20Saint%20Eulalia.jpg"}'::text[], 1, '{"en": {"name": "Cathedral of the Holy Cross and Saint Eulalia", "description": "Gothic cathedral and seat of the Archbishop of Barcelona, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kathedrale von Barcelona", "description": "Kirchengebäude in Barcelona. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Eulalii w Barcelonie", "description": "Świątynia katolicka. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Barcelona", "description": "Kathedraal in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Santa Eulalia de Barcelona", "description": "Catedral de Barcelona, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Eulalie de Barcelone", "description": "Édifice religieux espagnol. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Барселонський собор", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Kostel Santa Maria del Mar', 'Barcelonský kostel (Španělsko). Památka ve Španělsku — kus historie přímo u trasy.', 41.38361, 2.18194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Santa%20Maria%20del%20Mar%2C%20Barcelona%2005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Santa%20Maria%20del%20Mar%2C%20Barcelona%2005.jpg"}'::text[], 2, '{"en": {"name": "Basilica of Our Lady of the Sea", "description": "Church. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Santa Maria del Mar", "description": "Kirchengebäude in Barcelona. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół Santa Maria del Mar w Barcelonie", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Santa María del Mar", "description": "Kerkgebouw in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa María del Mar", "description": "Basílica menor en Barcelona, Cataluña, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Sainte-Marie-de-la-Mer de Barcelone", "description": "Église espagnole. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Санта Марія дель Мар", "description": "Церква. Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Sagrada Família', 'Chrám ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 41.40369, 2.17433, 'http://commons.wikimedia.org/wiki/Special:FilePath/SF%20maig%202026.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/SF%20maig%202026.jpg"}'::text[], 3, '{"en": {"name": "Basilica and Expiatory Church of the Holy Family", "description": "Basilica under construction since 1882 in Barcelona, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Sagrada Família", "description": "Römisch-katholische Basilika im Bau in Barcelona, Katalonien, Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sagrada Família", "description": "Bazylika w Barcelonie. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Sagrada Família", "description": "Basiliek in Barcelona, Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Templo Expiatorio de la Sagrada Familia", "description": "Basílica católica de estilo modernista catalán en construcción en Barcelona, Cataluña, España. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "Sagrada Família", "description": "Basilique catholique romaine monumentale en construction depuis 1882 situé à Barcelone, Catalogne, Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Храм Святого Сімейства", "description": "Монументальна римо-католицька базиліка, що будується в Барселоні, Каталонія, Іспанія. Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'National Expiatory Basilica of the Sacred Heart of Jesus', 'Památka ve Španělsku — kus historie přímo u trasy.', 41.42207, 2.11886, 'http://commons.wikimedia.org/wiki/Special:FilePath/Temple%20del%20Sagrat%20Cor%20vist%20des%20de%20la%20Talaia%20del%20Tibidabo.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Temple%20del%20Sagrat%20Cor%20vist%20des%20de%20la%20Talaia%20del%20Tibidabo.JPG"}'::text[], 4, '{"en": {"name": "National Expiatory Basilica of the Sacred Heart of Jesus", "description": "Church in Barcelona, Spain (European Union). A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "National Expiatory Basilica of the Sacred Heart of Jesus", "description": "Kirchengebäude in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sagrat Cor", "description": "Kościół w Barcelonie, w Hiszpanii. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "National Expiatory Basilica of the Sacred Heart of Jesus", "description": "Kerkgebouw in Barcelona, Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Templo Expiatorio del Sagrado Corazón", "description": "Iglesia situada en Barcelona. Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "temple expiatoire du Sacré-Cœur", "description": "Église à Barcelone (Espagne). Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Храм Святого Серця (Барселона)", "description": "Церква в Іспанії. Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Terrassa Cathedral', 'Památka ve Španělsku — kus historie přímo u trasy.', 41.5622, 2.01194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica%20del%20Sant%20Esperit%20%28Terrassa%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica%20del%20Sant%20Esperit%20%28Terrassa%29.jpg"}'::text[], 5, '{"en": {"name": "Terrassa Cathedral", "description": "Church building in Terrassa, Spain. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kathedrale von Terrassa", "description": "Kathedrale in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Terrassa Cathedral", "description": "Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Terrassa Cathedral", "description": "Kathedraal in Spanje. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral del Espíritu Santo de Tarrasa", "description": "Templo católico de la provincia de Barcelona (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale du Saint-Esprit de Terrassa", "description": "Cathédrale espagnole. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Terrassa Cathedral", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Klášter Montserrat', 'Klášter ve Španělsku. Památka ve Španělsku — kus historie přímo u trasy.', 41.59319, 1.83714, 'http://commons.wikimedia.org/wiki/Special:FilePath/Montserrat%20Natural%20Park%204.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Montserrat%20Natural%20Park%204.jpg"}'::text[], 6, '{"en": {"name": "Santa Maria de Montserrat", "description": "Abbey. A heritage sight in Spain — a piece of history right on your route."}, "de": {"name": "Kloster Montserrat", "description": "Kloster in Spanien. Ein Denkmal in Spanien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Opactwo Matki Bożej w Montserrat", "description": "Klasztor benedyktynów w Hiszpanii. Zabytek w Hiszpanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Klooster van Montserrat", "description": "Bouwwerk in Catalonië. Een monument in Spanje — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Monasterio de Montserrat", "description": "Monasterio de la provincia de Barcelona, (España). Un monumento en España: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Montserrat", "description": "Abbaye bénédictine, Catalogne, Espagne. Un monument en Espagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Монсеррат", "description": "Пам''ятка в Іспанії — шматочок історії просто на маршруті."}}'::jsonb);
