    (v_route, 'Letiště London Luton', 'Letiště ve Velké Británii. Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 51.87472, -0.36833, 'http://commons.wikimedia.org/wiki/Special:FilePath/Luton%20Airport%20from%20the%20air%20%28geograph%207106190%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Luton%20Airport%20from%20the%20air%20%28geograph%207106190%29.jpg"}'::text[], 0, '{"en": {"name": "London Luton Airport", "description": "International airport in Luton, Bedfordshire, England. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "London Luton Airport", "description": "Internationaler Verkehrsflughafen bei Luton, etwa 50 km nordwestlich von London. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Londyn-Luton", "description": "Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Londen Luton", "description": "Internationale luchthaven in Luton, Verenigd Koninkrijk. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Londres-Luton", "description": "Aeropuerto de Gran Bretaña. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Londres Luton", "description": "Aéroport desservant Londres au Royaume-Uni. Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Лутон", "description": "Міжнародний аеропорт у Бедфордширі, Англія. Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Someries Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.86912, -0.37561, 'http://commons.wikimedia.org/wiki/Special:FilePath/Someries%20Castle%20Chapel.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Someries%20Castle%20Chapel.jpg"}'::text[], 1, '{"en": {"name": "Someries Castle", "description": "Fortified manor house in Hyde, Bedfordshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Someries Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Someries", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Someries Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Someries Castle", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Someries", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Someries Castle", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'St Albans Cathedral', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.75056, -0.34222, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20Albans%20Cathedral%20Exterior%20from%20west%2C%20Herfordshire%2C%20UK%20-%20Diliff.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20Albans%20Cathedral%20Exterior%20from%20west%2C%20Herfordshire%2C%20UK%20-%20Diliff.jpg"}'::text[], 2, '{"en": {"name": "St Albans Cathedral", "description": "Cathedral in St Albans, England. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Abtei von St Albans", "description": "Abtei in der Stadt St Albans im englischen Hertfordshire. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w St Albans", "description": "Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal en Abdijkerk van Sint-Albanus", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de St Albans", "description": "Catedral en la ciudad de St. Albans, Inglaterra. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Alban de Saint Albans", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Сент-Олбанський собор", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'zámek Berkhamsted', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.7641, -0.55878, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berkhamsted%20Castle%20Jan%202007.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berkhamsted%20Castle%20Jan%202007.jpg"}'::text[], 3, '{"en": {"name": "Berkhamsted Castle", "description": "Castle in Berkhamsted, Hertfordshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Berkhamsted Castle", "description": "Ruine im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "zámek Berkhamsted", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "zámek Berkhamsted", "description": "Mottekasteel in Berkhamsted, Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "zámek Berkhamsted", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Berkhamsted", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "zámek Berkhamsted", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Battle of Britain Bunker', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.5412, -0.46528, 'http://commons.wikimedia.org/wiki/Special:FilePath/Plotting%20Table.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Plotting%20Table.jpg"}'::text[], 4, '{"en": {"name": "Battle of Britain Bunker", "description": "Royal Air Force WWII operations room. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Battle of Britain Bunker", "description": "Bunker. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Battle of Britain Bunker", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Battle of Britain Bunker", "description": "Militair museum in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Battle of Britain Bunker", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "bunker de la bataille d''Angleterre", "description": "Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Battle of Britain Bunker", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Watkin''s Tower', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.55556, -0.27944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Watkin%20tower%20first%20stage.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Watkin%20tower%20first%20stage.jpg"}'::text[], 5, '{"en": {"name": "Watkin''s Tower", "description": "Partially completed iron lattice tower in London, England. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "Watkins Tower", "description": "Unvollendetes Turmbauvorhaben in London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Watkin’s Tower", "description": "Konstrukcja kratowa z kutego żelaza (nieukończona wieża; Londyn, Wielka Brytania; 1894–1907). Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Watkin''s Tower", "description": "Folly in Londen, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de Watkin", "description": "Torre de celosía de hierro parcialmente terminada en Londres, Inglaterra. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour de Watkin", "description": "Tour inachevée de Londres. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Watkin''s Tower", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Bedford Castle', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 52.1357, -0.4635, 'http://commons.wikimedia.org/wiki/Special:FilePath/BitvauBedfordu1224.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BitvauBedfordu1224.jpg"}'::text[], 6, '{"en": {"name": "Bedford Castle", "description": "Castle in Bedfordshire, England, UK. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Bedford Castle", "description": "Archäologische Stätte im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Bedford Castle", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Bedford Castle", "description": "Kasteel in Bedford, het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Bedford Castle", "description": "Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Bedford", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Bedford Castle", "description": "Археологічна пам''ятка у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb);
