    (v_route, 'Letiště Oslo', 'Letecký cíl v Norsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 60.20278, 11.08389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oslo%20Airport%20terminal%20night%20view.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oslo%20Airport%20terminal%20night%20view.jpg"}'::text[], 0, '{"en": {"name": "Oslo Airport", "description": "International airport serving Oslo, Norway. An aviation sight in Norway — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Oslo-Gardermoen", "description": "Flughafen in Norwegen. Ein Luftfahrt-Ziel in Norwegen — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Oslo-Gardermoen", "description": "Port lotniczy w Norwegii. Cel lotniczy w Norwegii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Oslo Gardermoen", "description": "Vliegveld in Nannestad, Noorwegen. Een luchtvaartdoel in Noorwegen — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Oslo-Gardermoen", "description": "Principal aeropuerto de Noruega. Un destino aeronáutico en Noruega: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international d''Oslo-Gardermoen", "description": "Aéroport desservant Oslo, en Norvège. Un site aéronautique en Norvège — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Осло-Гардермуен", "description": "Аеропорт міста Осло. Авіаційна пам''ятка в Норвегії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Sognsvann', 'Vodní plocha v Norsku — příjemný cíl vyjížďky s výhledy na hladinu.', 59.97528, 10.7275, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sognsvann.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sognsvann.jpg"}'::text[], 1, '{"en": {"name": "Sognsvann", "description": "Lake in Norway. A body of water in Norway — a pleasant ride destination with waterside views."}, "de": {"name": "Sognsvann", "description": "See in Norwegen. Ein Gewässer in Norwegen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Sognsvann", "description": "Akwen w Norwegii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Sognsvann", "description": "Meer in Noorwegen. Een waterpartij in Noorwegen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Sognsvann", "description": "Lago en Noruega. Una masa de agua en Noruega: un destino agradable con vistas al agua."}, "fr": {"name": "Sognsvann", "description": "Lac en Norvège. Un plan d''eau en Norvège — une belle destination avec vue sur l''eau."}, "uk": {"name": "Согнсванн", "description": "Озеро в Норвегії. Водойма в Норвегії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Oslo Synagogue', 'Památka v Norsku — kus historie přímo u trasy.', 59.92581, 10.74329, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue%20Oslo%20.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue%20Oslo%20.JPG"}'::text[], 2, '{"en": {"name": "Oslo Synagogue", "description": "Jüdisches Gotteshaus in Oslo, Norwegen. A heritage sight in Norway — a piece of history right on your route."}, "de": {"name": "Synagoge Olso", "description": "Gebäude in Oslo, Norwegen. Ein Denkmal in Norwegen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Oslo", "description": "Zabytek w Norwegii — kawałek historii tuż przy trasie."}, "nl": {"name": "Oslo Synagogue", "description": "Een monument in Noorwegen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga de Oslo", "description": "Templo judío en Oslo, Noruega. Un monumento en Noruega: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue d''Oslo", "description": "Un monument en Norvège — un morceau d''histoire au bord de la route."}, "uk": {"name": "Oslo Synagogue", "description": "Пам''ятка в Норвегії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Olafa', 'Památka v Norsku — kus historie přímo u trasy.', 59.91816, 10.74413, 'http://commons.wikimedia.org/wiki/Special:FilePath/StOlavsOsloFeb2009.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/StOlavsOsloFeb2009.jpg"}'::text[], 3, '{"en": {"name": "St. Olav''s Cathedral", "description": "Cathedral in Oslo, Norway. A heritage sight in Norway — a piece of history right on your route."}, "de": {"name": "St. Olav", "description": "Kirchengebäude in Oslo. Ein Denkmal in Norwegen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Olafa w Oslo", "description": "Kościół w Norwegii. Zabytek w Norwegii — kawałek historii tuż przy trasie."}, "nl": {"name": "Domkerk Sint-Olaf", "description": "Kathedraal in Noorwegen. Een monument in Noorwegen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Olaf de Oslo", "description": "Templo católico de Oslo (Noruega). Un monumento en Noruega: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Olaf d''Oslo", "description": "Un monument en Norvège — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Олафа", "description": "Пам''ятка в Норвегії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála v Oslu', 'Kostel v Norsku. Památka v Norsku — kus historie přímo u trasy.', 59.91232, 10.74696, 'http://commons.wikimedia.org/wiki/Special:FilePath/00%207720%20Oslo%20-%20Domkirche.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/00%207720%20Oslo%20-%20Domkirche.jpg"}'::text[], 4, '{"en": {"name": "Oslo Cathedral", "description": "Cathedral in Oslo, Norway. A heritage sight in Norway — a piece of history right on your route."}, "de": {"name": "Osloer Dom", "description": "Kirchengebäude in Oslo. Ein Denkmal in Norwegen — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Oslo", "description": "Zabytek w Norwegii — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Oslo", "description": "Bouwwerk in Oslo. Een monument in Noorwegen — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral del Salvador de Oslo", "description": "Templo luterano de Oslo (Noruega). Un monumento en Noruega: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale d''Oslo", "description": "Église norvégienne. Un monument en Norvège — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Осло", "description": "Церква у Норвегії. Пам''ятка в Норвегії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Akershus', 'Hrad či zámek v Norsku — historická zastávka, která stojí za odbočku.', 59.90661, 10.73625, 'http://commons.wikimedia.org/wiki/Special:FilePath/OSLO-NO-02%2005%20ubt.jpeg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/OSLO-NO-02%2005%20ubt.jpeg"}'::text[], 5, '{"en": {"name": "Akershus Fortress", "description": "Former medieval castle in Oslo, Norway. A castle in Norway — a historic stop worth the detour."}, "de": {"name": "Festung Akershus", "description": "Burg und Museum in Norwegen. Eine Burg bzw. ein Schloss in Norwegen — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Twierdza Akershus", "description": "Zamek w Norwegii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Akershus", "description": "Vesting. Een kasteel in Noorwegen — een historische stop die de omweg waard is."}, "es": {"name": "Fortaleza de Akershus", "description": "Un castillo en Noruega: una parada histórica que merece el desvío."}, "fr": {"name": "citadelle d''Akershus", "description": "Citadelle à Oslo, de la fin du XIIIe siècle, durant le règne du roi Håkon V de Norvège. Un château en Norvège — une halte historique qui vaut le détour."}, "uk": {"name": "Фортеця Акерсхус", "description": "Замок в Норвегії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Øyeren', 'Vodní plocha v Norsku — příjemný cíl vyjížďky s výhledy na hladinu.', 59.85722, 11.16333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Oyern1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Oyern1.jpg"}'::text[], 6, '{"en": {"name": "Øyeren", "description": "Lake in Rælingen, Eastern Norway, Norway. A body of water in Norway — a pleasant ride destination with waterside views."}, "de": {"name": "Øyeren", "description": "See in Norwegen. Ein Gewässer in Norwegen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Øyeren", "description": "Jezioro w Norwegii. Akwen w Norwegii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Øyeren", "description": "Meer in Noorwegen. Een waterpartij in Noorwegen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago Øyeren", "description": "Una masa de agua en Noruega: un destino agradable con vistas al agua."}, "fr": {"name": "Øyeren", "description": "Lac en Norvège. Un plan d''eau en Norvège — une belle destination avec vue sur l''eau."}, "uk": {"name": "Еєрен", "description": "Озеро в Норвегії. Водойма в Норвегії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
