    (v_route, 'Letiště Manchester', 'Hlavní letiště v Manchesteru. Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 53.35389, -2.275, 'http://commons.wikimedia.org/wiki/Special:FilePath/Manchester%20Airport.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Manchester%20Airport.jpg"}'::text[], 0, '{"en": {"name": "Manchester Airport", "description": "International airport in Manchester, England. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Manchester", "description": "Internationaler Verkehrsflughafen im nordenglischen Manchester. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Manchester", "description": "Międzynarodowy port lotniczy w Manchesterze. Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Manchester Airport", "description": "Internationale luchthaven in Ringway, Verenigd Koninkrijk. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Mánchester", "description": "Aeropuerto de Gran Bretaña. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Manchester", "description": "Aéroport situé à Manchester, Angleterre (Royaume-Uni). Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Манчестер", "description": "Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Cathedral Church of St. John the Evangelist', 'Památka ve Velké Británii — kus historie přímo u trasy.', 53.48364, -2.26103, 'http://commons.wikimedia.org/wiki/Special:FilePath/Salford%20rc%20Cathedral.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Salford%20rc%20Cathedral.jpg"}'::text[], 1, '{"en": {"name": "Cathedral Church of St. John the Evangelist", "description": "Roman Catholic cathedral in Salford, Greater Manchester, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Salford", "description": "Kathedrale in Salford bei Manchester, England. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Salford", "description": "Świątynia katolicka. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Cathedral Church of St. John the Evangelist", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan Evangelista", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean-l''Évangéliste de Salford", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Cathedral Church of St. John the Evangelist", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'katedrála Panny Marie, sv. Denise a sv. Jiří v Manchesteru', 'Katedrála ve Spojeném království. Památka ve Velké Británii — kus historie přímo u trasy.', 53.48528, -2.24472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Manchester%20Cathedral%20-%20Aerial%20-%202024-06-16%2002.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Manchester%20Cathedral%20-%20Aerial%20-%202024-06-16%2002.jpg"}'::text[], 2, '{"en": {"name": "Manchester Cathedral", "description": "Church of England cathedral in Manchester, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Manchester", "description": "Englisches Kirchengebäude. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Manchesterze", "description": "Kościół anglikański. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Manchester", "description": "Bouwwerk in Manchester. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Mánchester", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Manchester", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "katedrála Panny Marie, sv. Denise a sv. Jiří v Manchesteru", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
