    (v_route, 'Letiště Bělehrad', 'Letecký cíl v Srbsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 44.81944, 20.30694, 'http://commons.wikimedia.org/wiki/Special:FilePath/Belgrade%20Nikola%20Tesla%20Airport%204.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Belgrade%20Nikola%20Tesla%20Airport%204.jpg"}'::text[], 0, '{"en": {"name": "Belgrade Nikola Tesla Airport", "description": "Main international airport of Serbia. An aviation sight in Serbia — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Nikola-Tesla-Flughafen Belgrad", "description": "Größter Flughafen Serbiens. Ein Luftfahrt-Ziel in Serbien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Belgrad", "description": "Port lotniczy w Serbii. Cel lotniczy w Serbii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Belgrado Nikola Tesla Airport", "description": "Surcin, grootste vliegveld van Servië, bij Belgrado. Een luchtvaartdoel in Servië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Belgrado-Nikola Tesla", "description": "Un destino aeronáutico en Serbia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport Nikola-Tesla de Belgrade", "description": "Aéroport situé à Belgrade en Serbie. Un site aéronautique en Serbie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт «Белград»", "description": "Авіаційна пам''ятка в Сербії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Bělehradská pevnost', 'Hrad či zámek v Srbsku — historická zastávka, která stojí za odbočku.', 44.8236, 20.4503, 'http://commons.wikimedia.org/wiki/Special:FilePath/Despotova%20kula6.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Despotova%20kula6.jpg"}'::text[], 1, '{"en": {"name": "Belgrade Fortress", "description": "Fortress in Serbia. A castle in Serbia — a historic stop worth the detour."}, "de": {"name": "Festung von Belgrad", "description": "Burg in Serbien. Eine Burg bzw. ein Schloss in Serbien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Bělehradská pevnost", "description": "Zamek w Serbii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Beogradska tvrdjava", "description": "Vesting in Belgrado, Servië. Een kasteel in Servië — een historische stop die de omweg waard is."}, "es": {"name": "Bělehradská pevnost", "description": "Un castillo en Serbia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse de Belgrade", "description": "Forteresse à Belgrade, quartier de Kalemegdan, Serbie. Un château en Serbie — une halte historique qui vaut le détour."}, "uk": {"name": "Белградська фортеця", "description": "Замок в Сербії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'chrám svatého Michala Archanděla v Bělehradě', 'Kostel v Bělehradě. Památka v Srbsku — kus historie přímo u trasy.', 44.81806, 20.45214, 'http://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B0%D0%B1%D0%BE%D1%80%D0%BD%D0%B0%20%D1%86%D1%80%D0%BA%D0%B2%D0%B0%20%D1%83%20%D0%91%D0%B5%D0%BE%D0%B3%D1%80%D0%B0%D0%B4%D1%83%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B0%D0%B1%D0%BE%D1%80%D0%BD%D0%B0%20%D1%86%D1%80%D0%BA%D0%B2%D0%B0%20%D1%83%20%D0%91%D0%B5%D0%BE%D0%B3%D1%80%D0%B0%D0%B4%D1%83%202.jpg"}'::text[], 2, '{"en": {"name": "St. Michael''s Cathedral", "description": "Church in Belgrade, Serbia. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Kathedrale Hl. Michael", "description": "Kirchengebäude in Belgrad. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Cerkiew katedralna świętego Michała Archanioła w Belgradzie", "description": "Świątynia prawosławna. Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Saborna crkva u Beogradu", "description": "Kathedraal in Servië. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Miguel", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Michel de Belgrade", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Архангела Михаїла (Белград)", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Belgrade Synagogue', 'Památka v Srbsku — kus historie přímo u trasy.', 44.81528, 20.45722, 'http://commons.wikimedia.org/wiki/Special:FilePath/Beogradska%20sinagoga.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Beogradska%20sinagoga.jpg"}'::text[], 3, '{"en": {"name": "Belgrade Synagogue", "description": "Synagogue in Belgrad, Serbia. A heritage sight in Serbia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Synagoge in Belgrad. Ein Denkmal in Serbien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga w Belgradzie", "description": "Zabytek w Serbii — kawałek historii tuż przy trasie."}, "nl": {"name": "Beogradska sinagoga", "description": "Bouwwerk in Servië. Een monument in Servië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga de Belgrado", "description": "Un monumento en Serbia: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue de Belgrade", "description": "Un monument en Serbie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Belgrade Synagogue", "description": "Пам''ятка в Сербії — шматочок історії просто на маршруті."}}'::jsonb),
