  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Berlín Brandenburg', 'Hlavní letiště v Berlíně. Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 52.36225, 13.50067, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20Brandenburg%20Airport%20Terminal%201%20at%20night.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20Brandenburg%20Airport%20Terminal%201%20at%20night.jpg"}'::text[], 0, '{"en": {"name": "Berlin Brandenburg Airport", "description": "Airport serving Berlin, Germany. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Berlin Brandenburg", "description": "Flughafen bei Berlin, Deutschland. Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "port lotniczy Berlin-Brandenburg", "description": "Port lotniczy na obrzeżach Berlina. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Berlijn Brandenburg", "description": "Internationale luchthaven in Schönefeld, Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Berlín Brandeburgo Willy Brandt", "description": "Principal aeropuerto que sirve a Berlín, Alemania. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Berlin-Brandebourg", "description": "Aéroport allemand a Berlin. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Берлін-Бранденбург", "description": "Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Berlínský palác', 'Palác v Berlíně v Německu. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 52.5175, 13.40278, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berlin-Mitte-Ehemaliges%20Berliner%20Schloss-ZI-0136-06-Th176311.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berlin-Mitte-Ehemaliges%20Berliner%20Schloss-ZI-0136-06-Th176311.jpg"}'::text[], 1, '{"en": {"name": "Berlin Palace", "description": "Former residence of the Prussian kings, seat of the Humboldt Forum. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Berliner Schloss", "description": "Ehemalige Residenz der preußischen Könige, Sitz des Humboldt Forums. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Berlinie", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Berliner Stadtschloss", "description": "Paleis in Berlijn, Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio Real de Berlín", "description": "Palacio real de Prusia, demolido en 1950 y parcialmente reconstruido en 2020. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Berlin", "description": "Château allemand. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Міський палац (Берлін)", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Evangelická katedrála v Berlíně', 'Katedrála v Berlíně. Památka v Německu — kus historie přímo u trasy.', 52.51917, 13.40111, 'http://commons.wikimedia.org/wiki/Special:FilePath/Berliner%20Dom%20von%20Humboldt-Box.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Berliner%20Dom%20von%20Humboldt-Box.jpg"}'::text[], 2, '{"en": {"name": "Berlin Cathedral", "description": "Main lutheran church in Berlin. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Berliner Dom", "description": "Evangelische Kirche und dynastische Grabstätte in Berlin. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Berlinie", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Dom van Berlijn", "description": "Kathedraal in Duitsland ontworpen door Julius Raschdorff. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Berlín", "description": "Templo luterano de Alemania. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "Berliner Dom", "description": "Église de Berlin. Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Берлінський собор", "description": "Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Berliner Fernsehturm', 'Televizní věž v Berlíně. Rozhledna v Německu — výhled do kraje jako odměna za zastávku.', 52.52083, 13.40944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tv-turm%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tv-turm%20-%20panoramio.jpg"}'::text[], 3, '{"en": {"name": "Fernsehturm Berlin", "description": "Television tower in Berlin. A lookout tower in Germany — sweeping views as a reward for stopping."}, "de": {"name": "Berliner Fernsehturm", "description": "Sende- und Aussichtsturm in Berlin. Ein Aussichtsturm in Deutschland — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "Fernsehturm w Berlinie", "description": "Wieża telewizyjna. Wieża widokowa w Niemczech — rozległe widoki w nagrodę za postój."}, "nl": {"name": "Fernsehturm", "description": "Bouwwerk in Berlijn. Een uitkijktoren in Duitsland — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre de televisión de Berlin", "description": "Torre de transmisión y observación en Berlín, Alemania. Un mirador en Alemania: amplias vistas como recompensa por la parada."}, "fr": {"name": "Fernsehturm de Berlin", "description": "Tour à Berlin. Une tour panoramique en Allemagne — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Берлінська телевежа", "description": "Телевежа, що є найвищою спорудою Німеччини. Оглядова вежа в Німеччині — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Vůdcův bunkr', 'Podzemní stavba v Berlíně. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 52.5125, 13.3815, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bundesarchiv%20Bild%20183-V04744%2C%20Berlin%2C%20Garten%20der%20zerst%C3%B6rte%20Reichskanzlei.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bundesarchiv%20Bild%20183-V04744%2C%20Berlin%2C%20Garten%20der%20zerst%C3%B6rte%20Reichskanzlei.jpg"}'::text[], 4, '{"en": {"name": "Führerbunker", "description": "Subterranean bunker complex used by Adolf Hitler in 1945. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Führerbunker", "description": "Führerhauptquartier von Adolf Hitler. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Führerbunker", "description": "Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Führerbunker", "description": "Bouwwerk in Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Führerbunker", "description": "Refugio antiaéreo cerca de la Cancillería del Reich en Berlín. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "Führerbunker", "description": "Bunker personnel d''Hitler à Berlin. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Фюрербункер", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Braniborská brána', 'Brána v Berlíně. Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 52.51627, 13.37772, 'http://commons.wikimedia.org/wiki/Special:FilePath/Brandenburger%20Tor%20morgens.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Brandenburger%20Tor%20morgens.jpg"}'::text[], 5, '{"en": {"name": "Brandenburg Gate", "description": "Triumphal arch in Berlin, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Brandenburger Tor", "description": "Klassizistisches Triumphtor in Berlin. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Brama Brandenburska", "description": "Łuk triumfalny (Berlin, Niemcy). Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Brandenburger Tor", "description": "Triomfboog in Berlijn, Duitsland. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Puerta de Brandeburgo", "description": "Puerta triunfal clásica en Berlín. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "porte de Brandebourg", "description": "Monument allemand situé à Berlin. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Бранденбурзькі ворота", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Zámek Charlottenburg', 'Hrad či zámek v Německu — historická zastávka, která stojí za odbočku.', 52.52111, 13.29583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Charlottenburg%202025.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Schloss%20Charlottenburg%202025.jpg"}'::text[], 6, '{"en": {"name": "Charlottenburg Palace", "description": "Baroque palace in Berlin, Germany. A castle in Germany — a historic stop worth the detour."}, "de": {"name": "Schloss Charlottenburg", "description": "Ehemalige Sommerresidenz der preußischen Könige in Berlin. Eine Burg bzw. ein Schloss in Deutschland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Pałac Charlottenburg", "description": "Pałac w Berlinie. Zamek w Niemczech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slot Charlottenburg", "description": "Bouwwerk in Berlijn. Een kasteel in Duitsland — een historische stop die de omweg waard is."}, "es": {"name": "Palacio de Charlottenburg", "description": "Palacio en Berlín, Alemania. Un castillo en Alemania: una parada histórica que merece el desvío."}, "fr": {"name": "château de Charlottenbourg", "description": "Ancienne résidence d''été des rois de Prusse à Berlin, Allemagne. Un château en Allemagne — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Шарлоттенбург", "description": "Замок в Німеччині — історична зупинка, варта об''їзду."}}'::jsonb);
