    (v_route, 'Letiště London City', 'Letiště ve Velké Británii. Letecký cíl ve Velké Británii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 51.50528, 0.05528, 'http://commons.wikimedia.org/wiki/Special:FilePath/London%20City%20Airport%20Zwart.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/London%20City%20Airport%20Zwart.jpg"}'::text[], 0, '{"en": {"name": "London City Airport", "description": "International airport in London, England. An aviation sight in the United Kingdom — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen London City", "description": "Internationaler Flughafen in London. Ein Luftfahrt-Ziel in Großbritannien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Londyn-City", "description": "Cel lotniczy w Wielkiej Brytanii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Londen City", "description": "Internationale luchthaven in Newham, Verenigd Koninkrijk. Een luchtvaartdoel in het Verenigd Koninkrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de la Ciudad de Londres", "description": "Aeropuerto de Gran Bretaña. Un destino aeronáutico en el Reino Unido: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Londres City", "description": "Aéroport situé à Londres au Royaume-Uni. Un site aéronautique au Royaume-Uni — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Лондон-Сіті", "description": "Авіаційна пам''ятка у Великій Британії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'ArcelorMittal Orbit', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.53833, -0.01333, 'http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ArcelorMittal%20Orbit%20at%20night.jpg"}'::text[], 1, '{"en": {"name": "ArcelorMittal Orbit", "description": "Sculpture and observation tower in the Olympic Park in Stratford, London. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "ArcelorMittal Orbit", "description": "Skulptur von Anish Kapoor und Cecil Balmond im Olympic Park in Stratford, London. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "ArcelorMittal Orbit", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "ArcelorMittal Orbit", "description": "Bouwwerk in Londen. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "ArcelorMittal Orbit", "description": "Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "tour Orbit", "description": "Œuvre de Anish Kapoor et Cecil Balmond. Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "ArcelorMittal Orbit", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Londýnské hradby', 'Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.5175, -0.09694, 'http://commons.wikimedia.org/wiki/Special:FilePath/London%20Roman%20Wall%20-%20surviving%20section%20by%20Tower%20Hill%20gardens.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/London%20Roman%20Wall%20-%20surviving%20section%20by%20Tower%20Hill%20gardens.jpg"}'::text[], 2, '{"en": {"name": "London Wall", "description": "Ancient defensive wall built by the Romans around Londinium. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "London Wall", "description": "Stadtmauer um Londinium und London. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Londýnské hradby", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "London Wall", "description": "Weermuur in City of London, Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Muralla de Londres", "description": "Muralla defensiva construida por los romanos alrededor de Londinium. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "mur de Londres", "description": "Ancien mur d''enceinte de Londres bâti à l''époque romaine. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Лондонська стіна", "description": "Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála v Southwarku', 'Katedrála v Anglii. Památka ve Velké Británii — kus historie přímo u trasy.', 51.50611, -0.08972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Northwest%20View%20of%20Southwark%20Cathedral%20%2801%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Northwest%20View%20of%20Southwark%20Cathedral%20%2801%29.jpg"}'::text[], 3, '{"en": {"name": "Southwark Cathedral", "description": "Mother church of the Anglican Diocese of Southwark. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Southwark Cathedral", "description": "Kirchengebäude in London. Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Southwark", "description": "Kościół anglikański w Londynie. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Southwark", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Southwark", "description": "Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Southwark", "description": "Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála v Southwarku", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Věž British Telecom', 'Rozhledna ve Velké Británii — výhled do kraje jako odměna za zastávku.', 51.5215, -0.1389, 'http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/BT%20Tower-1.jpg"}'::text[], 4, '{"en": {"name": "BT Tower", "description": "Communications tower located in Fitzrovia, London, England, UK. A lookout tower in the United Kingdom — sweeping views as a reward for stopping."}, "de": {"name": "BT Tower", "description": "Londoner Fernsehturm. Ein Aussichtsturm in Großbritannien — weite Ausblicke als Belohnung für den Stopp."}, "pl": {"name": "BT Tower", "description": "Wieża widokowa w Wielkiej Brytanii — rozległe widoki w nagrodę za postój."}, "nl": {"name": "BT Tower", "description": "Communicatietoren in Camden, Verenigd Koninkrijk. Een uitkijktoren in het Verenigd Koninkrijk — weidse uitzichten als beloning voor de stop."}, "es": {"name": "Torre BT", "description": "Torre de telecomunicaciones en Reino Unido. Un mirador en el Reino Unido: amplias vistas como recompensa por la parada."}, "fr": {"name": "BT Tower", "description": "Une tour panoramique au Royaume-Uni — un large panorama en récompense de l''arrêt."}, "uk": {"name": "Věž British Telecom", "description": "Оглядова вежа у Великій Британії — широкі краєвиди як нагорода за зупинку."}}'::jsonb),
    (v_route, 'Rochester', 'Hrad v Anglii. Hrad či zámek ve Velké Británii — historická zastávka, která stojí za odbočku.', 51.3898, 0.50163, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rochester%20Castle%20Keep%20and%20Bailey%200038stcp.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rochester%20Castle%20Keep%20and%20Bailey%200038stcp.JPG"}'::text[], 5, '{"en": {"name": "Rochester Castle", "description": "Castle in Rochester, Kent, South East England. A castle in the United Kingdom — a historic stop worth the detour."}, "de": {"name": "Rochester Castle", "description": "Burg im Vereinigten Königreich. Eine Burg bzw. ein Schloss in Großbritannien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Rochester", "description": "Zamek w Wielkiej Brytanii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Rochester Castle", "description": "Kasteel in het Verenigd Koninkrijk. Een kasteel in het Verenigd Koninkrijk — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Rochester", "description": "Castillo de Rochester, Inglaterra. Un castillo en el Reino Unido: una parada histórica que merece el desvío."}, "fr": {"name": "château de Rochester", "description": "Château britannique. Un château au Royaume-Uni — une halte historique qui vaut le détour."}, "uk": {"name": "Рочестерський замок", "description": "Замок у Великій Британії. Замок у Великій Британії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála v Rochesteru', 'Památka ve Velké Británii — kus historie přímo u trasy.', 51.38892, 0.50352, 'http://commons.wikimedia.org/wiki/Special:FilePath/Rochester%20Cathedral%20from%20west.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Rochester%20Cathedral%20from%20west.jpg"}'::text[], 6, '{"en": {"name": "Rochester Cathedral", "description": "Norman church in Rochester, Medway, Kent, England, UK. A heritage sight in the United Kingdom — a piece of history right on your route."}, "de": {"name": "Kathedrale von Rochester", "description": "Ein Denkmal in Großbritannien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Rochester", "description": "Budynek sakralny. Zabytek w Wielkiej Brytanii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Rochester", "description": "Kathedraal in het Verenigd Koninkrijk. Een monument in het Verenigd Koninkrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Rochester", "description": "Iglesia anglicana ubicada en Rochester, Inglaterra, Reino Unido. Un monumento en el Reino Unido: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de Rochester", "description": "Église britannique. Un monument au Royaume-Uni — un morceau d''histoire au bord de la route."}, "uk": {"name": "Рочестерський собор", "description": "Пам''ятка у Великій Британії — шматочок історії просто на маршруті."}}'::jsonb);
