  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Stockholm-Arlanda', 'Letecký cíl ve Švédsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 59.65194, 17.91861, 'http://commons.wikimedia.org/wiki/Special:FilePath/Arlanda%201%20Publish.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Arlanda%201%20Publish.jpg"}'::text[], 0, '{"en": {"name": "Stockholm Arlanda Airport", "description": "International airport serving Stockholm, Sweden. An aviation sight in Sweden — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Stockholm-Arlanda", "description": "Flughafen in Schweden. Ein Luftfahrt-Ziel in Schweden — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Sztokholm-Arlanda", "description": "Port lotniczy w Szwecji. Cel lotniczy w Szwecji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Stockholm-Arlanda", "description": "Internationale luchthaven in Sigtuna, Zweden. Een luchtvaartdoel in Zweden — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Estocolmo-Arlanda", "description": "Un aeropuerto internacional al norte de Estocolmo. Un destino aeronáutico en Suecia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Stockholm-Arlanda", "description": "Principal aéroport suédois desservant Stockholm. Un site aéronautique en Suède — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Стокгольм-Арланда", "description": "Авіаційна пам''ятка у Швеції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'zámek Skokloster', 'Barokní zámek ve Švédsku. Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.7038, 17.61941, 'http://commons.wikimedia.org/wiki/Special:FilePath/Skokloster%20fasad%202013b.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Skokloster%20fasad%202013b.jpg"}'::text[], 1, '{"en": {"name": "Skokloster Castle", "description": "Swedish Baroque castle on a peninsula of Lake Mälaren between Stockholm and Uppsala, built in the 17th century by Carl Gustaf Wrangel. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Schloss Skokloster", "description": "Barockschloss; größtes privates Schloss, das je in Schweden gebaut wurde. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Skokloster", "description": "Barokowy zamek (gm. Håbo, reg. Uppsala, Szwecja; od 1676). Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Skokloster", "description": "Wordt beschouwd als een van Europa''s mooiste barokke kasteel en is het grootste privékasteel dat ooit in Zweden is gebouwd, ook is het kasteel een monument voor de Zweedse tijd van grootheid. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Skokloster", "description": "Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Skokloster", "description": "Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Скуклостер", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála Uppsala', 'Památka ve Švédsku — kus historie přímo u trasy.', 59.85806, 17.63333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Uppsala%20domkyrka%2C%20flygbild%20%28cropped%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Uppsala%20domkyrka%2C%20flygbild%20%28cropped%29.jpg"}'::text[], 2, '{"en": {"name": "Uppsala Cathedral", "description": "Swedish cathedral. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Dom zu Uppsala", "description": "Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Uppsali", "description": "Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Uppsala", "description": "Zweedse kathedraal. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Uppsala", "description": "Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale d''Uppsala", "description": "Cathédrale située à Uppsala, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Уппсали", "description": "Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Mikuláše', 'Kostel ve Stockholmu. Památka ve Švédsku — kus historie přímo u trasy.', 59.32583, 18.07056, 'http://commons.wikimedia.org/wiki/Special:FilePath/Storkyrkan%202025%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Storkyrkan%202025%2001.jpg"}'::text[], 3, '{"en": {"name": "Storkyrkan", "description": "Lutheran cathedral in Stockholm. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Sankt Nikolai kyrka", "description": "Kirchengebäude in Stockholm. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Mikołaja w Sztokholmie", "description": "Luterańska katedra w Sztokholmie. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Storkyrkan", "description": "Bouwwerk in Stockholm. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Nicolás de Estocolmo", "description": "Catedral de Estocolmo, Suecia. Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Storkyrkan", "description": "Cathédrale située à Stockholm, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Церква Святого Миколая", "description": "Кафедральний собор Стокгольма. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Tre Kronor Castle', 'Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 59.32583, 18.07139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Slottet%20Tre%20Kronor%201661.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Slottet%20Tre%20Kronor%201661.jpg"}'::text[], 4, '{"en": {"name": "Tre Kronor Castle", "description": "Stronghold in Stockholm, later rebuilt into a castle and royal residence. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Burg Tre Kronor", "description": "Burganlage, die Birger Jarl errichtete und später zu Schloss und Residenz umgebaut wurde. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Tre Kronor Castle", "description": "Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Kasteel Tre Kronor", "description": "Was de burcht die Birger Jarl bouwde en later herbouwde tot het kasteel en de koninklijke residentie. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Tre Kronor", "description": "Fue la fortaleza que construyó Birger Jarl y luego fue reconstruida en el castillo y la residencia real. Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "Tre Kronor", "description": "Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Три корони (палац)", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'German Church', 'Památka ve Švédsku — kus historie přímo u trasy.', 59.32417, 18.07167, 'http://commons.wikimedia.org/wiki/Special:FilePath/Tyska%20kyrkan%20stadsbild%202012.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Tyska%20kyrkan%20stadsbild%202012.jpg"}'::text[], 5, '{"en": {"name": "German Church", "description": "Church building in Stockholm, Sweden. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Tyska kyrkan", "description": "Kirchengebäude in Stockholm. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół niemiecki w Sztokholmie", "description": "Kościół w Sztokholmie. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Tyska kyrkan", "description": "Bouwwerk in Stockholm. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia Alemana", "description": "Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église allemande", "description": "Bâtiment de la commune de Stockholm, Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Німецька церква", "description": "Євангелічно-лютеранська церква у центрі Стокгольма. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Erika', 'Římskokatolická katedrála v Stockholmu. Památka ve Švédsku — kus historie přímo u trasy.', 59.31381, 18.0725, 'http://commons.wikimedia.org/wiki/Special:FilePath/Stockholms%20katolska%20domkyrka%2003.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Stockholms%20katolska%20domkyrka%2003.jpg"}'::text[], 6, '{"en": {"name": "St. Eric''s Cathedral, Stockholm", "description": "Roman Catholic cathedral in Stockholm, Sweden. A heritage sight in Sweden — a piece of history right on your route."}, "de": {"name": "Domkirche St. Erich", "description": "Kathedrale in Schweden. Ein Denkmal in Schweden — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Eryka w Sztokholmie", "description": "Rzymskokatolicka katedra w Sztokholmie. Zabytek w Szwecji — kawałek historii tuż przy trasie."}, "nl": {"name": "Domkerk Sint-Erik", "description": "Kathedraal in Zweden. Een monument in Zweden — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Erik", "description": "Catedral de la diócesis católica de Estocolmo. Un monumento en Suecia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Éric de Stockholm", "description": "Édifice religieux située en Suède. Un monument en Suède — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Еріка (Стокгольм)", "description": "Католицька церква у Стокгольмі. Пам''ятка у Швеції — шматочок історії просто на маршруті."}}'::jsonb);
