  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Dublin', 'Letiště v Irsku. Letecký cíl v Irsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 53.42139, -6.27, 'http://commons.wikimedia.org/wiki/Special:FilePath/Departure%20from%20Dublin%20Airport%20onboard%20Aer%20Lingus%20A320.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Departure%20from%20Dublin%20Airport%20onboard%20Aer%20Lingus%20A320.jpg"}'::text[], 0, '{"en": {"name": "Dublin Airport", "description": "International airport in Dublin, Ireland. An aviation sight in Ireland — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Dublin", "description": "Flughafen in Irland. Ein Luftfahrt-Ziel in Irland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Dublin", "description": "Port lotniczy w Irlandii. Cel lotniczy w Irlandii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Dublin Airport", "description": "Internationale luchthaven in Fingal, Ierland. Een luchtvaartdoel in Ierland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Dublín", "description": "Aeropuerto irlandés. Un destino aeronáutico en Irlanda: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Dublin", "description": "Aéroport desservant Dublin en Irlande. Un site aéronautique en Irlande — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Дублінський аеропорт", "description": "Авіаційна пам''ятка в Ірландії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'St Mary''s Cathedral', 'Památka v Irsku — kus historie přímo u trasy.', 53.35083, -6.25917, 'http://commons.wikimedia.org/wiki/Special:FilePath/St.%20Mary%E2%80%99s%20Pro-Cathedral%2C%20Dublin%202023%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St.%20Mary%E2%80%99s%20Pro-Cathedral%2C%20Dublin%202023%20%282%29.jpg"}'::text[], 1, '{"en": {"name": "St Mary''s Cathedral", "description": "Church in Dublin, Ireland. A heritage sight in Ireland — a piece of history right on your route."}, "de": {"name": "Pro-Cathedral of the Immaculate Conception of the Blessed Virgin Mary", "description": "Kirchengebäude in Dublin. Ein Denkmal in Irland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Prokatedra Najświętszej Maryi Panny w Dublinie", "description": "Świątynia katolicka. Zabytek w Irlandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Saint Mary''s Pro-Cathedral", "description": "Bouwwerk in Dublin. Een monument in Ierland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Procatedral de Santa María", "description": "Un monumento en Irlanda: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Sainte-Marie de Dublin", "description": "Pro-cathédrale catholique de Dublin. Un monument en Irlande — un morceau d''histoire au bord de la route."}, "uk": {"name": "St Mary''s Cathedral", "description": "Пам''ятка в Ірландії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Dublinský zámek', 'Zámek v Irsku. Hrad či zámek v Irsku — historická zastávka, která stojí za odbočku.', 53.34311, -6.26739, 'http://commons.wikimedia.org/wiki/Special:FilePath/Dublin%20castle.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Dublin%20castle.JPG"}'::text[], 2, '{"en": {"name": "Dublin Castle", "description": "Castle. A castle in Ireland — a historic stop worth the detour."}, "de": {"name": "Dublin Castle", "description": "Schloss in Dublin, Irland. Eine Burg bzw. ein Schloss in Irland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Dubliński", "description": "Zamek królewski w Dublinie. Zamek w Irlandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Dublin Castle", "description": "Kasteel in Dublin, Ierland. Een kasteel in Ierland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Dublín", "description": "Sede del Gobierno británico en Irlanda hasta 1922. Un castillo en Irlanda: una parada histórica que merece el desvío."}, "fr": {"name": "château de Dublin", "description": "Château qui fut le siège du pouvoir britannique à Dublin. Un château en Irlande — une halte historique qui vaut le détour."}, "uk": {"name": "Дублінський замок", "description": "Замок (споруда). Замок в Ірландії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Katedrála Nejsvětější Trojice', 'Katedrála v Dublinu. Památka v Irsku — kus historie přímo u trasy.', 53.34306, -6.27139, 'http://commons.wikimedia.org/wiki/Special:FilePath/Christ%20Church%20Cathedral%20%28Dublin%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Christ%20Church%20Cathedral%20%28Dublin%29.jpg"}'::text[], 3, '{"en": {"name": "Christ Church Cathedral, Dublin", "description": "Diocesan cathedral of Dublin and Glendalough, Church of Ireland. A heritage sight in Ireland — a piece of history right on your route."}, "de": {"name": "Christ Church Cathedral", "description": "Kirchengebäude in Dublin, Irland. Ein Denkmal in Irland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Kościoła Chrystusowego w Dublinie", "description": "Kościół anglikański. Zabytek w Irlandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Christ Church Cathedral", "description": "Kathedraal in Ierland. Een monument in Ierland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de la Santísima Trinidad de Dublín", "description": "Un monumento en Irlanda: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Christ Church de Dublin", "description": "Un monument en Irlande — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála Nejsvětější Trojice", "description": "Пам''ятка в Ірландії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Katedrála svatého Patrika', 'Katedrála v Dublinu. Památka v Irsku — kus historie přímo u trasy.', 53.33944, -6.27139, 'http://commons.wikimedia.org/wiki/Special:FilePath/St%20Patrick%27s%20Cathedral%20Exterior%2C%20Dublin%2C%20Ireland%20-%20Diliff.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/St%20Patrick%27s%20Cathedral%20Exterior%2C%20Dublin%2C%20Ireland%20-%20Diliff.jpg"}'::text[], 4, '{"en": {"name": "St Patrick''s Cathedral", "description": "Cathedral in Dublin, Ireland. A heritage sight in Ireland — a piece of history right on your route."}, "de": {"name": "St. Patrick’s Cathedral", "description": "Kirchengebäude in Dublin. Ein Denkmal in Irland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Patryka w Dublinie", "description": "Kościół anglikański. Zabytek w Irlandii — kawałek historii tuż przy trasie."}, "nl": {"name": "Saint Patrick''s Cathedral", "description": "Kathedraal in Ierland. Een monument in Ierland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Patricio de Dublín", "description": "Un monumento en Irlanda: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Patrick de Dublin", "description": "Cathédrale nationale de l''Église d''Irlande, à Dublin. Un monument en Irlande — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Святого Патрика", "description": "Кафедральний собор Дубліна. Пам''ятка в Ірландії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Powerscourt Waterfall', 'Přírodní zajímavost v Irsku — místo na protažení nohou uprostřed přírody.', 53.146, -6.211, 'http://commons.wikimedia.org/wiki/Special:FilePath/Powerscourt%20Waterfall%2C%202011.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Powerscourt%20Waterfall%2C%202011.jpg"}'::text[], 5, '{"en": {"name": "Powerscourt Waterfall", "description": "Waterfall in Wicklow, Ireland. A natural sight in Ireland — a spot to stretch your legs amid nature."}, "de": {"name": "Powerscourt Waterfall", "description": "Wasserfall in Irland. Eine Natursehenswürdigkeit in Irland — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Powerscourt", "description": "Wodospad w Irlandii. Atrakcja przyrodnicza w Irlandii — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Powerscourtwaterval", "description": "Een natuurbezienswaardigheid in Ierland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cascada Powerscourt", "description": "Un paraje natural en Irlanda: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "cascade Powerscourt", "description": "Plus haute chute d''Irlande. Un site naturel en Irlande — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Powerscourt Waterfall", "description": "Природна пам''ятка в Ірландії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Slane Castle', 'Hrad či zámek v Irsku — historická zastávka, která stojí za odbočku.', 53.70942, -6.56125, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Slane%2005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Slane%2005.jpg"}'::text[], 6, '{"en": {"name": "Slane Castle", "description": "Castle in Ireland. A castle in Ireland — a historic stop worth the detour."}, "de": {"name": "Slane", "description": "Burg in Irland. Eine Burg bzw. ein Schloss in Irland — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek w Slane", "description": "Zamek w Irlandii. Zamek w Irlandii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Slane Castle", "description": "Kasteel in Ierland. Een kasteel in Ierland — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Slane", "description": "Un castillo en Irlanda: una parada histórica que merece el desvío."}, "fr": {"name": "Slane Castle", "description": "Château en Irlande. Un château en Irlande — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Слейн", "description": "Замок в Ірландії — історична зупинка, варта об''їзду."}}'::jsonb);
