  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Ženeva', 'Mezinárodní letiště v Ženevě. Letecký cíl ve Švýcarsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 46.23833, 6.10944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Geneva%20airport%20from%20air.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Geneva%20airport%20from%20air.jpg"}'::text[], 0, '{"en": {"name": "Geneva International Airport", "description": "International airport serving Geneva, Switzerland. An aviation sight in Switzerland — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Genf", "description": "Flughafen in der Schweiz. Ein Luftfahrt-Ziel in der Schweiz — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Genewa-Cointrin", "description": "Port lotniczy w Szwajcarii. Cel lotniczy w Szwajcarii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Genève", "description": "Vliegveld in Meyrin, Zwitserland. Een luchtvaartdoel in Zwitserland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional de Ginebra", "description": "Infraestructura de transporte de Ginebra, Suiza. Un destino aeronáutico en Suiza: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Genève", "description": "Aéroport desservant Genève, canton de Genève, Suisse. Un site aéronautique en Suisse — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Женева", "description": "Авіаційна пам''ятка у Швейцарії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Basilica Notre-Dame of Geneva', 'Památka ve Švýcarsku — kus historie přímo u trasy.', 46.20872, 6.1422, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilique%20Notre-Dame%2C%20Gen%C3%A8ve.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilique%20Notre-Dame%2C%20Gen%C3%A8ve.jpg"}'::text[], 1, '{"en": {"name": "Basilica Notre-Dame of Geneva", "description": "The main Roman Catholic church in Geneva, Switzerland. A heritage sight in Switzerland — a piece of history right on your route."}, "de": {"name": "Notre-Dame de Genève", "description": "Kirchengebäude in der Schweiz. Ein Denkmal in der Schweiz — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika Najświętszej Marii Panny w Genewie", "description": "Zabytek w Szwajcarii — kawałek historii tuż przy trasie."}, "nl": {"name": "Basilica Notre-Dame of Geneva", "description": "Kerkgebouw in Genève, Zwitserland. Een monument in Zwitserland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Nuestra Señora de Ginebra", "description": "Un monumento en Suiza: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Notre-Dame de Genève", "description": "La principale église catholique à Genève, Suisse. Un monument en Suisse — un morceau d''histoire au bord de la route."}, "uk": {"name": "Basilica Notre-Dame of Geneva", "description": "Пам''ятка у Швейцарії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Beth Yaakov Synagogue', 'Památka ve Švýcarsku — kus historie přímo u trasy.', 46.20278, 6.14083, 'http://commons.wikimedia.org/wiki/Special:FilePath/Beth%20Yaacov%20Place%20Sud.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Beth%20Yaacov%20Place%20Sud.JPG"}'::text[], 2, '{"en": {"name": "Beth Yaakov Synagogue", "description": "Church building in Geneva, Switzerland. A heritage sight in Switzerland — a piece of history right on your route."}, "de": {"name": "Synagoge Beth-Yaacov (Genf)", "description": "Synagoge in Genf, Schweiz. Ein Denkmal in der Schweiz — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Beth Yaakov Synagogue", "description": "Zabytek w Szwajcarii — kawałek historii tuż przy trasie."}, "nl": {"name": "Beth Yaakov Synagogue", "description": "Synagoge in Genève, Zwitserland. Een monument in Zwitserland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Sinagoga Beth-Yaacov de Ginebra", "description": "Un monumento en Suiza: un pedazo de historia junto a la ruta."}, "fr": {"name": "synagogue Beth-Yaacov de Genève", "description": "Synagogue à Genève, Suisse. Un monument en Suisse — un morceau d''histoire au bord de la route."}, "uk": {"name": "Beth Yaakov Synagogue", "description": "Пам''ятка у Швейцарії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'katedrála svatého Petra v Ženevě', 'Památka ve Švýcarsku — kus historie přímo u trasy.', 46.20111, 6.14861, 'http://commons.wikimedia.org/wiki/Special:FilePath/Fa%C3%A7ade%20de%20la%20cath%C3%A9drale%20Saint-Pierre%20de%20Gen%C3%A8ve%202009-07-11.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Fa%C3%A7ade%20de%20la%20cath%C3%A9drale%20Saint-Pierre%20de%20Gen%C3%A8ve%202009-07-11.jpg"}'::text[], 3, '{"en": {"name": "St. Pierre Cathedral", "description": "Protestant cathedral in Geneva. A heritage sight in Switzerland — a piece of history right on your route."}, "de": {"name": "Kathedrale Sankt Peter", "description": "Kirchengebäude in Genf. Ein Denkmal in der Schweiz — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Piotra w Genewie", "description": "Zabytek w Szwajcarii — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Genève", "description": "Bouwwerk in Genève. Een monument in Zwitserland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Ginebra", "description": "Catedral de Suiza. Un monumento en Suiza: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Pierre de Genève", "description": "Cathédrale protestante de Genève. Un monument en Suisse — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор святого Петра", "description": "Протестантський кафедральний собор в Женеві. Пам''ятка у Швейцарії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Russian Orthodox Church of Geneva', 'Památka ve Švýcarsku — kus historie přímo u trasy.', 46.19888, 6.15379, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C3%89glise%20russe%20de%20Gen%C3%A8ve%20-%20JeP%202019%20-%20Fa%C3%A7ade%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C3%89glise%20russe%20de%20Gen%C3%A8ve%20-%20JeP%202019%20-%20Fa%C3%A7ade%2001.jpg"}'::text[], 4, '{"en": {"name": "Russian Orthodox Church of Geneva", "description": "Russian Cathedral in Geneva, Switzerland. A heritage sight in Switzerland — a piece of history right on your route."}, "de": {"name": "Kreuzerhöhungskathedrale", "description": "Russisch-orthodoxe Kathedrale in Genf, Schweiz. Ein Denkmal in der Schweiz — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sobór Podwyższenia Krzyża Pańskiego w Genewie", "description": "Zabytek w Szwajcarii — kawałek historii tuż przy trasie."}, "nl": {"name": "Russian Orthodox Church of Geneva", "description": "Oosters-orthodox kerkgebouw in Zwitserland. Een monument in Zwitserland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Russian Orthodox Church of Geneva", "description": "Un monumento en Suiza: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale de l''Exaltation-de-la-Sainte-Croix de Genève", "description": "Cathédrale russe orthodoxe à Genève, Suisse. Un monument en Suisse — un morceau d''histoire au bord de la route."}, "uk": {"name": "Russian Orthodox Church of Geneva", "description": "Пам''ятка у Швейцарії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Toblerone Line', 'Hrad či zámek ve Švýcarsku — historická zastávka, která stojí za odbočku.', 46.40217, 6.28017, 'http://commons.wikimedia.org/wiki/Special:FilePath/Serine03.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Serine03.JPG"}'::text[], 5, '{"en": {"name": "Toblerone Line", "description": "Defensive fortifications of Vaud, Switzerland, from WWII. A castle in Switzerland — a historic stop worth the detour."}, "de": {"name": "Tobleroneweg", "description": "Ab 1938 gebaute Schweizer Verteidigungslinie, heute Wanderweg. Eine Burg bzw. ein Schloss in der Schweiz — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Toblerone Line", "description": "Zamek w Szwajcarii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Toblerone Line", "description": "Een kasteel in Zwitserland — een historische stop die de omweg waard is."}, "es": {"name": "Toblerone Line", "description": "Un castillo en Suiza: una parada histórica que merece el desvío."}, "fr": {"name": "ligne des Toblerones", "description": "Ligne de fortifications de la deuxième guerre mondiale dans le canton de Vaud, Suisse. Un château en Suisse — une halte historique qui vaut le détour."}, "uk": {"name": "Toblerone Line", "description": "Замок у Швейцарії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Château Allaman', 'Hrad či zámek ve Švýcarsku — historická zastávka, která stojí za odbočku.', 46.47132, 6.39784, 'http://commons.wikimedia.org/wiki/Special:FilePath/Allaman%2C%20ch%C3%A2teau%20d%27Allaman%2C%2014-03-2013%2005.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Allaman%2C%20ch%C3%A2teau%20d%27Allaman%2C%2014-03-2013%2005.jpg"}'::text[], 6, '{"en": {"name": "Château Allaman", "description": "Castle in Allaman in the canton of Vaud, Switzerland. A castle in Switzerland — a historic stop worth the detour."}, "de": {"name": "Schloss Allaman", "description": "Schloss in Allaman im Kanton Waadt, Schweiz. Eine Burg bzw. ein Schloss in der Schweiz — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Château Allaman", "description": "Zamek w Szwajcarii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Allaman Castle", "description": "Kasteel in Vaud, Zwitserland. Een kasteel in Zwitserland — een historische stop die de omweg waard is."}, "es": {"name": "Château Allaman", "description": "Un castillo en Suiza: una parada histórica que merece el desvío."}, "fr": {"name": "château d''Allaman", "description": "Château en Suisse. Un château en Suisse — une halte historique qui vaut le détour."}, "uk": {"name": "Château Allaman", "description": "Замок у Швейцарії — історична зупинка, варта об''їзду."}}'::jsonb);
