    (v_route, 'Letiště Hamburk', 'Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 53.63039, 9.98823, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hamburg%20airport%20terminals.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hamburg%20airport%20terminals.jpg"}'::text[], 0, '{"en": {"name": "Hamburg Airport", "description": "Airport in Fuhlsbüttel, Hamburg, Germany. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Hamburg", "description": "Flughafen in Hamburg-Fuhlsbüttel. Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Hamburg-Fuhlsbüttel", "description": "Port lotniczy w Niemczech. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Hamburg", "description": "Internationale luchthaven in Hamburg, Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Hamburgo-Fuhlsbüttel", "description": "Aeropuerto internacional de Hamburgo, Alemania. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Hambourg", "description": "Aéroport desservant Hambourg, Allemagne. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Гамбург", "description": "Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Außenalster', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 53.565, 10.01, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Binnenalster%20and%20Au%C3%9Fenalster%20%28view%20from%20the%20southwest%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20Binnenalster%20and%20Au%C3%9Fenalster%20%28view%20from%20the%20southwest%29.jpg"}'::text[], 1, '{"en": {"name": "Außenalster", "description": "Lake and reservoir in Hamburg, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Außenalster", "description": "See in Hamburg. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Außenalster", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Außenalster", "description": "Stuwmeer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Außenalster", "description": "Embalse de Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Außenalster", "description": "Lac allemand. Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Außenalster", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
