    (v_route, 'Letiště Orio al Serio', 'Letecký cíl v Itálii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 45.66547, 9.69948, 'http://commons.wikimedia.org/wiki/Special:FilePath/Orio%20al%20Serio%20International%20Airport%202025.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Orio%20al%20Serio%20International%20Airport%202025.jpg"}'::text[], 0, '{"en": {"name": "Bergamo-Il Caravaggio", "description": "International airport serving Bergamo, Italy. An aviation sight in Italy — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Bergamo", "description": "Flughafen in Italien. Ein Luftfahrt-Ziel in Italien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Bergamo-Orio al Serio", "description": "Port lotniczy we Włoszech. Cel lotniczy we Włoszech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Orio al Serio", "description": "Vliegveld in Orio al Serio, Italië. Een luchtvaartdoel in Italië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Bérgamo-Orio al Serio", "description": "Aeropuerto internacional en el norte de Italia, situado a 45 km al noreste de Milán y a 5 km al sureste de Bérgamo, en el municipio lombardo de Orio al Serio. Un destino aeronáutico en Italia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Bergame-Orio al Serio", "description": "Aéroport desservant Milan, Italie. Un site aéronautique en Italie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Оріо-аль-Серіо", "description": "Авіаційна пам''ятка в Італії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Bergamo Cathedral', 'Památka v Itálii — kus historie přímo u trasy.', 45.70331, 9.6629, 'http://commons.wikimedia.org/wiki/Special:FilePath/Bergamo%20katedra%2003.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Bergamo%20katedra%2003.jpg"}'::text[], 1, '{"en": {"name": "Bergamo Cathedral", "description": "Cathedral. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Dom zu Bergamo", "description": "Kathedrale in Bergamo. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Bergamo", "description": "Świątynia katolicka w Bergamo. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Bergamo Cathedral", "description": "Kathedraal in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Alejandro", "description": "Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Alexandre de Bergame", "description": "Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Bergamo Cathedral", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
