    (v_route, 'Letiště Benátky Marco Polo', 'Mezinárodní letiště v Itálii. Letecký cíl v Itálii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 45.50528, 12.35194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aeroporto%20di%20Venezia-Tessera%20%286%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aeroporto%20di%20Venezia-Tessera%20%286%29.jpg"}'::text[], 0, '{"en": {"name": "Venice Marco Polo Airport", "description": "International airport serving Venice, Italy. An aviation sight in Italy — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Venedig-Tessera", "description": "Flughafen in Italien. Ein Luftfahrt-Ziel in Italien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Wenecja-Marco Polo", "description": "Port lotniczy we Włoszech. Cel lotniczy we Włoszech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Venetië Marco Polo", "description": "Internationale luchthaven in Italië. Een luchtvaartdoel in Italië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional Marco Polo", "description": "Aeropuerto Internacional en Italia. Un destino aeronáutico en Italia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Venise - Marco-Polo", "description": "Aéroport desservant Venise, en Italie. Un site aéronautique en Italie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Венеція-Марко Поло", "description": "Авіаційна пам''ятка в Італії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Bazilika Santa Maria Gloriosa dei Frari', 'Církevní budova v Benátkách, Itálie. Památka v Itálii — kus historie přímo u trasy.', 45.43693, 12.32649, 'http://commons.wikimedia.org/wiki/Special:FilePath/Facade%20of%20Santa%20Maria%20Gloriosa%20dei%20Frari%20%28Venice%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Facade%20of%20Santa%20Maria%20Gloriosa%20dei%20Frari%20%28Venice%29.jpg"}'::text[], 1, '{"en": {"name": "Santa Maria Gloriosa dei Frari", "description": "Church in Venice. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Santa Maria Gloriosa dei Frari", "description": "Kirchengebäude in Venedig. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Santa Maria Gloriosa dei Frari", "description": "Kościół katolicki w Wenecji. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basilica di Santa Maria Gloriosa dei Frari", "description": "Bouwwerk in Venetië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa María dei Frari", "description": "Iglesia en Venecia, Italia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Sainte-Marie-Glorieuse-des-Frères de Venise", "description": "Église à Venise. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Санта-Марія-Глоріоза-дей-Фрарі", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'bazilika Panny Marie zdraví', 'Církevní budova v Benátkách, Itálie. Památka v Itálii — kus historie přímo u trasy.', 45.43057, 12.33473, 'http://commons.wikimedia.org/wiki/Special:FilePath/Santa%20Maria%20della%20Salute%20from%20Hotel%20Monaco.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Santa%20Maria%20della%20Salute%20from%20Hotel%20Monaco.jpg"}'::text[], 2, '{"en": {"name": "Santa Maria della Salute", "description": "Church in Venice, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Santa Maria della Salute", "description": "Kirchengebäude im Sestiere Dorsoduro, Venedig. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Santa Maria della Salute", "description": "Kościół w Wenecji. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basiliek van Santa Maria della Salute", "description": "Kerkgebouw in Venetië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de Santa Maria della Salute", "description": "Basílica de Venecia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Santa Maria della Salute de Venise", "description": "Édifice religieux italien. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Санта-Марія-делла-Салюте", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika svatého Marka', 'Hlavní benátský kostel v byzantském slohu, založený v 10. století. Památka v Itálii — kus historie přímo u trasy.', 45.43444, 12.33972, 'http://commons.wikimedia.org/wiki/Special:FilePath/Venice%20-%20St.%20Marc%27s%20Basilica%2001.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Venice%20-%20St.%20Marc%27s%20Basilica%2001.jpg"}'::text[], 3, '{"en": {"name": "St Mark''s Basilica", "description": "Church in Venice, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Markusdom", "description": "Kathedrale in Venedig. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Marka w Wenecji", "description": "Kościół w Wenecji. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basiliek van San Marco", "description": "Kathedraal in Venetië, Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Marcos", "description": "Basílica menor en Venecia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Marc", "description": "Édifice religieux situé à Venise, Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "собор Святого Марка", "description": "Католицька церква у Венеції (Італія). Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Bazilika San Giorgio Maggiore', 'Kostel v Benátkách. Památka v Itálii — kus historie přímo u trasy.', 45.4293, 12.3433, 'http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20San%20Giorgio%20Maggiore%20%28Venice%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Basilica%20di%20San%20Giorgio%20Maggiore%20%28Venice%29.jpg"}'::text[], 4, '{"en": {"name": "Church of San Giorgio Maggiore", "description": "Basilica on the Island of San Giorgio Maggiore in Venice. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "San Giorgio Maggiore", "description": "Kirche in Venedig. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół San Giorgio Maggiore", "description": "Kościół katolicki w Wenecji. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "kerk van San Giorgio Maggiore", "description": "Bouwwerk in Venetië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Giorgio Maggiore", "description": "Basílica de San Giorgio Maggiore en Venecia. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique San Giorgio Maggiore de Venise", "description": "Basilique sur l''île de San Giorgio Maggiore à Venise. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Сан-Джорджо-Маджоре", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Benátská laguna', 'Vodní plocha spojená s Benátským zálivem. Vodní plocha v Itálii — příjemný cíl vyjížďky s výhledy na hladinu.', 45.41306, 12.29722, 'http://commons.wikimedia.org/wiki/Special:FilePath/The%20Venetian%20Lagoon%20ESA25362327%20%28cropped%29.tiff', '{"http://commons.wikimedia.org/wiki/Special:FilePath/The%20Venetian%20Lagoon%20ESA25362327%20%28cropped%29.tiff"}'::text[], 5, '{"en": {"name": "Venetian Lagoon", "description": "Enclosed bay of the Adriatic Sea. A body of water in Italy — a pleasant ride destination with waterside views."}, "de": {"name": "Lagune von Venedig", "description": "Meerbusen im Norden des Adriatischen Meeres. Ein Gewässer in Italien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Laguna Wenecka", "description": "Laguna na Morzu Adriatyckim, w zachodniej części Zatoki Weneckiej. Akwen we Włoszech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lagune van Venetië", "description": "Baai in de Adriatische Zee. Een waterpartij in Italië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Laguna de Venecia", "description": "Accidente geográfico de Italia. Una masa de agua en Italia: un destino agradable con vistas al agua."}, "fr": {"name": "lagune de Venise", "description": "Lagune de la mer Adriatique. Un plan d''eau en Italie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Венеційська лагуна", "description": "Водойма в Італії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Bazilika svatého Antonína v Padově', 'Památka v Itálii — kus historie přímo u trasy.', 45.40137, 11.88053, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sant%27Antonio%20%28Padua%29%20-%20Facade.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sant%27Antonio%20%28Padua%29%20-%20Facade.jpg"}'::text[], 6, '{"en": {"name": "Basilica of Saint Anthony of Padua", "description": "Church in Padua, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Basilika des heiligen Antonius", "description": "Gebäude in Padua, Venetien. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Antoniego w Padwie", "description": "Kościół rzymskokatolicki. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "Basilica di Sant''Antonio", "description": "Bouwwerk in Padua, Veneto. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Basílica de San Antonio de Padua", "description": "Iglesia católica en Padua (Italia). Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "église du Santo", "description": "Basilique à Padoue, Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Антонія", "description": "Церква в Падуї, Італія. Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb);
