  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Ference Liszta Budapešť', 'Letiště v Maďarsku. Letecký cíl v Maďarsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 47.43944, 19.26194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aeropark%20l%C3%A9gi%20felv%C3%A9telen.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aeropark%20l%C3%A9gi%20felv%C3%A9telen.jpg"}'::text[], 0, '{"en": {"name": "Budapest Ferenc Liszt International Airport", "description": "Airport in Budapest, Hungary. An aviation sight in Hungary — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Budapest Liszt Ferenc", "description": "Internationaler Verkehrsflughafen der ungarischen Hauptstadt Budapest. Ein Luftfahrt-Ziel in Ungarn — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Budapest Liszt Ferenc", "description": "Port lotniczy na Węgrzech. Cel lotniczy na Węgrzech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven van Boedapest", "description": "Vliegveld in Boedapest, Hongarije. Een luchtvaartdoel in Hongarije — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Budapest-Ferenc Liszt", "description": "Infraestructura de transporte de Budapest, Hungría. Un destino aeronáutico en Hungría: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Budapest-Ferenc Liszt", "description": "Aéroport desservant Budapest, en Hongrie. Un site aéronautique en Hongrie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт імені Ференца Ліста", "description": "Аеропорт в Угорщині. Авіаційна пам''ятка в Угорщині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'hrad Vajdahunyad', 'Hrad v Budapešti. Hrad či zámek v Maďarsku — historická zastávka, která stojí za odbočku.', 47.51528, 19.08194, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vajdahunyad%20v%C3%A1ra%20Budapest%20September%202013.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vajdahunyad%20v%C3%A1ra%20Budapest%20September%202013.jpg"}'::text[], 1, '{"en": {"name": "Vajdahunyad Castle", "description": "Castle. A castle in Hungary — a historic stop worth the detour."}, "de": {"name": "Burg Vajdahunyad", "description": "Burg in Ungarn. Eine Burg bzw. ein Schloss in Ungarn — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Vajdahunyad", "description": "Zamek na Węgrzech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Vajdahunyadburcht", "description": "Bouwwerk in Boedapest. Een kasteel in Hongarije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Vajdahunyad", "description": "Un castillo en Hungría: una parada histórica que merece el desvío."}, "fr": {"name": "château de Vajdahunyad", "description": "Un château en Hongrie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Вайдахуняд", "description": "Замок (споруда). Замок в Угорщині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Bazilika svatého Štěpána', 'Římskokatolická bazilika v Budapešti. Památka v Maďarsku — kus historie přímo u trasy.', 47.50083, 19.05389, 'http://commons.wikimedia.org/wiki/Special:FilePath/HUN-2015-Budapest-St.%20Stephen%27s%20Basilica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/HUN-2015-Budapest-St.%20Stephen%27s%20Basilica.jpg"}'::text[], 2, '{"en": {"name": "St. Stephen''s Basilica", "description": "Roman Catholic basilica in Budapest, Hungary. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "St.-Stephans-Basilika", "description": "Kirchengebäude in Budapest, Ungarn. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Stefana w Budapeszcie", "description": "Świątynia katolicka. Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Sint-Stefanusbasiliek", "description": "Bouwwerk in Boedapest. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Esteban", "description": "Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Étienne de Pest", "description": "Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Святого Іштвана", "description": "Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Velká synagoga', 'Maďarská synagoga se sídlem v Budapešti, postavená v letech 1854-1859. Největší synagoga v Evropě a jedna z největších synagog na světě. Památka v Maďarsku — kus historie přímo u trasy.', 47.4959, 19.0607, 'http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue-Budapest.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Synagogue-Budapest.jpg"}'::text[], 3, '{"en": {"name": "Dohány Street Synagogue", "description": "Synagogue in Budapest, Hungary. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "Große Synagoge", "description": "Synagoge in Budapest. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Wielka Synagoga w Budapeszcie", "description": "Synagoga (Budapeszt, Węgry). Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Grote Synagoge van Boedapest", "description": "Bouwwerk in Boedapest. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Gran Sinagoga de Budapest", "description": "Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "Grande synagogue de Budapest", "description": "Synagogue en Hongrie. Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Велика синагога (Будапешт)", "description": "Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Budínský hrad', 'Hrad v Budapešti. Hrad či zámek v Maďarsku — historická zastávka, která stojí za odbočku.', 47.49611, 19.03972, 'http://commons.wikimedia.org/wiki/Special:FilePath/20190502%20Zamek%20w%20Budapeszcie%200647%201862%20DxO.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20190502%20Zamek%20w%20Budapeszcie%200647%201862%20DxO.jpg"}'::text[], 4, '{"en": {"name": "Buda Castle", "description": "Castle and palace complex of the Hungarian kings in Budapest. A castle in Hungary — a historic stop worth the detour."}, "de": {"name": "Budaer Burg", "description": "Größtes Gebäude in Ungarn, Sehenswürdigkeit der Hauptstadt Budapest. Eine Burg bzw. ein Schloss in Ungarn — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Królewski w Budapeszcie", "description": "Zabytkowy zespół pałacowy w Budapeszcie, Węgy. Zamek na Węgrzech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burcht van Boeda", "description": "Bouwwerk in Boedapest. Een kasteel in Hongarije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Buda", "description": "Monumento más grande de Hungría, atracción turística de su capital Budapest. Un castillo en Hungría: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Budavár", "description": "Un château en Hongrie — une halte historique qui vaut le détour."}, "uk": {"name": "Замок Буда", "description": "Замково-палацовий комплекс угорських королів у Будапешті. Замок в Угорщині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Matyášův chrám', 'Kostel v Budapešti. Památka v Maďarsku — kus historie přímo u trasy.', 47.50194, 19.03417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Matthias%20Church%2C%20Budapest%2C%202017.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Matthias%20Church%2C%20Budapest%2C%202017.jpg"}'::text[], 5, '{"en": {"name": "Matthias Church", "description": "Roman Catholic church in Budapest, Hungary. A heritage sight in Hungary — a piece of history right on your route."}, "de": {"name": "Matthiaskirche", "description": "Kirche in Budapest. Ein Denkmal in Ungarn — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół Macieja w Budapeszcie", "description": "Świątynia katolicka. Zabytek na Węgrzech — kawałek historii tuż przy trasie."}, "nl": {"name": "Matthiaskerk", "description": "Boedapest. Een monument in Hongarije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "iglesia de Matías", "description": "Iglesia católica ubicada en Budapest. Un monumento en Hungría: un pedazo de historia junto a la ruta."}, "fr": {"name": "église Notre-Dame-de-l''Assomption de Budavár", "description": "Un monument en Hongrie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Церква Матяша", "description": "Церква в Будапешті (Угорщина). Пам''ятка в Угорщині — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Aquincum', 'Římské město a vojenský tábor v Pannonii Inferior; dnes na území Budapešti. Hrad či zámek v Maďarsku — historická zastávka, která stojí za odbočku.', 47.56414, 19.04947, 'http://commons.wikimedia.org/wiki/Special:FilePath/Polg%C3%A1rv%C3%A1ros1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Polg%C3%A1rv%C3%A1ros1.jpg"}'::text[], 6, '{"en": {"name": "Aquincum", "description": "Historical settlement in the Roman Empire. A castle in Hungary — a historic stop worth the detour."}, "de": {"name": "Aquincum", "description": "Römische Vorgängerstadt von Budapest. Eine Burg bzw. ein Schloss in Ungarn — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Aquincum", "description": "Starożytne miasto rzymskie i obóz legionów nad Dunajem. Zamek na Węgrzech — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Aquincum", "description": "Museum in Hongarije. Een kasteel in Hongarije — een historische stop die de omweg waard is."}, "es": {"name": "Aquincum", "description": "Asentamiento romano que dio origen a la ciudad de Budapest. Un castillo en Hungría: una parada histórica que merece el desvío."}, "fr": {"name": "Aquincum", "description": "Antique cité romaine sur le site de Budapest, Hongrie. Un château en Hongrie — une halte historique qui vaut le détour."}, "uk": {"name": "Аквінк", "description": "Замок в Угорщині — історична зупинка, варта об''їзду."}}'::jsonb);
