  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Letiště Lisabon-Portela', 'Letecký cíl v Portugalsku — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 38.77417, -9.13417, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aeroporto%20Lisboa%20-%20panoramio.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aeroporto%20Lisboa%20-%20panoramio.jpg"}'::text[], 0, '{"en": {"name": "Humberto Delgado Airport", "description": "International airport serving Lisbon, Portugal. An aviation sight in Portugal — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Lissabon-Humberto Delgado", "description": "Flughafen in Portugal. Ein Luftfahrt-Ziel in Portugal — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Lizbona-Portela", "description": "Cel lotniczy w Portugalii — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Aeroporto Humberto Delgado", "description": "Internationale luchthaven van Lissabon, Portugal. Een luchtvaartdoel in Portugal — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Lisboa Humberto Delgado", "description": "Infraestructura de transporte de Lisboa, Portugal. Un destino aeronáutico en Portugal: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Lisbonne-Humberto Delgado", "description": "Aéroport desservant Lisbonne, au Portugal. Un site aéronautique au Portugal — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний аеропорт «Портела»", "description": "Авіаційна пам''ятка в Португалії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Hrad svatého Jiří', 'Hrad v Lisabonu. Hrad či zámek v Portugalsku — historická zastávka, která stojí za odbočku.', 38.71389, -9.13333, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20de%20S%C3%A3o%20Jorge%20%284166049903%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20de%20S%C3%A3o%20Jorge%20%284166049903%29.jpg"}'::text[], 1, '{"en": {"name": "Castle of Saint George", "description": "Moorish castle in Lisbon, Portugal. A castle in Portugal — a historic stop worth the detour."}, "de": {"name": "Castelo de São Jorge", "description": "Burg in Portugal. Eine Burg bzw. ein Schloss in Portugal — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek św. Jerzego w Lizbonie", "description": "Zamek w Portugalii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castelo de São Jorge", "description": "Bouwwerk in Lissabon. Een kasteel in Portugal — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de San Jorge de Lisboa", "description": "Castillo en Lisboa, Portugal. Un castillo en Portugal: una parada histórica que merece el desvío."}, "fr": {"name": "château de Saint-Georges", "description": "Château mauresque à Lisbonne. Un château au Portugal — une halte historique qui vaut le détour."}, "uk": {"name": "Замок святого георгія", "description": "Замок в Португалії — історична зупинка, варта об''їзду."}}'::jsonb),
