    (v_route, 'Belémská věž', 'Opevněná věž v Lisabonu. Hrad či zámek v Portugalsku — historická zastávka, která stojí za odbočku.', 38.69139, -9.21583, 'http://commons.wikimedia.org/wiki/Special:FilePath/Belem%20Tower%20-%20April%202019%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Belem%20Tower%20-%20April%202019%20%282%29.jpg"}'::text[], 4, '{"en": {"name": "Belém Tower", "description": "Fortified tower located in the civil parish of Santa Maria de Belém in the municipality of Lisbon, Portugal. A castle in Portugal — a historic stop worth the detour."}, "de": {"name": "Torre de Belém", "description": "Wahrzeichen Lissabons. Eine Burg bzw. ein Schloss in Portugal — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Torre de Belém", "description": "Wieża warowna (Lizbona, Portugalia). Zamek w Portugalii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Torre de Belém", "description": "Bouwwerk in Lissabon. Een kasteel in Portugal — een historische stop die de omweg waard is."}, "es": {"name": "Torre de Belém", "description": "Torre de defensa militar en Lisboa. Un castillo en Portugal: una parada histórica que merece el desvío."}, "fr": {"name": "tour de Belém", "description": "Bâtiment de Santa Maria de Belém, Lisbonne, au Portugal. Un château au Portugal — une halte historique qui vaut le détour."}, "uk": {"name": "Беленська башта", "description": "Укріплена ренесансна башта в районі Белен на березі р.Тежу. Замок в Португалії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Maurský hrad', 'Středověký hrad v portugalské obci Sintra. Hrad či zámek v Portugalsku — historická zastávka, která stojí za odbočku.', 38.79254, -9.3896, 'http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20dos%20Mouros.%20Sintra%2C%20Portugal.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Castelo%20dos%20Mouros.%20Sintra%2C%20Portugal.jpg"}'::text[], 5, '{"en": {"name": "Castle of the Moors", "description": "Cultural heritage monument in Sintra, Portugal. A castle in Portugal — a historic stop worth the detour."}, "de": {"name": "Castelo dos Mouros", "description": "Burg in Portugal. Eine Burg bzw. ein Schloss in Portugal — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Maurów", "description": "Zamek w Portugalii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Castelo dos Mouros", "description": "Kasteel in Sintra, Portugal. Een kasteel in Portugal — een historische stop die de omweg waard is."}, "es": {"name": "Castelo dos Mouros (Sintra)", "description": "Un castillo en Portugal: una parada histórica que merece el desvío."}, "fr": {"name": "château des Maures", "description": "Bâtiment de Sintra, Lisbonne, au Portugal. Un château au Portugal — une halte historique qui vaut le détour."}, "uk": {"name": "Замок маврів", "description": "Замок в Португалії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Palác Mafra', 'Monumentální komplex královského paláce a kláštera s bazilikou ve stejnojmenné obci v Portugalsku. Památka v Portugalsku — kus historie přímo u trasy.', 38.93692, -9.32639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Mafra%20May%202013-2.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Mafra%20May%202013-2.jpg"}'::text[], 6, '{"en": {"name": "Palace of Mafra", "description": "Church building in Mafra, Lisbon District, Portugal. A heritage sight in Portugal — a piece of history right on your route."}, "de": {"name": "Palácio Nacional de Mafra", "description": "Schloss in Mafra, größte Schloss- und Klosteranlage Portugals, mit Museum. Ein Denkmal in Portugal — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Pałac w Mafrze", "description": "Zabytek w Portugalii — kawałek historii tuż przy trasie."}, "nl": {"name": "Paleis van Mafra", "description": "Klooster in Portugal. Een monument in Portugal — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Palacio Nacional de Mafra", "description": "Un monumento en Portugal: un pedazo de historia junto a la ruta."}, "fr": {"name": "palais National de Mafra", "description": "Palais de Mafra, Lisbonne, Portugal. Un monument au Portugal — un morceau d''histoire au bord de la route."}, "uk": {"name": "Національний палац Мафра", "description": "Пам''ятка в Португалії — шматочок історії просто на маршруті."}}'::jsonb);
