    (v_route, 'letiště Düsseldorf', 'Letecký cíl v Německu — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 51.28093, 6.75731, 'http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20D%C3%BCsseldorf%20Airport.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20image%20of%20the%20D%C3%BCsseldorf%20Airport.jpg"}'::text[], 0, '{"en": {"name": "Düsseldorf Airport", "description": "International airport of Düsseldorf. An aviation sight in Germany — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Düsseldorf", "description": "Flughafen in Deutschland. Ein Luftfahrt-Ziel in Deutschland — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Düsseldorf", "description": "Port lotniczy w Niemczech. Cel lotniczy w Niemczech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Düsseldorf International", "description": "Internationale luchthaven in Duitsland. Een luchtvaartdoel in Duitsland — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional de Düsseldorf", "description": "Aeropuerto de Alemania. Un destino aeronáutico en Alemania: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport international de Düsseldorf", "description": "Aéroport desservant Düsseldorf, en Allemagne. Un site aéronautique en Allemagne — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Міжнародний Аеропорт Дюссельдорф", "description": "Авіаційна пам''ятка в Німеччині — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Basilica of St. Quirinus', 'Památka v Německu — kus historie přímo u trasy.', 51.1991, 6.69321, 'http://commons.wikimedia.org/wiki/Special:FilePath/2009%20Turm%20Quirinusm%C3%BCnster%20Neuss.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/2009%20Turm%20Quirinusm%C3%BCnster%20Neuss.jpg"}'::text[], 1, '{"en": {"name": "Basilica of St. Quirinus", "description": "Roman-catholic church in Neuss, Northrhine-Westphalia, Germany. A heritage sight in Germany — a piece of history right on your route."}, "de": {"name": "Quirinus-Münster", "description": "Römisch-katholisches Kirchengebäude in Neuss. Ein Denkmal in Deutschland — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazylika św. Kwiryna w Neuss", "description": "Zabytek w Niemczech — kawałek historii tuż przy trasie."}, "nl": {"name": "Quirinusmunster", "description": "Kerkgebouw in Duitsland. Een monument in Duitsland — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Quirino", "description": "Templo católico que fue erigido en la ciudad de Neuss, Alemania. Un monumento en Alemania: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Quirin de Neuss", "description": "Un monument en Allemagne — un morceau d''histoire au bord de la route."}, "uk": {"name": "Basilica of St. Quirinus", "description": "Церква в Німеччині. Пам''ятка в Німеччині — шматочок історії просто на маршруті."}}'::jsonb),
