    (v_route, 'Eichener See', 'Vodní plocha v Německu — příjemný cíl vyjížďky s výhledy na hladinu.', 47.64475, 7.86211, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eiemer%20See.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eiemer%20See.JPG"}'::text[], 4, '{"en": {"name": "Eichener See", "description": "Lake in Lörrach, Baden-Württemberg, Germany. A body of water in Germany — a pleasant ride destination with waterside views."}, "de": {"name": "Eichener See", "description": "Zeitweise erscheinender See in Baden-Württemberg. Ein Gewässer in Deutschland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Eichener See", "description": "Akwen w Niemczech — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Eichener See", "description": "Meer in Duitsland. Een waterpartij in Duitsland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lago de Eichen", "description": "Lago de Alemania. Una masa de agua en Alemania: un destino agradable con vistas al agua."}, "fr": {"name": "Eichener See", "description": "Un plan d''eau en Allemagne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Eichener See", "description": "Водойма в Німеччині — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'Erdmannshöhle', 'Přírodní zajímavost v Německu — místo na protažení nohou uprostřed přírody.', 47.64916, 7.89592, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hasel%20Erdmannsh%C3%B6hle%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hasel%20Erdmannsh%C3%B6hle%201.jpg"}'::text[], 5, '{"en": {"name": "Erdmannshöhle", "description": "Cave in Germany. A natural sight in Germany — a spot to stretch your legs amid nature."}, "de": {"name": "Erdmannshöhle", "description": "Höhle in Deutschland. Eine Natursehenswürdigkeit in Deutschland — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Erdmannshöhle", "description": "Jaskinia turystyczna (Hasel, Niemcy). Atrakcja przyrodnicza w Niemczech — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Erdmannshöhle", "description": "Een natuurbezienswaardigheid in Duitsland — een plek om de benen te strekken in de natuur."}, "es": {"name": "Erdmannshöhle", "description": "Cueva de Alemania. Un paraje natural en Alemania: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Erdmannshöhle", "description": "Grotte en Allemagne. Un site naturel en Allemagne — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Erdmannshöhle", "description": "Природна пам''ятка в Німеччині — місце розім''яти ноги серед природи."}}'::jsonb),
