    (v_route, 'Letiště Nice', 'Letecký cíl ve Francii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 43.66528, 7.215, 'http://commons.wikimedia.org/wiki/Special:FilePath/A%C3%A9roport%20Nice%20vue%20a%C3%A9rienne.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/A%C3%A9roport%20Nice%20vue%20a%C3%A9rienne.jpg"}'::text[], 0, '{"en": {"name": "Nice Côte d''Azur Airport", "description": "International airport serving Côte d''Azur, France. An aviation sight in France — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Nizza", "description": "Flughafen in Frankreich. Ein Luftfahrt-Ziel in Frankreich — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Nicea-Lazurowe Wybrzeże", "description": "Cel lotniczy we Francji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Nice Côte d''Azur", "description": "Vliegveld in Alpes-Maritimes, Frankrijk. Een luchtvaartdoel in Frankrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto Internacional Niza Costa Azul", "description": "Un destino aeronáutico en Francia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Nice-Côte d''Azur", "description": "Aéroport desservant Nice (Alpes-Maritimes, Provence-Alpes-Côte d''Azur, France). Un site aéronautique en France — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Ніцца-Лазурний Берег", "description": "Авіаційна пам''ятка у Франції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Russian Orthodox Cathedral, Nice', 'Památka ve Francii — kus historie přímo u trasy.', 43.70389, 7.25389, 'http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20ortodoxe%20russe.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20ortodoxe%20russe.jpg"}'::text[], 1, '{"en": {"name": "Russian Orthodox Cathedral, Nice", "description": "Cathedral located in Alpes-Maritimes, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Russisch-orthodoxe Kathedrale", "description": "Kirchengebäude in Nizza, Département Alpes-Maritimes, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Sobór św. Mikołaja w Nicei", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Russische kerk", "description": "Nice. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral San Nicolás", "description": "Catedral situada en Alpes Marítimos, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Nicolas", "description": "Cathédrale orthodoxe russe à Nice, dans les Alpes-Maritimes, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Russian Orthodox Cathedral, Nice", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
