    (v_route, 'Grasse Cathedral', 'Památka ve Francii — kus historie přímo u trasy.', 43.65778, 6.92472, 'http://commons.wikimedia.org/wiki/Special:FilePath/Grasse%20BW%202011-06-08%2011-00-02.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Grasse%20BW%202011-06-08%2011-00-02.JPG"}'::text[], 6, '{"en": {"name": "Grasse Cathedral", "description": "Cathedral located in Alpes-Maritimes, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Kathedrale Notre-Dame-du-Puy", "description": "Kirchengebäude in Grasse, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Grasse Cathedral", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Grasse Cathedral", "description": "Kathedraal in Frankrijk. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Nuestra Señora de Le Puy", "description": "Catedral situada en Alpes Marítimos, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Notre-Dame-du-Puy de Grasse", "description": "Cathédrale située dans les Alpes-Maritimes, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Grasse Cathedral", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb);
