    (v_route, 'Letiště Linate', 'Letiště v Itálii. Letecký cíl v Itálii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 45.4609, 9.28, 'http://commons.wikimedia.org/wiki/Special:FilePath/Terminal%20Linate.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Terminal%20Linate.jpg"}'::text[], 0, '{"en": {"name": "Linate Airport", "description": "International airport serving Milan, Italy. An aviation sight in Italy — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Mailand-Linate", "description": "Flughafen in Italien. Ein Luftfahrt-Ziel in Italien — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Mediolan-Linate", "description": "Port lotniczy we Włoszech. Cel lotniczy we Włoszech — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Milaan-Linate", "description": "Vliegveld in Milaan, Italië. Een luchtvaartdoel in Italië — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Milán-Linate", "description": "Aeropuerto de Italia. Un destino aeronáutico en Italia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport de Milan Linate", "description": "Aéroport desservant Milan, en Italie. Un site aéronautique en Italie — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Аеропорт Мілан–Лінате", "description": "Авіаційна пам''ятка в Італії — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Katedrála Narození Panny Marie v Miláně', 'Katedrála v Miláně. Památka v Itálii — kus historie přímo u trasy.', 45.46397, 9.19058, 'http://commons.wikimedia.org/wiki/Special:FilePath/20110724%20Milan%20Cathedral%205260.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/20110724%20Milan%20Cathedral%205260.jpg"}'::text[], 1, '{"en": {"name": "Milan Cathedral", "description": "Cathedral church of Milan, Italy. A heritage sight in Italy — a piece of history right on your route."}, "de": {"name": "Mailänder Dom", "description": "Kirchengebäude in Mailand. Ein Denkmal in Italien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra w Mediolanie", "description": "Świątynia katolicka. Zabytek we Włoszech — kawałek historii tuż przy trasie."}, "nl": {"name": "dom van Milaan", "description": "Grootste kathedraal in Italië. Een monument in Italië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Milán", "description": "Catedral gótica, neogótica, neoclásica en la ciudad italiana de Milán. Un monumento en Italia: un pedazo de historia junto a la ruta."}, "fr": {"name": "dôme de Milan", "description": "Cathédrale de Milan, \"Duomo\", Italie. Un monument en Italie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Міланський собор", "description": "Пам''ятка в Італії — шматочок історії просто на маршруті."}}'::jsonb),
