    (v_route, 'Mogoșoaia Palace', 'Hrad či zámek v Rumunsku — historická zastávka, která stojí za odbočku.', 44.52768, 25.99271, 'http://commons.wikimedia.org/wiki/Special:FilePath/RO%20IF%20Mogosoaia%20Palace%20front.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/RO%20IF%20Mogosoaia%20Palace%20front.jpg"}'::text[], 1, '{"en": {"name": "Mogoșoaia Palace", "description": "Palace in Romania. A castle in Romania — a historic stop worth the detour."}, "de": {"name": "Schloss Mogoșoaia", "description": "Schloss in Rumänien. Eine Burg bzw. ein Schloss in Rumänien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Mogoșoaia Palace", "description": "Zamek w Rumunii — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Mogoșoaia Palace", "description": "Kasteel in Roemenië. Een kasteel in Roemenië — een historische stop die de omweg waard is."}, "es": {"name": "Mogoșoaia Palace", "description": "Un castillo en Rumanía: una parada histórica que merece el desvío."}, "fr": {"name": "palais de Mogoșoaia", "description": "Palais en Roumanie. Un château en Roumanie — une halte historique qui vaut le détour."}, "uk": {"name": "Палац Могошоая", "description": "Замок в Румунії — історична зупинка, варта об''їзду."}}'::jsonb),
