    (v_route, 'letiště Lyon-Saint-Exupéry', 'Francouzské letiště. Letecký cíl ve Francii — letadla zblízka a vůně ranveje, oblíbená motorkářská zastávka.', 45.72556, 5.08111, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vue%20a%C3%A9rienne%20d%27une%20partie%20de%20l%27a%C3%A9roport%20de%20Lyon%20Saint-Exup%C3%A9ry%20et%20de%20la%20gare%20TGV%20%28septembre%202022%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vue%20a%C3%A9rienne%20d%27une%20partie%20de%20l%27a%C3%A9roport%20de%20Lyon%20Saint-Exup%C3%A9ry%20et%20de%20la%20gare%20TGV%20%28septembre%202022%29.jpg"}'::text[], 0, '{"en": {"name": "Lyon–Saint-Exupéry Airport", "description": "International airport in Lyon, France. An aviation sight in France — aircraft up close and runway vibes, a favourite riders'' stop."}, "de": {"name": "Flughafen Lyon Saint-Exupéry", "description": "Flughafen in Frankreich. Ein Luftfahrt-Ziel in Frankreich — Flugzeuge hautnah und Flugplatz-Flair, ein beliebter Bikerstopp."}, "pl": {"name": "Port lotniczy Lyon-Saint-Exupéry", "description": "Port lotniczy we Francji. Cel lotniczy we Francji — samoloty z bliska i klimat pasa startowego, ulubiony przystanek motocyklistów."}, "nl": {"name": "Luchthaven Lyon-Saint-Exupéry", "description": "Vliegveld nabij Lyon, Frankrijk. Een luchtvaartdoel in Frankrijk — vliegtuigen van dichtbij en start­baansfeer, favoriete stop van motorrijders."}, "es": {"name": "Aeropuerto de Lyon-Saint Exupéry", "description": "Aeropuerto ubicado al este de Lyon, en el municipio de Colombier-Saugnieu, en Francia. Un destino aeronáutico en Francia: aviones de cerca y ambiente de pista, parada favorita de moteros."}, "fr": {"name": "aéroport Lyon-Saint-Exupéry", "description": "Aéroport desservant Lyon (Rhône, Auvergne-Rhône-Alpes, France). Un site aéronautique en France — des avions de près et l''ambiance des pistes, un arrêt apprécié des motards."}, "uk": {"name": "Ліон", "description": "Аеропорт у Франції. Авіаційна пам''ятка у Франції — літаки зблизька й атмосфера злітної смуги, улюблена зупинка мотоциклістів."}}'::jsonb),
    (v_route, 'Bazilika Saint-Martin d''Ainay', 'Památka ve Francii — kus historie přímo u trasy.', 45.75371, 4.82724, 'http://commons.wikimedia.org/wiki/Special:FilePath/Lyon%202e%20-%20Basilique%20Saint-Martin%20d%27Ainay%20depuis%20la%20rue%20Bourgelat%20%28mars%202019%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Lyon%202e%20-%20Basilique%20Saint-Martin%20d%27Ainay%20depuis%20la%20rue%20Bourgelat%20%28mars%202019%29.jpg"}'::text[], 1, '{"en": {"name": "Basilica of Saint-Martin d''Ainay", "description": "Church in Ainay, Lyon, France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Basilika Saint-Martin d’Ainay", "description": "Kirchengebäude in Lyon, Auvergne-Rhône-Alpes, Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Bazilika Saint-Martin d''Ainay", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Basilica of Saint-Martin d''Ainay", "description": "Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "basílica de San Martín de Ainay", "description": "Templo y monumento de Lyon, Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "basilique Saint-Martin d''Ainay", "description": "Basilique ancienne abbatiale située à Lyon. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Базиліка Сен-Мартен", "description": "Церква в Аінаї. Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'katedrála v Lyonu', 'Památka ve Francii — kus historie přímo u trasy.', 45.76083, 4.82722, 'http://commons.wikimedia.org/wiki/Special:FilePath/007.%20Photo%20prise%20depuis%20les%20toits%20de%20la%20Basilique%20Notre-Dame%20de%20Fourvi%C3%A8re.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/007.%20Photo%20prise%20depuis%20les%20toits%20de%20la%20Basilique%20Notre-Dame%20de%20Fourvi%C3%A8re.JPG"}'::text[], 2, '{"en": {"name": "Lyon Cathedral", "description": "Roman Catholic cathedral in Lyon, France, and the seat of the Archbishop of Lyon. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Kathedrale von Lyon", "description": "Kirchenbau der Stadt Lyon. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jana Chrzciciela w Lyonie", "description": "Świątynia katolicka. Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Lyon", "description": "Bouwwerk in Lyon. Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de Lyon", "description": "Catedral y primado de Lyon, Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "primatiale Saint-Jean de Lyon", "description": "Cathédrale à Lyon. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Кафедральний собор Івана Хрестителя в Ліоні", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb),
